INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u4-C1','math',6,1,'u4',2,'두 양을 차와 배로 비교하기 — 뺄셈으로 비교하면 차, 나눗셈으로 비교하면 몇 배인지 알 수 있고, 두 양이 같은 배로 늘어나면 차는 변하지만 배로 비교한 관계는 변하지 않음을 알기',ARRAY['6수04-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u4-C2','math',6,1,'u4',2,'비 알기 — 두 양의 변하지 않는 관계를 기호 ：을 써서 2：10처럼 나타내고, 「○에 대한」 쪽이 기준량(후항), 다른 쪽이 비교하는 양(전항)임을 알며, 순서를 바꾸면 다른 비가 됨을 알기',ARRAY['6수04-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u4-C3','math',6,1,'u4',3,'비율 알기 — 기준량에 대한 비교하는 양의 크기를 (비교하는 양) ÷ (기준량)으로 구해 분수나 소수로 나타내고, 비율이 1보다 클 수도 있으며 기준량이 달라도 관계가 같으면 비율이 같음을 알기',ARRAY['6수04-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u4-C4','math',6,1,'u4',4,'비율이 사용되는 경우 — 경기 결과(전체 경기 수에 대한 이긴 경기 수), 걸린 시간에 대한 이동 거리, 넓이에 대한 인구, 지도의 거리처럼 생활 속 비율을 구하고, 기준이 다른 것끼리는 수가 아니라 비율로 비교하기',ARRAY['6수04-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u4-C5','math',6,1,'u4',5,'백분율 알기 — 기준량을 100으로 할 때의 비율을 백분율이라 하고 기호 %로 나타내며, 기준량이 100인 비율로 바꾸거나 비율에 100을 곱해 백분율로 나타내고, 백분율을 분수·소수로도 바꾸기',ARRAY['6수04-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u4-C6','math',6,1,'u4',6,'백분율이 사용되는 경우 — 득표율, 이자율, 할인율(원래 가격에 대한 할인 금액), 설탕물의 진하기(설탕물 양에 대한 설탕 양)를 백분율로 구하고, 금액이나 양이 아니라 백분율로 비교하기',ARRAY['6수04-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u4-C7','math',6,1,'u4',7,'백분율로 문제 해결하기 — 이해·계획·해결·검토 네 단계로, 전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해 전체의 몇 %인 양을 구하며, 조건이 바뀌면 기준량이 무엇인지 다시 확인하고 구한 답을 비율로 만들어 검토하기',ARRAY['6수04-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X01','math',6,'u4',ARRAY['M6-1-u4-C2','M6-1-u4-C3','M6-1-u4-C4']::text[],'기준량과 비교하는 양을 바꾸어 비를 쓴다(「바닷물 양에 대한 소금 양의 비」를 150：6으로)','「○에 대한」 쪽이 기준량, 뒤에 써요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X02','math',6,'u4',ARRAY['M6-1-u4-C2']::text[],'비의 순서를 바꾸어도 같은 비라고 본다(3：4와 4：3을 같다고)','기준량이 바뀌면 다른 비') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X03','math',6,'u4',ARRAY['M6-1-u4-C1','M6-1-u4-C2','M6-1-u4-C4']::text[],'몇 배인지 비교해야 할 때 뺄셈으로 차를 구하거나, 몇 배로 늘려야 할 때 같은 수를 더한다','「몇 배」는 나눗셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X04','math',6,'u4',ARRAY['M6-1-u4-C1']::text[],'두 양이 같은 배로 늘 때 차도 그대로라고 보거나, 배 관계가 변한다고 본다','늘어나도 그대로인 것은 배') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X05','math',6,'u4',ARRAY['M6-1-u4-C3','M6-1-u4-C4','M6-1-u4-C6']::text[],'비율을 (기준량) ÷ (비교하는 양)으로 거꾸로 나눈다(9：50의 비율을 50 ÷ 9로)','비교하는 양 ÷ 기준량') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X06','math',6,'u4',ARRAY['M6-1-u4-C3']::text[],'비율은 언제나 1보다 작다고 본다(12：5의 비율 2.4를 틀렸다고)','비교하는 양이 더 크면 비율은 1보다 커요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X07','math',6,'u4',ARRAY['M6-1-u4-C2','M6-1-u4-C3','M6-1-u4-C4','M6-1-u4-C6']::text[],'전체에 대한 비에서 전체 대신 다른 한 부분을 기준량으로 쓰거나, 한 부분 대신 전체를 쓴다(남 10·여 13에서 전체에 대한 여학생 비를 13：10으로)','전체 = 부분 + 부분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X08','math',6,'u4',ARRAY['M6-1-u4-C5','M6-1-u4-C6','M6-1-u4-C7']::text[],'비율을 백분율로 바꿀 때 100이 아닌 10·1000을 곱하거나 곱하지 않는다(0.07을 70 %·0.7 %로)','비율 × 100에 % 붙이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X09','math',6,'u4',ARRAY['M6-1-u4-C5','M6-1-u4-C6']::text[],'분수를 백분율로 바꿀 때 분자를 그대로 %로 쓰는 등 기준량을 100으로 맞추지 않는다(⟨16/25⟩를 16 %로)','분모를 100으로 고쳐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X10','math',6,'u4',ARRAY['M6-1-u4-C6','M6-1-u4-C7']::text[],'할인율을 구할 때 할인 금액 대신 할인된 가격을 쓴다','할인 금액 = 원래 가격 − 할인된 가격') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X11','math',6,'u4',ARRAY['M6-1-u4-C3','M6-1-u4-C4','M6-1-u4-C5','M6-1-u4-C6','M6-1-u4-C7']::text[],'기준량이 다른데 수·금액·양의 크기만으로 비교한다(넣은 횟수·인구·할인 금액이 크면 더 잘했다·빽빽하다·싸다고)','기준이 다르면 비율로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X12','math',6,'u4',ARRAY['M6-1-u4-C6']::text[],'설탕물의 진하기를 구할 때 기준량을 설탕물 대신 물의 양으로 쓴다','설탕물 = 물 + 설탕') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X13','math',6,'u4',ARRAY['M6-1-u4-C7']::text[],'전체의 몇 %를 구할 때 %의 수를 그대로 답하거나, 전체를 %의 수로 나누거나, 한 칸(1 %)만 구하고 멈춘다','한 칸 × 칸 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X14','math',6,'u4',ARRAY['M6-1-u4-C7']::text[],'조건이 바뀌어 기준량이 달라졌는데 처음 전체를 그대로 기준량으로 쓴다(신재생 에너지의 48 %를 전체 발전량의 48 %로)','「무엇의」 몇 %인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X15','math',6,'u4',ARRAY['M6-1-u4-C1','M6-1-u4-C2','M6-1-u4-C3','M6-1-u4-C4','M6-1-u4-C5','M6-1-u4-C6','M6-1-u4-C7']::text[],'분수·소수 셈(약분·나눗셈·자릿값)을 잘못 계산한다','곱셈으로 거꾸로 확인해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X16','math',6,'u4',ARRAY['M6-1-u4-C1','M6-1-u4-C2','M6-1-u4-C3','M6-1-u4-C4','M6-1-u4-C5','M6-1-u4-C6','M6-1-u4-C7']::text[],'묻는 말을 놓친다 — 이긴 경기↔진 경기, 할인 금액↔할인된 가격, 쓴 양↔남은 양, 가장 큰↔작은','물음의 「무엇을·가장」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#1','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C1',1,'sa','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 뺄셈으로 비교하면 물은 매실 원액보다 몇 컵 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C1","difficulty":1,"kind":"sa","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 뺄셈으로 비교하면 물은 매실 원액보다 몇 컵 더 많은가요? 숫자로 쓰세요.","answer":["3"],"explanation":["뺄셈으로 비교하면 두 양의 차를 알 수 있어요.","4 − 1 = 3이에요.","물은 매실 원액보다 3컵 더 많아요."],"mis":"M6-1-u4-X16","variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 뺄셈으로 비교하면 노란 구슬은 파란 구슬보다 몇 개 더 많은가요? 숫자로 쓰세요.","answer":["8"],"explanation":["뺄셈으로 비교하면 두 양의 차를 알 수 있어요.","10 − 2 = 8이에요.","노란 구슬은 파란 구슬보다 8개 더 많아요."]},{"stem":"꽃다발 한 개에는 안개꽃 12송이와 장미 3송이가 들어가요. 뺄셈으로 비교하면 안개꽃은 장미보다 몇 송이 더 많은가요? 숫자로 쓰세요.","answer":["9"],"explanation":["뺄셈으로 비교하면 두 양의 차를 알 수 있어요.","12 − 3 = 9예요.","안개꽃은 장미보다 9송이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#2','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C1',1,'sa','auto','팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 나눗셈으로 비교하면 노란 구슬은 파란 구슬의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u4-C1","difficulty":1,"kind":"sa","stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 나눗셈으로 비교하면 노란 구슬은 파란 구슬의 몇 배인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","10 ÷ 2 = 5예요.","노란 구슬은 파란 구슬의 5배예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 나눗셈으로 비교하면 물은 매실 원액의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","4 ÷ 1 = 4예요.","물은 매실 원액의 4배예요."]},{"stem":"하늘색 물감 한 접시에는 흰색 물감 8방울과 파란색 물감 2방울이 들어가요. 나눗셈으로 비교하면 흰색 물감은 파란색 물감의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","8 ÷ 2 = 4예요.","흰색 물감은 파란색 물감의 4배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#3','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C2',1,'sa','auto','비 2：10에서 기준량은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u4-C2","difficulty":1,"kind":"sa","stem":"비 2：10에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","2：10에서 전항은 2, 후항은 10이에요.","그래서 기준량은 10이에요."],"mis":"M6-1-u4-X01","variant_rule":{"alt":[{"stem":"비 9：20에서 후항은 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","9：20에서 전항은 9, 후항은 20이에요.","그래서 후항은 20이에요."]},{"stem":"비 3：4에서 전항은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","3：4에서 전항은 3, 후항은 4예요.","그래서 전항은 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#4','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C2',1,'mc','auto','바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 어느 것인가요?',ARRAY['M6-1-u4-X01','M6-1-u4-X03']::text[],true,'{"seq":4,"concept":"M6-1-u4-C2","difficulty":1,"kind":"mc","stem":"바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 어느 것인가요?","options":[{"t":"6：150","correct":true},{"t":"150：6","mis":"M6-1-u4-X01"},{"t":"6：144","mis":"M6-1-u4-X03"},{"t":"25：1","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 바닷물 양이에요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 6：150이에요."],"variant_rule":{"alt":[{"stem":"팔찌 하나에 파란 구슬 2개와 노란 구슬 10개를 꿰어요. 파란 구슬 수와 노란 구슬 수의 비는 어느 것인가요?","options":[{"t":"2：10","correct":true},{"t":"10：2","mis":"M6-1-u4-X01"},{"t":"2：8","mis":"M6-1-u4-X03"},{"t":"5：1","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 노란 구슬 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 2：10이에요."]},{"stem":"닭 2마리와 병아리 5마리가 있어요. 닭 수에 대한 병아리 수의 비는 어느 것인가요?","options":[{"t":"5：2","correct":true},{"t":"2：5","mis":"M6-1-u4-X01"},{"t":"5：7","mis":"M6-1-u4-X07"},{"t":"3：5","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 닭 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 5：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#5','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C1',2,'mc','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 수를 늘려도 변하지 않는 비교는 어느 것인가요?',ARRAY['M6-1-u4-X04']::text[],true,'{"seq":5,"concept":"M6-1-u4-C1","difficulty":2,"kind":"mc","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 수를 늘려도 변하지 않는 비교는 어느 것인가요?","options":[{"t":"나눗셈으로 비교한 배","correct":true},{"t":"뺄셈으로 비교한 차","mis":"M6-1-u4-X04"},{"t":"물과 매실 원액을 더한 합","mis":"M6-1-u4-X04"},{"t":"매실 주스 수","mis":"M6-1-u4-X04"}],"explanation":["매실 주스 2병이면 물 8컵, 매실 원액 2컵이에요.","차는 3에서 6으로 변하지만 8 ÷ 2 = 4배는 그대로예요.","그래서 변하지 않는 비교는 나눗셈으로 비교한 배예요."],"variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 팔찌 수를 늘려도 변하지 않는 비교는 어느 것인가요?","options":[{"t":"나눗셈으로 비교한 배","correct":true},{"t":"뺄셈으로 비교한 차","mis":"M6-1-u4-X04"},{"t":"노란 구슬과 파란 구슬을 더한 합","mis":"M6-1-u4-X04"},{"t":"팔찌 수","mis":"M6-1-u4-X04"}],"explanation":["팔찌 2개이면 노란 구슬 20개, 파란 구슬 4개예요.","차는 8에서 16으로 변하지만 20 ÷ 4 = 5배는 그대로예요.","그래서 변하지 않는 비교는 나눗셈으로 비교한 배예요."]},{"stem":"하늘색 물감 한 접시에는 흰색 물감 8방울과 파란색 물감 2방울이 들어가요. 하늘색 물감 수를 늘려도 변하지 않는 비교는 어느 것인가요?","options":[{"t":"나눗셈으로 비교한 배","correct":true},{"t":"뺄셈으로 비교한 차","mis":"M6-1-u4-X04"},{"t":"흰색 물감과 파란색 물감을 더한 합","mis":"M6-1-u4-X04"},{"t":"하늘색 물감 수","mis":"M6-1-u4-X04"}],"explanation":["하늘색 물감 2접시이면 흰색 물감 16방울, 파란색 물감 4방울이에요.","차는 6에서 12로 변하지만 16 ÷ 4 = 4배는 그대로예요.","그래서 변하지 않는 비교는 나눗셈으로 비교한 배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#6','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C1',2,'sa','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 2병을 만들려면 물은 모두 몇 컵 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C1","difficulty":2,"kind":"sa","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 2병을 만들려면 물은 모두 몇 컵 필요한가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 병에 물 4컵씩 들어가요.","2병이면 4 × 2 = 8이에요.","물은 모두 8컵 필요해요."],"mis":"M6-1-u4-X04","variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 팔찌 3개를 만들려면 노란 구슬은 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["30"],"explanation":["한 개에 노란 구슬 10개씩 들어가요.","3개이면 10 × 3 = 30이에요.","노란 구슬은 모두 30개 필요해요."]},{"stem":"꽃다발 한 개에는 안개꽃 12송이와 장미 3송이가 들어가요. 꽃다발 4개를 만들려면 안개꽃은 모두 몇 송이 필요한가요? 숫자로 쓰세요.","answer":["48"],"explanation":["한 개에 안개꽃 12송이씩 들어가요.","4개이면 12 × 4 = 48이에요.","안개꽃은 모두 48송이 필요해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#7','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C2',2,'ox','auto','비 2：10에서 2는 비교하는 양, 10은 기준량이에요.',ARRAY['M6-1-u4-X01']::text[],true,'{"seq":7,"concept":"M6-1-u4-C2","difficulty":2,"kind":"ox","stem":"비 2：10에서 2는 비교하는 양, 10은 기준량이에요.","answer":"O","reason_options":[{"t":"기호 ：의 뒤에 있는 수가 기준량이기 때문에","correct":true},{"t":"큰 수가 언제나 기준량이기 때문에","mis":"M6-1-u4-X01"}],"mis":"M6-1-u4-X01","explanation":["두 양의 변하지 않는 관계를 기호 ：로 나타낸 것이 비예요.","：의 앞은 비교하는 양(전항), 뒤는 기준량(후항)이에요.","「○에 대한」 쪽이 기준량이에요."],"variant_rule":{"alt":[{"stem":"「6에 대한 5의 비」는 6：5로 써요.","answer":"X","reason_options":[{"t":"「대한」 쪽 6이 기준량이라 5：6으로 쓰기 때문에","correct":true},{"t":"앞에 나온 수를 먼저 쓰기 때문에","mis":"M6-1-u4-X01"}],"explanation":["두 양의 변하지 않는 관계를 기호 ：로 나타낸 것이 비예요.","：의 앞은 비교하는 양(전항), 뒤는 기준량(후항)이에요.","「○에 대한」 쪽이 기준량이에요."]},{"stem":"「5 대 2」와 「2에 대한 5의 비」는 같은 비예요.","answer":"O","reason_options":[{"t":"둘 다 기준량이 2인 5：2이기 때문에","correct":true},{"t":"두 말에 같은 수가 들어 있기 때문에","mis":"M6-1-u4-X01"}],"explanation":["두 양의 변하지 않는 관계를 기호 ：로 나타낸 것이 비예요.","：의 앞은 비교하는 양(전항), 뒤는 기준량(후항)이에요.","「○에 대한」 쪽이 기준량이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#8','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C2',2,'sa','auto','치즈 4장과 달걀부침 3개로 샌드위치를 만들었어요. 치즈 수에 대한 달걀부침 수의 비에서 기준량은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u4-C2","difficulty":2,"kind":"sa","stem":"치즈 4장과 달걀부침 3개로 샌드위치를 만들었어요. 치즈 수에 대한 달걀부침 수의 비에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["「치즈 수에 대한」이니 기준량은 치즈 수예요.","비는 3：4예요.","답은 4예요."],"mis":"M6-1-u4-X01","variant_rule":{"alt":[{"stem":"동전을 20번 던져 숫자 면이 9번 나왔어요. 동전을 던진 횟수에 대한 숫자 면이 나온 횟수의 비에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["「던진 횟수에 대한」이니 기준량은 던진 횟수예요.","비는 9：20이에요.","답은 20이에요."]},{"stem":"꽃밭에 튤립 8송이와 장미 15송이가 있어요. 장미 수에 대한 튤립 수의 비에서 비교하는 양은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["「장미 수에 대한」이니 기준량은 장미 수 15예요.","비교하는 양은 튤립 수라 비는 8：15예요.","답은 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#9','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C2',2,'mc','auto','3：4와 4：3에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u4-X02']::text[],true,'{"seq":9,"concept":"M6-1-u4-C2","difficulty":2,"kind":"mc","stem":"3：4와 4：3에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"기준량이 달라 서로 다른 비예요","correct":true},{"t":"같은 비예요","mis":"M6-1-u4-X02"},{"t":"두 수의 합이 같으니 같은 비예요","mis":"M6-1-u4-X02"},{"t":"순서만 다를 뿐 뜻이 같아요","mis":"M6-1-u4-X02"}],"explanation":["3：4의 기준량은 4이고 4：3의 기준량은 3이에요.","기준량이 다르면 다른 비예요.","비의 순서를 바꾸면 안 돼요."],"variant_rule":{"alt":[{"stem":"2：5와 5：2에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"기준량이 달라 서로 다른 비예요","correct":true},{"t":"같은 비예요","mis":"M6-1-u4-X02"},{"t":"두 수의 합이 같으니 같은 비예요","mis":"M6-1-u4-X02"},{"t":"순서만 다를 뿐 뜻이 같아요","mis":"M6-1-u4-X02"}],"explanation":["2：5의 기준량은 5이고 5：2의 기준량은 2예요.","기준량이 다르면 다른 비예요.","비의 순서를 바꾸면 안 돼요."]},{"stem":"7：3과 3：7에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"기준량이 달라 서로 다른 비예요","correct":true},{"t":"같은 비예요","mis":"M6-1-u4-X02"},{"t":"두 수의 합이 같으니 같은 비예요","mis":"M6-1-u4-X02"},{"t":"순서만 다를 뿐 뜻이 같아요","mis":"M6-1-u4-X02"}],"explanation":["7：3의 기준량은 3이고 3：7의 기준량은 7이에요.","기준량이 다르면 다른 비예요.","비의 순서를 바꾸면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#10','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C1',3,'sa','auto','가로 5 cm, 세로 2 cm인 직사각형을 모양 그대로 키웠더니 세로가 6 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u4-C1","difficulty":3,"kind":"sa","stem":"가로 5 cm, 세로 2 cm인 직사각형을 모양 그대로 키웠더니 세로가 6 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 6 ÷ 2 = 3배가 되었어요.","가로도 5 × 3 = 15 (cm)예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"가로 4 cm, 세로 3 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 9 ÷ 3 = 3배가 되었어요.","가로도 4 × 3 = 12 (cm)예요."]},{"stem":"가로 6 cm, 세로 4 cm인 직사각형을 모양 그대로 키웠더니 세로가 10 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 10 ÷ 4 = 2.5배가 되었어요.","가로도 6 × 2.5 = 15 (cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#1','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C1',2,'sa','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 2병을 만들 때 물과 매실 원액의 차는 몇 컵인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C1","difficulty":2,"kind":"sa","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 2병을 만들 때 물과 매실 원액의 차는 몇 컵인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["2병이면 물 8컵, 매실 원액 2컵이에요.","8 − 2 = 6이에요.","한 병일 때의 차 3과 달리 차는 6컵으로 변했어요."],"mis":"M6-1-u4-X04","variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 팔찌 3개를 만들 때 노란 구슬과 파란 구슬의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["3개이면 노란 구슬 30개, 파란 구슬 6개예요.","30 − 6 = 24예요.","한 개일 때의 차 8과 달리 차는 24개로 변했어요."]},{"stem":"하늘색 물감 한 접시에는 흰색 물감 8방울과 파란색 물감 2방울이 들어가요. 하늘색 물감 4접시를 만들 때 흰색 물감과 파란색 물감의 차는 몇 방울인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["4접시이면 흰색 물감 32방울, 파란색 물감 8방울이에요.","32 − 8 = 24예요.","한 접시일 때의 차 6과 달리 차는 24방울로 변했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#2','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C2',2,'mc','auto','비 3：5를 읽은 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-1-u4-X16','M6-1-u4-X01']::text[],true,'{"seq":2,"concept":"M6-1-u4-C2","difficulty":2,"kind":"mc","stem":"비 3：5를 읽은 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"3에 대한 5의 비","correct":true},{"t":"3 대 5","mis":"M6-1-u4-X16"},{"t":"5에 대한 3의 비","mis":"M6-1-u4-X01"},{"t":"3의 5에 대한 비","mis":"M6-1-u4-X01"}],"explanation":["3：5는 「3 대 5」라고 읽어요.","기준량이 5니 「5에 대한 3의 비」, 「3의 5에 대한 비」라고도 읽어요.","「3에 대한 5의 비」는 기준량이 3인 5：3이에요."],"variant_rule":{"alt":[{"stem":"비 4：7을 읽은 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"4에 대한 7의 비","correct":true},{"t":"4 대 7","mis":"M6-1-u4-X16"},{"t":"7에 대한 4의 비","mis":"M6-1-u4-X01"},{"t":"4의 7에 대한 비","mis":"M6-1-u4-X01"}],"explanation":["4：7은 「4 대 7」이라고 읽어요.","기준량이 7이니 「7에 대한 4의 비」, 「4의 7에 대한 비」라고도 읽어요.","「4에 대한 7의 비」는 기준량이 4인 7：4예요."]},{"stem":"비 2：9를 읽은 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"2에 대한 9의 비","correct":true},{"t":"2 대 9","mis":"M6-1-u4-X16"},{"t":"9에 대한 2의 비","mis":"M6-1-u4-X01"},{"t":"2의 9에 대한 비","mis":"M6-1-u4-X01"}],"explanation":["2：9는 「2 대 9」라고 읽어요.","기준량이 9니 「9에 대한 2의 비」, 「2의 9에 대한 비」라고도 읽어요.","「2에 대한 9의 비」는 기준량이 2인 9：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#3','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C1',3,'error','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 2병을 만드는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X04','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C1","difficulty":3,"kind":"error","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 2병을 만드는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「2병을 만들어도 물은 매실 원액보다 3컵 더 많아.」","correct":true,"mis_target":"M6-1-u4-X04"},{"t":"이현 — 「물은 8컵 필요해.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「물은 언제나 매실 원액의 4배야.」","mis":"M6-1-u4-X16"}],"explanation":["2병이면 물 8컵, 매실 원액 2컵이에요.","차는 8 − 2 = 6으로 변해요.","준희는 차가 그대로라고 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 팔찌 3개를 만드는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「3개를 만들어도 노란 구슬은 파란 구슬보다 8개 더 많아.」","correct":true,"mis_target":"M6-1-u4-X04"},{"t":"수아 — 「노란 구슬은 30개 필요해.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「노란 구슬은 언제나 파란 구슬의 5배야.」","mis":"M6-1-u4-X16"}],"explanation":["3개이면 노란 구슬 30개, 파란 구슬 6개예요.","차는 30 − 6 = 24로 변해요.","서호는 차가 그대로라고 잘못 말했어요."]},{"stem":"꽃다발 한 개에는 안개꽃 12송이와 장미 3송이가 들어가요. 꽃다발 2개를 만드는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「2개를 만들어도 안개꽃은 장미보다 9송이 더 많아.」","correct":true,"mis_target":"M6-1-u4-X04"},{"t":"나린 — 「안개꽃은 24송이 필요해.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「안개꽃은 언제나 장미의 4배야.」","mis":"M6-1-u4-X16"}],"explanation":["2개이면 안개꽃 24송이, 장미 6송이예요.","차는 24 − 6 = 18로 변해요.","가온은 차가 그대로라고 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#4','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C1',3,'ox','auto','주스를 두 병 만들면 물과 원액의 차는 그대로 3컵이에요.',ARRAY['M6-1-u4-X04']::text[],true,'{"seq":4,"concept":"M6-1-u4-C1","difficulty":3,"kind":"ox","stem":"주스를 두 병 만들면 물과 원액의 차는 그대로 3컵이에요.","answer":"X","reason_options":[{"t":"두 병이면 물 8컵, 원액 2컵이라 차는 6컵으로 변하기 때문에","correct":true},{"t":"병 수를 늘려도 차는 변하지 않기 때문에","mis":"M6-1-u4-X04"}],"mis":"M6-1-u4-X04","explanation":["두 양은 뺄셈(차)과 나눗셈(배)으로 비교할 수 있어요.","두 양이 같은 배로 늘면 차는 변해요.","그래도 나눗셈으로 비교한 배는 변하지 않아요."],"variant_rule":{"alt":[{"stem":"팔찌 3개를 만들면 노란 구슬은 파란 구슬보다 24개 더 많아요.","answer":"O","reason_options":[{"t":"노란 구슬 30개, 파란 구슬 6개라 30 − 6 = 24이기 때문에","correct":true},{"t":"팔찌 수를 늘려도 차는 8개 그대로이기 때문에","mis":"M6-1-u4-X04"}],"explanation":["두 양은 뺄셈(차)과 나눗셈(배)으로 비교할 수 있어요.","두 양이 같은 배로 늘면 차는 변해요.","그래도 나눗셈으로 비교한 배는 변하지 않아요."]},{"stem":"가로 5 cm, 세로 2 cm인 직사각형을 모양 그대로 키워 세로가 6 cm가 되면 가로는 9 cm예요.","answer":"X","reason_options":[{"t":"세로가 3배가 되었으니 가로도 3배인 15 cm이기 때문에","correct":true},{"t":"세로가 4 cm 늘었으니 가로도 4 cm 늘기 때문에","mis":"M6-1-u4-X03"}],"explanation":["두 양은 뺄셈(차)과 나눗셈(배)으로 비교할 수 있어요.","두 양이 같은 배로 늘면 차는 변해요.","그래도 나눗셈으로 비교한 배는 변하지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#5','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C2',3,'mc','auto','우리 반 남학생은 10명, 여학생은 13명이에요. 전체 학생 수에 대한 여학생 수의 비는 어느 것인가요?',ARRAY['M6-1-u4-X07','M6-1-u4-X01','M6-1-u4-X16']::text[],true,'{"seq":5,"concept":"M6-1-u4-C2","difficulty":3,"kind":"mc","stem":"우리 반 남학생은 10명, 여학생은 13명이에요. 전체 학생 수에 대한 여학생 수의 비는 어느 것인가요?","options":[{"t":"13：23","correct":true},{"t":"13：10","mis":"M6-1-u4-X07"},{"t":"23：13","mis":"M6-1-u4-X01"},{"t":"10：23","mis":"M6-1-u4-X16"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 전체 학생 수 10 + 13 = 23이에요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 13：23이에요."],"variant_rule":{"alt":[{"stem":"강아지 9마리 가운데 흰 강아지가 4마리예요. 흰색이 아닌 강아지 수에 대한 흰 강아지 수의 비는 어느 것인가요?","options":[{"t":"4：5","correct":true},{"t":"5：4","mis":"M6-1-u4-X01"},{"t":"4：9","mis":"M6-1-u4-X07"},{"t":"9：4","mis":"M6-1-u4-X07"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 흰색이 아닌 강아지 수 9 − 4 = 5예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 4：5예요."]},{"stem":"주스 8컵 가운데 5컵을 마셨어요. 처음 주스 양에 대한 마신 주스 양의 비는 어느 것인가요?","options":[{"t":"5：8","correct":true},{"t":"8：5","mis":"M6-1-u4-X01"},{"t":"5：3","mis":"M6-1-u4-X07"},{"t":"3：8","mis":"M6-1-u4-X16"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 처음 주스 양이에요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 5：8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#6','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C2',3,'sa','auto','우리 반 남학생은 10명, 여학생은 13명이에요. 여학생 수의 전체 학생 수에 대한 비에서 후항은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C2","difficulty":3,"kind":"sa","stem":"우리 반 남학생은 10명, 여학생은 13명이에요. 여학생 수의 전체 학생 수에 대한 비에서 후항은 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["후항은 기준량인 전체 학생 수예요.","전체 학생은 10 + 13 = 23(명)이라 비는 13：23이에요.","답은 23이에요."],"mis":"M6-1-u4-X07","variant_rule":{"alt":[{"stem":"바구니에 귤 12개와 사과 5개가 있어요. 전체 과일 수에 대한 귤 수의 비에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["기준량은 전체 과일 수예요.","전체 과일은 12 + 5 = 17(개)라 비는 12：17이에요.","답은 17이에요."]},{"stem":"학생 30명 가운데 안경을 쓴 학생은 7명이에요. 안경을 쓰지 않은 학생 수의 전체 학생 수에 대한 비에서 전항은 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["전항은 비교하는 양인 안경을 쓰지 않은 학생 수예요.","30 − 7 = 23(명)이라 비는 23：30이에요.","답은 23이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#7','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C2',3,'error','auto','사과 7개와 배 3개가 있어요. 배 수의 사과 수에 대한 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X01','M6-1-u4-X16']::text[],true,'{"seq":7,"concept":"M6-1-u4-C2","difficulty":3,"kind":"error","stem":"사과 7개와 배 3개가 있어요. 배 수의 사과 수에 대한 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「7：3이야.」","correct":true,"mis_target":"M6-1-u4-X01"},{"t":"이현 — 「기준량은 사과 수야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「비는 3：7이야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량은 사과 수예요.","비는 (비교하는 양)：(기준량) 차례라 3：7이에요.","준희는 기준량과 비교하는 양을 바꾸어 썼어요."],"variant_rule":{"alt":[{"stem":"치즈 4장과 달걀부침 3개로 샌드위치를 만들었어요. 치즈 수에 대한 달걀부침 수의 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「4：3이야.」","correct":true,"mis_target":"M6-1-u4-X01"},{"t":"수아 — 「기준량은 치즈 수야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「비는 3：4야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량은 치즈 수예요.","비는 (비교하는 양)：(기준량) 차례라 3：4예요.","서호는 기준량과 비교하는 양을 바꾸어 썼어요."]},{"stem":"닭 2마리와 병아리 5마리가 있어요. 닭 수에 대한 병아리 수의 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「2：5야.」","correct":true,"mis_target":"M6-1-u4-X01"},{"t":"나린 — 「기준량은 닭 수야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「비는 5：2야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량은 닭 수예요.","비는 (비교하는 양)：(기준량) 차례라 5：2예요.","가온은 기준량과 비교하는 양을 바꾸어 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#8','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C1',4,'mc','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 3병을 만들 때의 차와 배를 바르게 말한 것은 어느 것인가요?',ARRAY['M6-1-u4-X04']::text[],true,'{"seq":8,"concept":"M6-1-u4-C1","difficulty":4,"kind":"mc","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 3병을 만들 때의 차와 배를 바르게 말한 것은 어느 것인가요?","options":[{"t":"차는 9컵, 배는 4배","correct":true},{"t":"차는 3컵, 배는 4배","mis":"M6-1-u4-X04"},{"t":"차는 9컵, 배는 12배","mis":"M6-1-u4-X04"},{"t":"차는 3컵, 배는 12배","mis":"M6-1-u4-X04"}],"explanation":["3병이면 물 12컵, 매실 원액 3컵이에요.","차는 12 − 3 = 9예요.","배는 12 ÷ 3 = 4로 그대로예요."],"variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 팔찌 2개를 만들 때의 차와 배를 바르게 말한 것은 어느 것인가요?","options":[{"t":"차는 16개, 배는 5배","correct":true},{"t":"차는 8개, 배는 5배","mis":"M6-1-u4-X04"},{"t":"차는 16개, 배는 10배","mis":"M6-1-u4-X04"},{"t":"차는 8개, 배는 10배","mis":"M6-1-u4-X04"}],"explanation":["2개이면 노란 구슬 20개, 파란 구슬 4개예요.","차는 20 − 4 = 16이에요.","배는 20 ÷ 4 = 5로 그대로예요."]},{"stem":"모닝빵 반죽 한 판에는 밀가루 6컵과 우유 2컵이 들어가요. 모닝빵 반죽 3판을 만들 때의 차와 배를 바르게 말한 것은 어느 것인가요?","options":[{"t":"차는 12컵, 배는 3배","correct":true},{"t":"차는 4컵, 배는 3배","mis":"M6-1-u4-X04"},{"t":"차는 12컵, 배는 9배","mis":"M6-1-u4-X04"},{"t":"차는 4컵, 배는 9배","mis":"M6-1-u4-X04"}],"explanation":["3판이면 밀가루 18컵, 우유 6컵이에요.","차는 18 − 6 = 12예요.","배는 18 ÷ 6 = 3으로 그대로예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#9','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C2',4,'match','auto','말과 비를 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u4-C2","difficulty":4,"kind":"match","stem":"말과 비를 알맞게 이으세요.","pairs":[{"l":"4에 대한 3의 비","r":"3：4"},{"l":"3의 7에 대한 비","r":"3：7"},{"l":"7 대 4","r":"7：4"}],"mis":"M6-1-u4-X01","explanation":["「○에 대한」 쪽이 기준량이고 ：의 뒤에 써요.","4에 대한 3의 비 → 3：4, 3의 7에 대한 비 → 3：7, 7 대 4 → 7：4예요.","「대」로 읽을 때는 앞의 수부터 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 말과 비를 알맞게 이으세요.","pairs":[{"l":"5 대 2","r":"5：2"},{"l":"5에 대한 2의 비","r":"2：5"},{"l":"5의 9에 대한 비","r":"5：9"}],"explanation":["「○에 대한」 쪽이 기준량이고 ：의 뒤에 써요.","5 대 2 → 5：2, 5에 대한 2의 비 → 2：5, 5의 9에 대한 비 → 5：9예요.","「대」로 읽을 때는 앞의 수부터 써요."]},{"stem":"이번에는 다른 보기예요. 말과 비를 알맞게 이으세요.","pairs":[{"l":"6의 1에 대한 비","r":"6：1"},{"l":"1 대 6","r":"1：6"},{"l":"7에 대한 6의 비","r":"6：7"}],"explanation":["「○에 대한」 쪽이 기준량이고 ：의 뒤에 써요.","6의 1에 대한 비 → 6：1, 1 대 6 → 1：6, 7에 대한 6의 비 → 6：7이에요.","「대」로 읽을 때는 앞의 수부터 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#10','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C1',4,'essay','teacher','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 주스를 3병 만들 때 물과 원액을 뺄셈과 나눗셈으로 각각 비교하고, 병 수를 늘려도 변하지 않는 비교를 비로 나타내 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u4-C1","difficulty":4,"kind":"essay","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 주스를 3병 만들 때 물과 원액을 뺄셈과 나눗셈으로 각각 비교하고, 병 수를 늘려도 변하지 않는 비교를 비로 나타내 보세요.","answer_guide":{"answer":"예: 3병이면 물 12컵, 원액 3컵이 필요하다. 뺄셈으로 비교하면 12 − 3 = 9이므로 물이 9컵 더 많다(한 병일 때의 3컵에서 변했다). 나눗셈으로 비교하면 12 ÷ 3 = 4이므로 물은 원액의 4배이다. 병 수를 늘려도 4배는 변하지 않으므로 원액 양에 대한 물 양의 비는 4：1이다.","scoring_points":["3병일 때 물 12컵·원액 3컵을 구했는가","차 9컵과 4배를 각각 구하고 차는 변하지만 배는 그대로임을 밝혔는가","원액 양에 대한 물 양의 비를 4：1로 나타냈는가"]},"explanation":["3병이면 물 12컵, 원액 3컵이에요.","차는 9컵으로 변하지만 배는 4배 그대로예요.","원액 양에 대한 물 양의 비는 4：1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#1','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',1,'sa','auto','비 9：50에서 기준량은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C3","difficulty":1,"kind":"sa","stem":"비 9：50에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","9：50에서 전항은 9, 후항은 50이에요.","그래서 기준량은 50이에요."],"mis":"M6-1-u4-X01","variant_rule":{"alt":[{"stem":"비 12：5에서 비교하는 양은 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","12：5에서 전항은 12, 후항은 5예요.","그래서 비교하는 양은 12예요."]},{"stem":"비 3：10에서 후항은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","3：10에서 전항은 3, 후항은 10이에요.","그래서 후항은 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#2','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',1,'mc','auto','비 3：10의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X16']::text[],true,'{"seq":2,"concept":"M6-1-u4-C3","difficulty":1,"kind":"mc","stem":"비 3：10의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"3","mis":"M6-1-u4-X15"},{"t":"0.03","mis":"M6-1-u4-X15"},{"t":"0.7","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","3：10의 비율은 3 ÷ 10 = 0.3이에요.","분수로는 ⟨3/10⟩, 소수로는 0.3이에요."],"variant_rule":{"alt":[{"stem":"비 1：4의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.25","correct":true},{"t":"4","mis":"M6-1-u4-X05"},{"t":"2.5","mis":"M6-1-u4-X15"},{"t":"0.025","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","1：4의 비율은 1 ÷ 4 = 0.25예요.","분수로는 ⟨1/4⟩, 소수로는 0.25예요."]},{"stem":"비 6：5의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"1.2","correct":true},{"t":"12","mis":"M6-1-u4-X15"},{"t":"0.12","mis":"M6-1-u4-X15"},{"t":"2.2","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","6：5의 비율은 6 ÷ 5 = 1.2예요.","분수로는 ⟨6/5⟩, 소수로는 1.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#3','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',1,'mc','auto','비 9：50을 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X07','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C3","difficulty":1,"kind":"mc","stem":"비 9：50을 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨9/50⟩","correct":true},{"t":"⟨50/9⟩","mis":"M6-1-u4-X05"},{"t":"⟨9/59⟩","mis":"M6-1-u4-X07"},{"t":"⟨41/50⟩","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","비교하는 양은 9, 기준량은 50이에요.","그래서 비율은 ⟨9/50⟩예요."],"variant_rule":{"alt":[{"stem":"비 3：10을 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨3/10⟩","correct":true},{"t":"⟨10/3⟩","mis":"M6-1-u4-X05"},{"t":"⟨3/13⟩","mis":"M6-1-u4-X07"},{"t":"⟨7/10⟩","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","비교하는 양은 3, 기준량은 10이에요.","그래서 비율은 ⟨3/10⟩이에요."]},{"stem":"비 7：20을 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨7/20⟩","correct":true},{"t":"⟨20/7⟩","mis":"M6-1-u4-X05"},{"t":"⟨7/27⟩","mis":"M6-1-u4-X07"},{"t":"⟨13/20⟩","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","비교하는 양은 7, 기준량은 20이에요.","그래서 비율은 ⟨7/20⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#4','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',1,'sa','auto','비 6：5의 비율을 소수로 나타내면 1.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u4-C3","difficulty":1,"kind":"sa","stem":"비 6：5의 비율을 소수로 나타내면 1.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","6：5의 비율은 6 ÷ 5 = 1.2예요.","그래서 □는 2예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"비 3：5의 비율을 소수로 나타내면 0.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","3：5의 비율은 3 ÷ 5 = 0.6이에요.","그래서 □는 6이에요."]},{"stem":"비 7：5의 비율을 소수로 나타내면 1.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","7：5의 비율은 7 ÷ 5 = 1.4예요.","그래서 □는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#5','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',2,'mc','auto','비 12：5의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X15']::text[],true,'{"seq":5,"concept":"M6-1-u4-C3","difficulty":2,"kind":"mc","stem":"비 12：5의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"2.4","correct":true},{"t":"24","mis":"M6-1-u4-X15"},{"t":"0.24","mis":"M6-1-u4-X15"},{"t":"3.4","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","12：5의 비율은 12 ÷ 5 = 2.4예요.","분수로는 ⟨12/5⟩, 소수로는 2.4예요."],"variant_rule":{"alt":[{"stem":"비 9：50의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.18","correct":true},{"t":"1.8","mis":"M6-1-u4-X15"},{"t":"0.018","mis":"M6-1-u4-X15"},{"t":"0.82","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","9：50의 비율은 9 ÷ 50 = 0.18이에요.","분수로는 ⟨9/50⟩, 소수로는 0.18이에요."]},{"stem":"비 7：4의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"1.75","correct":true},{"t":"17.5","mis":"M6-1-u4-X15"},{"t":"0.175","mis":"M6-1-u4-X15"},{"t":"2.75","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","7：4의 비율은 7 ÷ 4 = 1.75예요.","분수로는 ⟨7/4⟩, 소수로는 1.75예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#6','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',2,'mc','auto','집에서 할머니 댁까지는 20 km, 집에서 주유소까지는 8 km예요. 집과 할머니 댁 사이 거리에 대한 집과 주유소 사이 거리의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":6,"concept":"M6-1-u4-C3","difficulty":2,"kind":"mc","stem":"집에서 할머니 댁까지는 20 km, 집에서 주유소까지는 8 km예요. 집과 할머니 댁 사이 거리에 대한 집과 주유소 사이 거리의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"2.5","mis":"M6-1-u4-X05"},{"t":"0.6","mis":"M6-1-u4-X16"},{"t":"4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 20, 비교하는 양은 8이에요.","8 ÷ 20 = 0.4예요.","그래서 비율은 0.4예요."],"variant_rule":{"alt":[{"stem":"가로 40 cm, 세로 24 cm인 태극기 액자가 있어요. 가로에 대한 세로의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.6","correct":true},{"t":"0.4","mis":"M6-1-u4-X16"},{"t":"6","mis":"M6-1-u4-X15"},{"t":"0.06","mis":"M6-1-u4-X15"}],"explanation":["기준량은 40, 비교하는 양은 24예요.","24 ÷ 40 = 0.6이에요.","그래서 비율은 0.6이에요."]},{"stem":"마을 자전거 도로 15 km 가운데 12 km가 완성되었어요. 전체 길이에 대한 완성된 길이의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"1.25","mis":"M6-1-u4-X05"},{"t":"0.2","mis":"M6-1-u4-X16"},{"t":"8","mis":"M6-1-u4-X15"}],"explanation":["기준량은 15, 비교하는 양은 12예요.","12 ÷ 15 = 0.8이에요.","그래서 비율은 0.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#7','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',2,'ox','auto','비율은 언제나 1보다 작아요.',ARRAY['M6-1-u4-X06']::text[],true,'{"seq":7,"concept":"M6-1-u4-C3","difficulty":2,"kind":"ox","stem":"비율은 언제나 1보다 작아요.","answer":"X","reason_options":[{"t":"12：5의 비율 2.4처럼 비교하는 양이 더 크면 1보다 크기 때문에","correct":true},{"t":"비율은 전체의 일부만 나타내기 때문에","mis":"M6-1-u4-X06"}],"mis":"M6-1-u4-X06","explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."],"variant_rule":{"alt":[{"stem":"15：25와 30：50은 비율이 같아요.","answer":"O","reason_options":[{"t":"15 ÷ 25 = 0.6이고 30 ÷ 50 = 0.6이기 때문에","correct":true},{"t":"두 비 모두 전항이 후항보다 작기 때문에","mis":"M6-1-u4-X11"}],"explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."]},{"stem":"⟨3/10⟩과 0.3은 같은 비율이에요.","answer":"O","reason_options":[{"t":"⟨3/10⟩ = 0.3이기 때문에","correct":true},{"t":"두 수에 모두 3이 들어 있기 때문에","mis":"M6-1-u4-X15"}],"explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#8','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',2,'mc','auto','비율이 1보다 큰 비는 어느 것인가요?',ARRAY['M6-1-u4-X01']::text[],true,'{"seq":8,"concept":"M6-1-u4-C3","difficulty":2,"kind":"mc","stem":"비율이 1보다 큰 비는 어느 것인가요?","options":[{"t":"12：5","correct":true},{"t":"3：5","mis":"M6-1-u4-X01"},{"t":"9：50","mis":"M6-1-u4-X01"},{"t":"4：7","mis":"M6-1-u4-X01"}],"explanation":["비교하는 양이 기준량보다 크면 비율은 1보다 커요.","3：5 → 0.6, 12：5 → 2.4, 9：50 → 0.18, 4：7 → ⟨4/7⟩예요.","1보다 큰 것은 12：5예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비율이 1보다 큰 비는 어느 것인가요?","options":[{"t":"7：4","correct":true},{"t":"2：9","mis":"M6-1-u4-X01"},{"t":"5：8","mis":"M6-1-u4-X01"},{"t":"1：3","mis":"M6-1-u4-X01"}],"explanation":["비교하는 양이 기준량보다 크면 비율은 1보다 커요.","7：4 → 1.75, 2：9 → ⟨2/9⟩, 5：8 → 0.625, 1：3 → ⟨1/3⟩이에요.","1보다 큰 것은 7：4예요."]},{"stem":"이번에는 다른 보기예요. 비율이 1보다 큰 비는 어느 것인가요?","options":[{"t":"11：6","correct":true},{"t":"9：10","mis":"M6-1-u4-X01"},{"t":"3：8","mis":"M6-1-u4-X01"},{"t":"6：11","mis":"M6-1-u4-X01"}],"explanation":["비교하는 양이 기준량보다 크면 비율은 1보다 커요.","9：10 → 0.9, 3：8 → 0.375, 11：6 → ⟨11/6⟩, 6：11 → ⟨6/11⟩이에요.","1보다 큰 것은 11：6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#9','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',2,'match','auto','비와 비율을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u4-C3","difficulty":2,"kind":"match","stem":"비와 비율을 알맞게 이으세요.","pairs":[{"l":"3：10","r":"0.3"},{"l":"12：5","r":"2.4"},{"l":"9：50","r":"0.18"}],"mis":"M6-1-u4-X05","explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","3 ÷ 10 = 0.3, 12 ÷ 5 = 2.4, 9 ÷ 50 = 0.18이에요.","：의 뒤에 있는 수로 나누어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비와 비율을 알맞게 이으세요.","pairs":[{"l":"1：4","r":"0.25"},{"l":"6：5","r":"1.2"},{"l":"7：20","r":"0.35"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","1 ÷ 4 = 0.25, 6 ÷ 5 = 1.2, 7 ÷ 20 = 0.35예요.","：의 뒤에 있는 수로 나누어요."]},{"stem":"이번에는 다른 보기예요. 비와 비율을 알맞게 이으세요.","pairs":[{"l":"3：5","r":"0.6"},{"l":"7：4","r":"1.75"},{"l":"9：10","r":"0.9"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","3 ÷ 5 = 0.6, 7 ÷ 4 = 1.75, 9 ÷ 10 = 0.9예요.","：의 뒤에 있는 수로 나누어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#10','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',3,'mc','auto','가 직사각형은 가로 10 cm, 세로 6 cm이고 나 직사각형은 가로 15 cm, 세로 9 cm예요. 가로에 대한 세로의 비율을 비교하면 어떤가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X11']::text[],true,'{"seq":10,"concept":"M6-1-u4-C3","difficulty":3,"kind":"mc","stem":"가 직사각형은 가로 10 cm, 세로 6 cm이고 나 직사각형은 가로 15 cm, 세로 9 cm예요. 가로에 대한 세로의 비율을 비교하면 어떤가요?","options":[{"t":"두 비율은 같아요","correct":true},{"t":"가의 비율이 더 커요","mis":"M6-1-u4-X15"},{"t":"나의 비율이 더 커요","mis":"M6-1-u4-X11"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["가는 6 ÷ 10 = 0.6이에요.","나는 9 ÷ 15 = 0.6이에요.","그래서 두 비율은 같아요."],"variant_rule":{"alt":[{"stem":"가 직사각형은 가로 8 cm, 세로 6 cm이고 나 직사각형은 가로 10 cm, 세로 7 cm예요. 가로에 대한 세로의 비율을 비교하면 어떤가요?","options":[{"t":"가의 비율이 더 커요","correct":true},{"t":"두 비율은 같아요","mis":"M6-1-u4-X11"},{"t":"나의 비율이 더 커요","mis":"M6-1-u4-X11"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["가는 6 ÷ 8 = 0.75예요.","나는 7 ÷ 10 = 0.7이에요.","그래서 가의 비율이 더 커요."]},{"stem":"가 직사각형은 가로 20 cm, 세로 12 cm이고 나 직사각형은 가로 25 cm, 세로 16 cm예요. 가로에 대한 세로의 비율을 비교하면 어떤가요?","options":[{"t":"나의 비율이 더 커요","correct":true},{"t":"두 비율은 같아요","mis":"M6-1-u4-X11"},{"t":"가의 비율이 더 커요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["가는 12 ÷ 20 = 0.6이에요.","나는 16 ÷ 25 = 0.64예요.","그래서 나의 비율이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#1','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',2,'sa','auto','집에서 할머니 댁까지는 20 km, 집에서 주유소까지는 8 km예요. 집과 할머니 댁 사이 거리에 대한 집과 주유소 사이 거리의 비율을 소수로 나타내면 0.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C3","difficulty":2,"kind":"sa","stem":"집에서 할머니 댁까지는 20 km, 집에서 주유소까지는 8 km예요. 집과 할머니 댁 사이 거리에 대한 집과 주유소 사이 거리의 비율을 소수로 나타내면 0.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["기준량은 20, 비교하는 양은 8이에요.","8 ÷ 20 = 0.4예요.","□는 4예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"버스 정원 45명 가운데 36명이 탔어요. 정원에 대한 탄 사람 수의 비율을 소수로 나타내면 0.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["기준량은 45, 비교하는 양은 36이에요.","36 ÷ 45 = 0.8이에요.","□는 8이에요."]},{"stem":"높이 150 cm인 나무의 그림자 길이가 90 cm예요. 나무 높이에 대한 그림자 길이의 비율을 소수로 나타내면 0.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["기준량은 150, 비교하는 양은 90이에요.","90 ÷ 150 = 0.6이에요.","□는 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#2','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',2,'mc','auto','비 21：25의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X16']::text[],true,'{"seq":2,"concept":"M6-1-u4-C3","difficulty":2,"kind":"mc","stem":"비 21：25의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.84","correct":true},{"t":"8.4","mis":"M6-1-u4-X15"},{"t":"0.084","mis":"M6-1-u4-X15"},{"t":"0.16","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","21：25의 비율은 21 ÷ 25 = 0.84예요.","분수로는 ⟨21/25⟩, 소수로는 0.84예요."],"variant_rule":{"alt":[{"stem":"비 7：8의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.875","correct":true},{"t":"8.75","mis":"M6-1-u4-X15"},{"t":"0.0875","mis":"M6-1-u4-X15"},{"t":"0.125","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","7：8의 비율은 7 ÷ 8 = 0.875예요.","분수로는 ⟨7/8⟩, 소수로는 0.875예요."]},{"stem":"비 9：4의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"2.25","correct":true},{"t":"22.5","mis":"M6-1-u4-X15"},{"t":"0.225","mis":"M6-1-u4-X15"},{"t":"3.25","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","9：4의 비율은 9 ÷ 4 = 2.25예요.","분수로는 ⟨9/4⟩, 소수로는 2.25예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#3','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',3,'error','auto','비 9：50의 비율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C3","difficulty":3,"kind":"error","stem":"비 9：50의 비율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「50 ÷ 9 = ⟨50/9⟩이야.」","correct":true,"mis_target":"M6-1-u4-X05"},{"t":"이현 — 「기준량은 50이야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「비율은 0.18이야.」","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","9 ÷ 50 = 0.18이에요.","준희는 기준량을 비교하는 양으로 나누었어요."],"variant_rule":{"alt":[{"stem":"비 3：4의 비율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「4 ÷ 3 = ⟨4/3⟩야.」","correct":true,"mis_target":"M6-1-u4-X05"},{"t":"수아 — 「기준량은 4야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「비율은 0.75야.」","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","3 ÷ 4 = 0.75예요.","서호는 기준량을 비교하는 양으로 나누었어요."]},{"stem":"비 12：5의 비율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「5 ÷ 12 = ⟨5/12⟩야.」","correct":true,"mis_target":"M6-1-u4-X05"},{"t":"나린 — 「기준량은 5야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「비율은 2.4야.」","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","12 ÷ 5 = 2.4예요.","가온은 기준량을 비교하는 양으로 나누었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#4','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',3,'ox','auto','비 9：50의 비율은 50 ÷ 9로 구해요.',ARRAY['M6-1-u4-X05']::text[],true,'{"seq":4,"concept":"M6-1-u4-C3","difficulty":3,"kind":"ox","stem":"비 9：50의 비율은 50 ÷ 9로 구해요.","answer":"X","reason_options":[{"t":"비율은 비교하는 양을 기준량으로 나누어 9 ÷ 50으로 구하기 때문에","correct":true},{"t":"큰 수를 작은 수로 나누어야 하기 때문에","mis":"M6-1-u4-X05"}],"mis":"M6-1-u4-X05","explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."],"variant_rule":{"alt":[{"stem":"비 12：5의 비율은 2.4예요.","answer":"O","reason_options":[{"t":"12 ÷ 5 = 2.4이기 때문에","correct":true},{"t":"비율은 큰 수를 작은 수로 나눈 것이기 때문에","mis":"M6-1-u4-X05"}],"explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."]},{"stem":"기준량이 다르면 비율은 언제나 달라요.","answer":"X","reason_options":[{"t":"6：10과 30：50처럼 기준량이 달라도 비율이 같을 수 있기 때문에","correct":true},{"t":"기준량이 다르면 관계도 달라지기 때문에","mis":"M6-1-u4-X11"}],"explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#5','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',3,'mc','auto','비율이 15：25와 같은 비는 어느 것인가요?',ARRAY['M6-1-u4-X02','M6-1-u4-X04','M6-1-u4-X15']::text[],true,'{"seq":5,"concept":"M6-1-u4-C3","difficulty":3,"kind":"mc","stem":"비율이 15：25와 같은 비는 어느 것인가요?","options":[{"t":"6：10","correct":true},{"t":"25：15","mis":"M6-1-u4-X02"},{"t":"20：30","mis":"M6-1-u4-X04"},{"t":"5：15","mis":"M6-1-u4-X15"}],"explanation":["15：25의 비율은 15 ÷ 25 = 0.6이에요.","6：10의 비율도 6 ÷ 10 = 0.6이에요.","기준량이 달라도 관계가 같으면 비율이 같아요."],"variant_rule":{"alt":[{"stem":"비율이 3：4와 같은 비는 어느 것인가요?","options":[{"t":"12：16","correct":true},{"t":"4：3","mis":"M6-1-u4-X02"},{"t":"5：6","mis":"M6-1-u4-X04"},{"t":"6：12","mis":"M6-1-u4-X15"}],"explanation":["3：4의 비율은 3 ÷ 4 = 0.75예요.","12：16의 비율도 12 ÷ 16 = 0.75예요.","기준량이 달라도 관계가 같으면 비율이 같아요."]},{"stem":"비율이 2：5와 같은 비는 어느 것인가요?","options":[{"t":"8：20","correct":true},{"t":"5：2","mis":"M6-1-u4-X02"},{"t":"4：7","mis":"M6-1-u4-X04"},{"t":"8：10","mis":"M6-1-u4-X15"}],"explanation":["2：5의 비율은 2 ÷ 5 = 0.4예요.","8：20의 비율도 8 ÷ 20 = 0.4예요.","기준량이 달라도 관계가 같으면 비율이 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#6','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',3,'mc','auto','세계 환경의 날 기념 행사에 어린이 50명이 지원해서 9명이 당첨되었어요. 지원한 어린이 수에 대한 당첨된 어린이 수의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":6,"concept":"M6-1-u4-C3","difficulty":3,"kind":"mc","stem":"세계 환경의 날 기념 행사에 어린이 50명이 지원해서 9명이 당첨되었어요. 지원한 어린이 수에 대한 당첨된 어린이 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.18","correct":true},{"t":"0.82","mis":"M6-1-u4-X16"},{"t":"1.8","mis":"M6-1-u4-X15"},{"t":"0.018","mis":"M6-1-u4-X15"}],"explanation":["기준량은 50, 비교하는 양은 9예요.","9 ÷ 50 = 0.18이에요.","그래서 비율은 0.18이에요."],"variant_rule":{"alt":[{"stem":"높이 150 cm인 나무의 그림자 길이가 90 cm예요. 나무 높이에 대한 그림자 길이의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.6","correct":true},{"t":"0.4","mis":"M6-1-u4-X16"},{"t":"6","mis":"M6-1-u4-X15"},{"t":"0.06","mis":"M6-1-u4-X15"}],"explanation":["기준량은 150, 비교하는 양은 90이에요.","90 ÷ 150 = 0.6이에요.","그래서 비율은 0.6이에요."]},{"stem":"버스 정원 45명 가운데 36명이 탔어요. 정원에 대한 탄 사람 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"1.25","mis":"M6-1-u4-X05"},{"t":"0.2","mis":"M6-1-u4-X16"},{"t":"8","mis":"M6-1-u4-X15"}],"explanation":["기준량은 45, 비교하는 양은 36이에요.","36 ÷ 45 = 0.8이에요.","그래서 비율은 0.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#7','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',3,'mc','auto','가 직사각형은 가로 16 cm, 세로 12 cm이고 나 직사각형은 가로 20 cm, 세로 15 cm예요. 가로에 대한 세로의 비율을 비교하면 어떤가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X11']::text[],true,'{"seq":7,"concept":"M6-1-u4-C3","difficulty":3,"kind":"mc","stem":"가 직사각형은 가로 16 cm, 세로 12 cm이고 나 직사각형은 가로 20 cm, 세로 15 cm예요. 가로에 대한 세로의 비율을 비교하면 어떤가요?","options":[{"t":"두 비율은 같아요","correct":true},{"t":"가의 비율이 더 커요","mis":"M6-1-u4-X15"},{"t":"나의 비율이 더 커요","mis":"M6-1-u4-X11"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["가는 12 ÷ 16 = 0.75예요.","나는 15 ÷ 20 = 0.75예요.","그래서 두 비율은 같아요."],"variant_rule":{"alt":[{"stem":"가 직사각형은 가로 5 cm, 세로 4 cm이고 나 직사각형은 가로 10 cm, 세로 7 cm예요. 가로에 대한 세로의 비율을 비교하면 어떤가요?","options":[{"t":"가의 비율이 더 커요","correct":true},{"t":"두 비율은 같아요","mis":"M6-1-u4-X11"},{"t":"나의 비율이 더 커요","mis":"M6-1-u4-X11"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["가는 4 ÷ 5 = 0.8이에요.","나는 7 ÷ 10 = 0.7이에요.","그래서 가의 비율이 더 커요."]},{"stem":"가 직사각형은 가로 25 cm, 세로 10 cm이고 나 직사각형은 가로 20 cm, 세로 9 cm예요. 가로에 대한 세로의 비율을 비교하면 어떤가요?","options":[{"t":"나의 비율이 더 커요","correct":true},{"t":"두 비율은 같아요","mis":"M6-1-u4-X11"},{"t":"가의 비율이 더 커요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["가는 10 ÷ 25 = 0.4예요.","나는 9 ÷ 20 = 0.45예요.","그래서 나의 비율이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#8','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',4,'mc','auto','비율이 1보다 큰 비는 어느 것인가요?',ARRAY['M6-1-u4-X01']::text[],true,'{"seq":8,"concept":"M6-1-u4-C3","difficulty":4,"kind":"mc","stem":"비율이 1보다 큰 비는 어느 것인가요?","options":[{"t":"9：8","correct":true},{"t":"15：25","mis":"M6-1-u4-X01"},{"t":"49：50","mis":"M6-1-u4-X01"},{"t":"30：50","mis":"M6-1-u4-X01"}],"explanation":["비교하는 양이 기준량보다 크면 비율은 1보다 커요.","15：25 → 0.6, 9：8 → 1.125, 49：50 → 0.98, 30：50 → 0.6이에요.","1보다 큰 것은 9：8이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비율이 1보다 큰 비는 어느 것인가요?","options":[{"t":"13：12","correct":true},{"t":"99：100","mis":"M6-1-u4-X01"},{"t":"21：25","mis":"M6-1-u4-X01"},{"t":"40：45","mis":"M6-1-u4-X01"}],"explanation":["비교하는 양이 기준량보다 크면 비율은 1보다 커요.","99：100 → 0.99, 21：25 → 0.84, 13：12 → ⟨13/12⟩, 40：45 → ⟨8/9⟩이에요.","1보다 큰 것은 13：12예요."]},{"stem":"이번에는 다른 보기예요. 비율이 1보다 큰 비는 어느 것인가요?","options":[{"t":"25：24","correct":true},{"t":"7：21","mis":"M6-1-u4-X01"},{"t":"24：25","mis":"M6-1-u4-X01"},{"t":"1：2","mis":"M6-1-u4-X01"}],"explanation":["비교하는 양이 기준량보다 크면 비율은 1보다 커요.","7：21 → ⟨1/3⟩, 25：24 → ⟨25/24⟩, 24：25 → 0.96, 1：2 → 0.5예요.","1보다 큰 것은 25：24예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#9','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',4,'mc','auto','비 36：45를 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X07','M6-1-u4-X16']::text[],true,'{"seq":9,"concept":"M6-1-u4-C3","difficulty":4,"kind":"mc","stem":"비 36：45를 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨36/45⟩","correct":true},{"t":"⟨45/36⟩","mis":"M6-1-u4-X05"},{"t":"⟨36/81⟩","mis":"M6-1-u4-X07"},{"t":"⟨9/45⟩","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","비교하는 양은 36, 기준량은 45예요.","그래서 비율은 ⟨36/45⟩이에요."],"variant_rule":{"alt":[{"stem":"비 21：28을 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨21/28⟩","correct":true},{"t":"⟨28/21⟩","mis":"M6-1-u4-X05"},{"t":"⟨21/49⟩","mis":"M6-1-u4-X07"},{"t":"⟨7/28⟩","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","비교하는 양은 21, 기준량은 28이에요.","그래서 비율은 ⟨21/28⟩이에요."]},{"stem":"비 14：35를 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨14/35⟩","correct":true},{"t":"⟨35/14⟩","mis":"M6-1-u4-X05"},{"t":"⟨14/49⟩","mis":"M6-1-u4-X07"},{"t":"⟨21/35⟩","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","비교하는 양은 14, 기준량은 35예요.","그래서 비율은 ⟨14/35⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#10','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',4,'essay','teacher','가로에 대한 세로의 비가 15：25, 30：50, 6：10인 세 직사각형이 있어요. 세 비율을 소수로 구해 비교하고, 기준량이 다른데도 비율이 같은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u4-C3","difficulty":4,"kind":"essay","stem":"가로에 대한 세로의 비가 15：25, 30：50, 6：10인 세 직사각형이 있어요. 세 비율을 소수로 구해 비교하고, 기준량이 다른데도 비율이 같은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 15 ÷ 25 = 0.6, 30 ÷ 50 = 0.6, 6 ÷ 10 = 0.6이므로 세 비율은 모두 0.6으로 같다. 세 직사각형은 크기는 다르지만 가로에 대한 세로의 관계(세로가 가로의 0.6배)가 같아서, 기준량이 달라도 비율이 같다.","scoring_points":["세 비율을 0.6으로 구했는가","세 비율이 같다고 비교했는가","관계가 같으면 기준량이 달라도 비율이 같다고 설명했는가"]},"explanation":["세 비율은 모두 0.6이에요.","크기는 달라도 모양(관계)이 같아요.","그래서 기준량이 달라도 비율이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#1','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',1,'mc','auto','넓이에 대한 인구의 비율에서 기준량은 무엇인가요?',ARRAY['M6-1-u4-X01','M6-1-u4-X07','M6-1-u4-X03']::text[],true,'{"seq":1,"concept":"M6-1-u4-C4","difficulty":1,"kind":"mc","stem":"넓이에 대한 인구의 비율에서 기준량은 무엇인가요?","options":[{"t":"넓이","correct":true},{"t":"인구","mis":"M6-1-u4-X01"},{"t":"넓이와 인구의 합","mis":"M6-1-u4-X07"},{"t":"인구와 넓이의 차","mis":"M6-1-u4-X03"}],"explanation":["「넓이에 대한」이니 기준량은 넓이예요.","비율은 (비교하는 양) ÷ (기준량)으로 구해요.","기준량을 바꾸면 전혀 다른 비율이 돼요."],"variant_rule":{"alt":[{"stem":"이동한 시간에 대한 이동한 거리의 비율에서 기준량은 무엇인가요?","options":[{"t":"이동한 시간","correct":true},{"t":"이동한 거리","mis":"M6-1-u4-X01"},{"t":"시간과 거리의 합","mis":"M6-1-u4-X07"},{"t":"거리와 시간의 차","mis":"M6-1-u4-X03"}],"explanation":["「이동한 시간에 대한」이니 기준량은 이동한 시간이에요.","비율은 (비교하는 양) ÷ (기준량)으로 구해요.","기준량을 바꾸면 전혀 다른 비율이 돼요."]},{"stem":"전체 경기 수에 대한 이긴 경기 수의 비율에서 비교하는 양은 무엇인가요?","options":[{"t":"이긴 경기 수","correct":true},{"t":"전체 경기 수","mis":"M6-1-u4-X01"},{"t":"진 경기 수","mis":"M6-1-u4-X16"},{"t":"전체 경기 수와 이긴 경기 수의 차","mis":"M6-1-u4-X03"}],"explanation":["「전체 경기 수에 대한」 쪽이 기준량이고 다른 쪽 이긴 경기 수가 비교하는 양이에요.","비율은 (비교하는 양) ÷ (기준량)으로 구해요.","기준량을 바꾸면 전혀 다른 비율이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#2','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',1,'mc','auto','푸른 팀은 15경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":2,"concept":"M6-1-u4-C4","difficulty":1,"kind":"mc","stem":"푸른 팀은 15경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"2.5","mis":"M6-1-u4-X05"},{"t":"0.6","mis":"M6-1-u4-X16"},{"t":"4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 15, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/15⟩ = 0.4예요.","푸른 팀의 비율은 0.4예요."],"variant_rule":{"alt":[{"stem":"노란 팀은 20경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"0.7","mis":"M6-1-u4-X16"},{"t":"3","mis":"M6-1-u4-X15"},{"t":"0.03","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 20, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/20⟩ = 0.3이에요.","노란 팀의 비율은 0.3이에요."]},{"stem":"초록 팀은 10경기를 치러서 5경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.5","correct":true},{"t":"2","mis":"M6-1-u4-X05"},{"t":"1","mis":"M6-1-u4-X07"},{"t":"5","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 10, 비교하는 양은 이긴 경기 수 5예요.","⟨5/10⟩ = 0.5예요.","초록 팀의 비율은 0.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#3','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',1,'sa','auto','자율 주행 자동차가 2시간 동안 160 km를 이동했어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u4-C4","difficulty":1,"kind":"sa","stem":"자율 주행 자동차가 2시간 동안 160 km를 이동했어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["기준량은 이동한 시간 2, 비교하는 양은 이동한 거리 160이에요.","160 ÷ 2 = 80이에요.","1시간에 80 km만큼 이동한 셈이에요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"자전거로 3시간 동안 12 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["기준량은 이동한 시간 3, 비교하는 양은 이동한 거리 12예요.","12 ÷ 3 = 4예요.","1시간에 4 km만큼 이동한 셈이에요."]},{"stem":"산책로를 2시간 동안 8 km 걸었어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["기준량은 이동한 시간 2, 비교하는 양은 이동한 거리 8이에요.","8 ÷ 2 = 4예요.","1시간에 4 km만큼 이동한 셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#4','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',1,'ox','auto','2시간 동안 160 km를 갔다면 이동한 시간에 대한 이동한 거리의 비율은 80이에요.',ARRAY['M6-1-u4-X03']::text[],true,'{"seq":4,"concept":"M6-1-u4-C4","difficulty":1,"kind":"ox","stem":"2시간 동안 160 km를 갔다면 이동한 시간에 대한 이동한 거리의 비율은 80이에요.","answer":"O","reason_options":[{"t":"160 ÷ 2 = 80이기 때문에","correct":true},{"t":"160과 2를 비교하면 차가 80쯤이기 때문에","mis":"M6-1-u4-X03"}],"mis":"M6-1-u4-X03","explanation":["비율은 경기 결과·빠르기·인구·지도처럼 생활 곳곳에 쓰여요.","먼저 「○에 대한」으로 기준량을 찾아요.","기준이 다른 것끼리는 수가 아니라 비율로 비교해요."],"variant_rule":{"alt":[{"stem":"넓이에 대한 인구의 비율이 클수록 사람이 빽빽하게 살아요.","answer":"O","reason_options":[{"t":"1 km²에 사는 사람이 더 많다는 뜻이기 때문에","correct":true},{"t":"넓이가 넓을수록 비율이 크기 때문에","mis":"M6-1-u4-X05"}],"explanation":["비율은 경기 결과·빠르기·인구·지도처럼 생활 곳곳에 쓰여요.","먼저 「○에 대한」으로 기준량을 찾아요.","기준이 다른 것끼리는 수가 아니라 비율로 비교해요."]},{"stem":"지도에서 1 cm가 실제 300 m이면 지도의 2 cm는 실제 600 m예요.","answer":"O","reason_options":[{"t":"300 × 2 = 600이기 때문에","correct":true},{"t":"300에 2를 더하기 때문에","mis":"M6-1-u4-X03"}],"explanation":["비율은 경기 결과·빠르기·인구·지도처럼 생활 곳곳에 쓰여요.","먼저 「○에 대한」으로 기준량을 찾아요.","기준이 다른 것끼리는 수가 아니라 비율로 비교해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#5','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',2,'mc','auto','가 마을은 넓이 2 km²에 6000명이 살아요. 넓이에 대한 인구의 비율은 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X15']::text[],true,'{"seq":5,"concept":"M6-1-u4-C4","difficulty":2,"kind":"mc","stem":"가 마을은 넓이 2 km²에 6000명이 살아요. 넓이에 대한 인구의 비율은 얼마인가요?","options":[{"t":"3000","correct":true},{"t":"⟨2/6000⟩","mis":"M6-1-u4-X05"},{"t":"12000","mis":"M6-1-u4-X15"},{"t":"30000","mis":"M6-1-u4-X15"}],"explanation":["기준량은 넓이 2, 비교하는 양은 인구 6000이에요.","6000 ÷ 2 = 3000이에요.","1 km²에 3000명꼴로 사는 셈이에요."],"variant_rule":{"alt":[{"stem":"나 마을은 넓이 3 km²에 7500명이 살아요. 넓이에 대한 인구의 비율은 얼마인가요?","options":[{"t":"2500","correct":true},{"t":"⟨3/7500⟩","mis":"M6-1-u4-X05"},{"t":"22500","mis":"M6-1-u4-X15"},{"t":"25000","mis":"M6-1-u4-X15"}],"explanation":["기준량은 넓이 3, 비교하는 양은 인구 7500이에요.","7500 ÷ 3 = 2500이에요.","1 km²에 2500명꼴로 사는 셈이에요."]},{"stem":"다 마을은 넓이 4 km²에 10000명이 살아요. 넓이에 대한 인구의 비율은 얼마인가요?","options":[{"t":"2500","correct":true},{"t":"⟨4/10000⟩","mis":"M6-1-u4-X05"},{"t":"40000","mis":"M6-1-u4-X15"},{"t":"25000","mis":"M6-1-u4-X15"}],"explanation":["기준량은 넓이 4, 비교하는 양은 인구 10000이에요.","10000 ÷ 4 = 2500이에요.","1 km²에 2500명꼴로 사는 셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#6','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',2,'mc','auto','푸른 팀은 15경기 중 6경기를, 초록 팀은 10경기 중 5경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율이 더 큰 팀은 어느 팀인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":6,"concept":"M6-1-u4-C4","difficulty":2,"kind":"mc","stem":"푸른 팀은 15경기 중 6경기를, 초록 팀은 10경기 중 5경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율이 더 큰 팀은 어느 팀인가요?","options":[{"t":"초록 팀","correct":true},{"t":"푸른 팀","mis":"M6-1-u4-X11"},{"t":"두 팀이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["치른 경기 수가 다르니 이긴 경기 수가 아니라 비율로 비교해요.","푸른 팀 6 ÷ 15 = 0.4, 초록 팀 5 ÷ 10 = 0.5예요.","비율이 더 큰 팀은 초록 팀이에요."],"variant_rule":{"alt":[{"stem":"하늘 팀은 20경기 중 12경기를, 바다 팀은 8경기 중 5경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율이 더 큰 팀은 어느 팀인가요?","options":[{"t":"바다 팀","correct":true},{"t":"하늘 팀","mis":"M6-1-u4-X11"},{"t":"두 팀이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["치른 경기 수가 다르니 이긴 경기 수가 아니라 비율로 비교해요.","하늘 팀 12 ÷ 20 = 0.6, 바다 팀 5 ÷ 8 = 0.625예요.","비율이 더 큰 팀은 바다 팀이에요."]},{"stem":"빨강 팀은 40경기 중 26경기를, 주황 팀은 20경기 중 14경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율이 더 큰 팀은 어느 팀인가요?","options":[{"t":"주황 팀","correct":true},{"t":"빨강 팀","mis":"M6-1-u4-X11"},{"t":"두 팀이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["치른 경기 수가 다르니 이긴 경기 수가 아니라 비율로 비교해요.","빨강 팀 26 ÷ 40 = 0.65, 주황 팀 14 ÷ 20 = 0.7이에요.","비율이 더 큰 팀은 주황 팀이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#7','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',2,'sa','auto','어떤 지도에서 1 cm는 실제 거리 25 m를 나타내요. 지도에서 3 cm인 두 곳 사이의 실제 거리는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u4-C4","difficulty":2,"kind":"sa","stem":"어떤 지도에서 1 cm는 실제 거리 25 m를 나타내요. 지도에서 3 cm인 두 곳 사이의 실제 거리는 몇 m인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["지도 거리에 대한 실제 거리의 비율은 25예요.","3 cm이면 25 × 3 = 75예요.","실제 거리는 75 m예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"어떤 지도에서 1 cm는 실제 거리 20 m를 나타내요. 지도에서 4 cm인 두 곳 사이의 실제 거리는 몇 m인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["지도 거리에 대한 실제 거리의 비율은 20이에요.","4 cm이면 20 × 4 = 80이에요.","실제 거리는 80 m예요."]},{"stem":"어떤 지도에서 1 cm는 실제 거리 15 m를 나타내요. 지도에서 6 cm인 두 곳 사이의 실제 거리는 몇 m인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["지도 거리에 대한 실제 거리의 비율은 15예요.","6 cm이면 15 × 6 = 90이에요.","실제 거리는 90 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#8','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',2,'mc','auto','가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":8,"concept":"M6-1-u4-C4","difficulty":2,"kind":"mc","stem":"가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"가 마을","correct":true},{"t":"나 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","가 6000 ÷ 2 = 3000, 나 7500 ÷ 3 = 2500이에요.","비율이 큰 가 마을이 더 빽빽해요."],"variant_rule":{"alt":[{"stem":"다 마을은 넓이 4 km²에 10000명, 라 마을은 넓이 5 km²에 11000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"다 마을","correct":true},{"t":"라 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","다 10000 ÷ 4 = 2500, 라 11000 ÷ 5 = 2200이에요.","비율이 큰 다 마을이 더 빽빽해요."]},{"stem":"바 마을은 넓이 4 km²에 7200명, 마 마을은 넓이 6 km²에 9000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"바 마을","correct":true},{"t":"마 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","바 7200 ÷ 4 = 1800, 마 9000 ÷ 6 = 1500이에요.","비율이 큰 바 마을이 더 빽빽해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#9','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',2,'ox','auto','인구가 더 많은 마을이 언제나 더 빽빽해요.',ARRAY['M6-1-u4-X11']::text[],true,'{"seq":9,"concept":"M6-1-u4-C4","difficulty":2,"kind":"ox","stem":"인구가 더 많은 마을이 언제나 더 빽빽해요.","answer":"X","reason_options":[{"t":"넓이가 다르면 넓이에 대한 인구의 비율로 비교해야 하기 때문에","correct":true},{"t":"사람이 많으면 땅이 좁아 보이기 때문에","mis":"M6-1-u4-X11"}],"mis":"M6-1-u4-X11","explanation":["비율은 경기 결과·빠르기·인구·지도처럼 생활 곳곳에 쓰여요.","먼저 「○에 대한」으로 기준량을 찾아요.","기준이 다른 것끼리는 수가 아니라 비율로 비교해요."],"variant_rule":{"alt":[{"stem":"이긴 경기 수가 많은 팀이 언제나 이긴 경기의 비율도 높아요.","answer":"X","reason_options":[{"t":"치른 경기 수가 다르면 비율이 달라지기 때문에","correct":true},{"t":"이긴 경기 수가 곧 비율이기 때문에","mis":"M6-1-u4-X11"}],"explanation":["비율은 경기 결과·빠르기·인구·지도처럼 생활 곳곳에 쓰여요.","먼저 「○에 대한」으로 기준량을 찾아요.","기준이 다른 것끼리는 수가 아니라 비율로 비교해요."]},{"stem":"이동한 시간에 대한 이동한 거리의 비율은 (이동한 시간) ÷ (이동한 거리)로 구해요.","answer":"X","reason_options":[{"t":"기준량인 시간으로 거리를 나누어야 하기 때문에","correct":true},{"t":"앞에 나온 양을 먼저 쓰기 때문에","mis":"M6-1-u4-X05"}],"explanation":["비율은 경기 결과·빠르기·인구·지도처럼 생활 곳곳에 쓰여요.","먼저 「○에 대한」으로 기준량을 찾아요.","기준이 다른 것끼리는 수가 아니라 비율로 비교해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#10','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',3,'mc','auto','가 자동차는 3시간 동안 240 km, 나 자동차는 2시간 동안 170 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율로 비교할 때 더 빠른 자동차는 어느 것인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":10,"concept":"M6-1-u4-C4","difficulty":3,"kind":"mc","stem":"가 자동차는 3시간 동안 240 km, 나 자동차는 2시간 동안 170 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율로 비교할 때 더 빠른 자동차는 어느 것인가요?","options":[{"t":"나 자동차","correct":true},{"t":"가 자동차","mis":"M6-1-u4-X11"},{"t":"두 자동차가 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["걸린 시간이 다르니 간 거리가 아니라 비율로 비교해요.","가 240 ÷ 3 = 80, 나 170 ÷ 2 = 85예요.","1시간에 더 멀리 가는 것은 나 자동차예요."],"variant_rule":{"alt":[{"stem":"다 자동차는 4시간 동안 200 km, 라 자동차는 3시간 동안 180 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율로 비교할 때 더 빠른 자동차는 어느 것인가요?","options":[{"t":"라 자동차","correct":true},{"t":"다 자동차","mis":"M6-1-u4-X11"},{"t":"두 자동차가 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["걸린 시간이 다르니 간 거리가 아니라 비율로 비교해요.","다 200 ÷ 4 = 50, 라 180 ÷ 3 = 60이에요.","1시간에 더 멀리 가는 것은 라 자동차예요."]},{"stem":"마 자동차는 5시간 동안 300 km, 바 자동차는 2시간 동안 130 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율로 비교할 때 더 빠른 자동차는 어느 것인가요?","options":[{"t":"바 자동차","correct":true},{"t":"마 자동차","mis":"M6-1-u4-X11"},{"t":"두 자동차가 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["걸린 시간이 다르니 간 거리가 아니라 비율로 비교해요.","마 300 ÷ 5 = 60, 바 130 ÷ 2 = 65예요.","1시간에 더 멀리 가는 것은 바 자동차예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#1','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',2,'sa','auto','기차가 2시간 동안 180 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C4","difficulty":2,"kind":"sa","stem":"기차가 2시간 동안 180 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["기준량은 이동한 시간 2, 비교하는 양은 이동한 거리 180이에요.","180 ÷ 2 = 90이에요.","1시간에 90 km만큼 이동한 셈이에요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"유람선이 4시간 동안 36 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["기준량은 이동한 시간 4, 비교하는 양은 이동한 거리 36이에요.","36 ÷ 4 = 9예요.","1시간에 9 km만큼 이동한 셈이에요."]},{"stem":"자전거로 5시간 동안 60 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["기준량은 이동한 시간 5, 비교하는 양은 이동한 거리 60이에요.","60 ÷ 5 = 12예요.","1시간에 12 km만큼 이동한 셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#2','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',2,'mc','auto','어떤 지도에서 1 cm는 실제 거리 300 m를 나타내요. 지도에서 3 cm인 두 곳 사이의 실제 거리는 몇 m인가요?',ARRAY['M6-1-u4-X03','M6-1-u4-X05','M6-1-u4-X15']::text[],true,'{"seq":2,"concept":"M6-1-u4-C4","difficulty":2,"kind":"mc","stem":"어떤 지도에서 1 cm는 실제 거리 300 m를 나타내요. 지도에서 3 cm인 두 곳 사이의 실제 거리는 몇 m인가요?","options":[{"t":"900 m","correct":true},{"t":"303 m","mis":"M6-1-u4-X03"},{"t":"100 m","mis":"M6-1-u4-X05"},{"t":"9000 m","mis":"M6-1-u4-X15"}],"explanation":["1 cm가 300 m니 몇 cm인지만큼 곱해요.","300 × 3 = 900이에요.","실제 거리는 900 m예요."],"variant_rule":{"alt":[{"stem":"어떤 지도에서 1 cm는 실제 거리 250 m를 나타내요. 지도에서 4 cm인 두 곳 사이의 실제 거리는 몇 m인가요?","options":[{"t":"1000 m","correct":true},{"t":"254 m","mis":"M6-1-u4-X03"},{"t":"62.5 m","mis":"M6-1-u4-X05"},{"t":"10000 m","mis":"M6-1-u4-X15"}],"explanation":["1 cm가 250 m니 몇 cm인지만큼 곱해요.","250 × 4 = 1000이에요.","실제 거리는 1000 m예요."]},{"stem":"어떤 지도에서 1 cm는 실제 거리 150 m를 나타내요. 지도에서 6 cm인 두 곳 사이의 실제 거리는 몇 m인가요?","options":[{"t":"900 m","correct":true},{"t":"156 m","mis":"M6-1-u4-X03"},{"t":"25 m","mis":"M6-1-u4-X05"},{"t":"9000 m","mis":"M6-1-u4-X15"}],"explanation":["1 cm가 150 m니 몇 cm인지만큼 곱해요.","150 × 6 = 900이에요.","실제 거리는 900 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#3','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',3,'error','auto','가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C4","difficulty":3,"kind":"error","stem":"가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「사람이 더 많은 나 마을이 더 빽빽해.」","correct":true,"mis_target":"M6-1-u4-X11"},{"t":"이현 — 「가 마을의 넓이에 대한 인구의 비율은 3000이야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「가 마을이 더 빽빽해.」","mis":"M6-1-u4-X16"}],"explanation":["넓이가 다르니 비율로 비교해요.","가 3000, 나 2500이에요.","준희는 인구 수만 보고 비교했어요."],"variant_rule":{"alt":[{"stem":"다 마을은 넓이 4 km²에 10000명, 라 마을은 넓이 5 km²에 11000명이 살아요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「사람이 더 많은 라 마을이 더 빽빽해.」","correct":true,"mis_target":"M6-1-u4-X11"},{"t":"수아 — 「다 마을의 넓이에 대한 인구의 비율은 2500이야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「다 마을이 더 빽빽해.」","mis":"M6-1-u4-X16"}],"explanation":["넓이가 다르니 비율로 비교해요.","다 2500, 라 2200이에요.","서호는 인구 수만 보고 비교했어요."]},{"stem":"바 마을은 넓이 4 km²에 7200명, 마 마을은 넓이 6 km²에 9000명이 살아요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「사람이 더 많은 마 마을이 더 빽빽해.」","correct":true,"mis_target":"M6-1-u4-X11"},{"t":"나린 — 「바 마을의 넓이에 대한 인구의 비율은 1800이야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「바 마을이 더 빽빽해.」","mis":"M6-1-u4-X16"}],"explanation":["넓이가 다르니 비율로 비교해요.","바 1800, 마 1500이에요.","가온은 인구 수만 보고 비교했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#4','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',3,'mc','auto','하늘 팀은 25경기를 치러서 16경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":4,"concept":"M6-1-u4-C4","difficulty":3,"kind":"mc","stem":"하늘 팀은 25경기를 치러서 16경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.64","correct":true},{"t":"1.5625","mis":"M6-1-u4-X05"},{"t":"0.36","mis":"M6-1-u4-X16"},{"t":"6.4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 25, 비교하는 양은 이긴 경기 수 16이에요.","⟨16/25⟩ = 0.64예요.","하늘 팀의 비율은 0.64예요."],"variant_rule":{"alt":[{"stem":"빨강 팀은 8경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.75","correct":true},{"t":"0.25","mis":"M6-1-u4-X16"},{"t":"3","mis":"M6-1-u4-X07"},{"t":"7.5","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 8, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/8⟩ = 0.75예요.","빨강 팀의 비율은 0.75예요."]},{"stem":"주황 팀은 40경기를 치러서 14경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.35","correct":true},{"t":"0.65","mis":"M6-1-u4-X16"},{"t":"3.5","mis":"M6-1-u4-X15"},{"t":"0.035","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 40, 비교하는 양은 이긴 경기 수 14예요.","⟨14/40⟩ = 0.35예요.","주황 팀의 비율은 0.35예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#5','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',3,'mc','auto','노란 팀은 20경기 중 6경기를, 파란 팀은 10경기 중 4경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율이 더 큰 팀은 어느 팀인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":5,"concept":"M6-1-u4-C4","difficulty":3,"kind":"mc","stem":"노란 팀은 20경기 중 6경기를, 파란 팀은 10경기 중 4경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율이 더 큰 팀은 어느 팀인가요?","options":[{"t":"파란 팀","correct":true},{"t":"노란 팀","mis":"M6-1-u4-X11"},{"t":"두 팀이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["치른 경기 수가 다르니 이긴 경기 수가 아니라 비율로 비교해요.","노란 팀 6 ÷ 20 = 0.3, 파란 팀 4 ÷ 10 = 0.4예요.","비율이 더 큰 팀은 파란 팀이에요."],"variant_rule":{"alt":[{"stem":"보라 팀은 50경기 중 28경기를, 초록 팀은 25경기 중 15경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율이 더 큰 팀은 어느 팀인가요?","options":[{"t":"초록 팀","correct":true},{"t":"보라 팀","mis":"M6-1-u4-X11"},{"t":"두 팀이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["치른 경기 수가 다르니 이긴 경기 수가 아니라 비율로 비교해요.","보라 팀 28 ÷ 50 = 0.56, 초록 팀 15 ÷ 25 = 0.6이에요.","비율이 더 큰 팀은 초록 팀이에요."]},{"stem":"하얀 팀은 16경기 중 12경기를, 까만 팀은 30경기 중 21경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율이 더 큰 팀은 어느 팀인가요?","options":[{"t":"하얀 팀","correct":true},{"t":"까만 팀","mis":"M6-1-u4-X11"},{"t":"두 팀이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["치른 경기 수가 다르니 이긴 경기 수가 아니라 비율로 비교해요.","하얀 팀 12 ÷ 16 = 0.75, 까만 팀 21 ÷ 30 = 0.7이에요.","비율이 더 큰 팀은 하얀 팀이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#6','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',3,'mc','auto','라 마을은 넓이 5 km²에 11000명이 살아요. 넓이에 대한 인구의 비율은 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X15']::text[],true,'{"seq":6,"concept":"M6-1-u4-C4","difficulty":3,"kind":"mc","stem":"라 마을은 넓이 5 km²에 11000명이 살아요. 넓이에 대한 인구의 비율은 얼마인가요?","options":[{"t":"2200","correct":true},{"t":"⟨5/11000⟩","mis":"M6-1-u4-X05"},{"t":"55000","mis":"M6-1-u4-X15"},{"t":"22000","mis":"M6-1-u4-X15"}],"explanation":["기준량은 넓이 5, 비교하는 양은 인구 11000이에요.","11000 ÷ 5 = 2200이에요.","1 km²에 2200명꼴로 사는 셈이에요."],"variant_rule":{"alt":[{"stem":"마 마을은 넓이 6 km²에 9000명이 살아요. 넓이에 대한 인구의 비율은 얼마인가요?","options":[{"t":"1500","correct":true},{"t":"⟨6/9000⟩","mis":"M6-1-u4-X05"},{"t":"54000","mis":"M6-1-u4-X15"},{"t":"15000","mis":"M6-1-u4-X15"}],"explanation":["기준량은 넓이 6, 비교하는 양은 인구 9000이에요.","9000 ÷ 6 = 1500이에요.","1 km²에 1500명꼴로 사는 셈이에요."]},{"stem":"바 마을은 넓이 4 km²에 7200명이 살아요. 넓이에 대한 인구의 비율은 얼마인가요?","options":[{"t":"1800","correct":true},{"t":"⟨4/7200⟩","mis":"M6-1-u4-X05"},{"t":"28800","mis":"M6-1-u4-X15"},{"t":"18000","mis":"M6-1-u4-X15"}],"explanation":["기준량은 넓이 4, 비교하는 양은 인구 7200이에요.","7200 ÷ 4 = 1800이에요.","1 km²에 1800명꼴로 사는 셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#7','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',3,'mc','auto','가 자동차는 4시간 동안 320 km, 나 자동차는 3시간 동안 255 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율로 비교할 때 더 빠른 자동차는 어느 것인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":7,"concept":"M6-1-u4-C4","difficulty":3,"kind":"mc","stem":"가 자동차는 4시간 동안 320 km, 나 자동차는 3시간 동안 255 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율로 비교할 때 더 빠른 자동차는 어느 것인가요?","options":[{"t":"나 자동차","correct":true},{"t":"가 자동차","mis":"M6-1-u4-X11"},{"t":"두 자동차가 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["걸린 시간이 다르니 간 거리가 아니라 비율로 비교해요.","가 320 ÷ 4 = 80, 나 255 ÷ 3 = 85예요.","1시간에 더 멀리 가는 것은 나 자동차예요."],"variant_rule":{"alt":[{"stem":"다 자동차는 2시간 동안 150 km, 라 자동차는 5시간 동안 350 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율로 비교할 때 더 빠른 자동차는 어느 것인가요?","options":[{"t":"다 자동차","correct":true},{"t":"라 자동차","mis":"M6-1-u4-X11"},{"t":"두 자동차가 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["걸린 시간이 다르니 간 거리가 아니라 비율로 비교해요.","다 150 ÷ 2 = 75, 라 350 ÷ 5 = 70이에요.","1시간에 더 멀리 가는 것은 다 자동차예요."]},{"stem":"마 자동차는 6시간 동안 420 km, 바 자동차는 4시간 동안 300 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율로 비교할 때 더 빠른 자동차는 어느 것인가요?","options":[{"t":"바 자동차","correct":true},{"t":"마 자동차","mis":"M6-1-u4-X11"},{"t":"두 자동차가 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["걸린 시간이 다르니 간 거리가 아니라 비율로 비교해요.","마 420 ÷ 6 = 70, 바 300 ÷ 4 = 75예요.","1시간에 더 멀리 가는 것은 바 자동차예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#8','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',4,'mc','auto','사 마을은 넓이 8 km²에 12000명, 아 마을은 넓이 5 km²에 8000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":8,"concept":"M6-1-u4-C4","difficulty":4,"kind":"mc","stem":"사 마을은 넓이 8 km²에 12000명, 아 마을은 넓이 5 km²에 8000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"아 마을","correct":true},{"t":"사 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","사 12000 ÷ 8 = 1500, 아 8000 ÷ 5 = 1600이에요.","비율이 큰 아 마을이 더 빽빽해요."],"variant_rule":{"alt":[{"stem":"자 마을은 넓이 12 km²에 30000명, 차 마을은 넓이 10 km²에 26000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"차 마을","correct":true},{"t":"자 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","자 30000 ÷ 12 = 2500, 차 26000 ÷ 10 = 2600이에요.","비율이 큰 차 마을이 더 빽빽해요."]},{"stem":"카 마을은 넓이 7 km²에 14000명, 타 마을은 넓이 9 km²에 16200명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"카 마을","correct":true},{"t":"타 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","카 14000 ÷ 7 = 2000, 타 16200 ÷ 9 = 1800이에요.","비율이 큰 카 마을이 더 빽빽해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#9','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',4,'sa','auto','어떤 지도에서 1 cm는 실제 거리 12 m를 나타내요. 지도에서 8 cm인 두 곳 사이의 실제 거리는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u4-C4","difficulty":4,"kind":"sa","stem":"어떤 지도에서 1 cm는 실제 거리 12 m를 나타내요. 지도에서 8 cm인 두 곳 사이의 실제 거리는 몇 m인가요? 숫자로 쓰세요.","answer":["96"],"explanation":["지도 거리에 대한 실제 거리의 비율은 12예요.","8 cm이면 12 × 8 = 96이에요.","실제 거리는 96 m예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"어떤 지도에서 1 cm는 실제 거리 30 m를 나타내요. 지도에서 3 cm인 두 곳 사이의 실제 거리는 몇 m인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["지도 거리에 대한 실제 거리의 비율은 30이에요.","3 cm이면 30 × 3 = 90이에요.","실제 거리는 90 m예요."]},{"stem":"어떤 지도에서 1 cm는 실제 거리 16 m를 나타내요. 지도에서 5 cm인 두 곳 사이의 실제 거리는 몇 m인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["지도 거리에 대한 실제 거리의 비율은 16이에요.","5 cm이면 16 × 5 = 80이에요.","실제 거리는 80 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#10','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',4,'essay','teacher','가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 「나 마을이 사람이 더 많으니 더 빽빽하다」는 말이 맞는지 넓이에 대한 인구의 비율을 구해 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u4-C4","difficulty":4,"kind":"essay","stem":"가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 「나 마을이 사람이 더 많으니 더 빽빽하다」는 말이 맞는지 넓이에 대한 인구의 비율을 구해 설명해 보세요.","answer_guide":{"answer":"예: 맞지 않다. 가 마을은 6000 ÷ 2 = 3000, 나 마을은 7500 ÷ 3 = 2500이다. 1 km²에 사는 사람이 가 마을이 더 많으므로 가 마을이 더 빽빽하다. 넓이가 다르면 인구 수가 아니라 넓이에 대한 인구의 비율로 비교해야 한다.","scoring_points":["3000과 2500을 구했는가","가 마을이 더 빽빽하다고 답했는가","기준(넓이)이 다르면 비율로 비교해야 한다고 썼는가"]},"explanation":["가 3000, 나 2500이에요.","가 마을이 더 빽빽해요.","넓이가 다르면 비율로 비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#1','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',1,'mc','auto','비율 0.35를 백분율로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":1,"concept":"M6-1-u4-C5","difficulty":1,"kind":"mc","stem":"비율 0.35를 백분율로 나타내면 얼마인가요?","options":[{"t":"35 %","correct":true},{"t":"3.5 %","mis":"M6-1-u4-X08"},{"t":"0.35 %","mis":"M6-1-u4-X08"},{"t":"350 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.35 × 100 = 35예요.","그래서 35 %예요."],"variant_rule":{"alt":[{"stem":"비율 0.83을 백분율로 나타내면 얼마인가요?","options":[{"t":"83 %","correct":true},{"t":"8.3 %","mis":"M6-1-u4-X08"},{"t":"0.83 %","mis":"M6-1-u4-X08"},{"t":"830 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.83 × 100 = 83이에요.","그래서 83 %예요."]},{"stem":"비율 0.6을 백분율로 나타내면 얼마인가요?","options":[{"t":"60 %","correct":true},{"t":"6 %","mis":"M6-1-u4-X08"},{"t":"0.6 %","mis":"M6-1-u4-X08"},{"t":"600 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.6 × 100 = 60이에요.","그래서 60 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#2','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',1,'ox','auto','비율 0.35는 35 %예요.',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":2,"concept":"M6-1-u4-C5","difficulty":1,"kind":"ox","stem":"비율 0.35는 35 %예요.","answer":"O","reason_options":[{"t":"0.35 × 100 = 35이기 때문에","correct":true},{"t":"소수점 뒤의 수가 35이기 때문에","mis":"M6-1-u4-X08"}],"mis":"M6-1-u4-X08","explanation":["기준량을 100으로 할 때의 비율을 백분율이라 하고 %를 써요.","비율에 100을 곱해서 나온 값에 %를 붙여요.","기준량이 100인 분수로 바꾸어도 돼요."],"variant_rule":{"alt":[{"stem":"백분율은 기준량을 100으로 할 때의 비율이에요.","answer":"O","reason_options":[{"t":"기준을 100으로 통일하면 분자만 견주면 되기 때문에","correct":true},{"t":"100은 언제나 비교하는 양이기 때문에","mis":"M6-1-u4-X01"}],"explanation":["기준량을 100으로 할 때의 비율을 백분율이라 하고 %를 써요.","비율에 100을 곱해서 나온 값에 %를 붙여요.","기준량이 100인 분수로 바꾸어도 돼요."]},{"stem":"100 %는 비율 1과 같아요.","answer":"O","reason_options":[{"t":"1 × 100 = 100이기 때문에","correct":true},{"t":"100은 1보다 크기 때문에","mis":"M6-1-u4-X08"}],"explanation":["기준량을 100으로 할 때의 비율을 백분율이라 하고 %를 써요.","비율에 100을 곱해서 나온 값에 %를 붙여요.","기준량이 100인 분수로 바꾸어도 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#3','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',1,'mc','auto','45 %를 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":3,"concept":"M6-1-u4-C5","difficulty":1,"kind":"mc","stem":"45 %를 소수로 나타내면 얼마인가요?","options":[{"t":"0.45","correct":true},{"t":"4.5","mis":"M6-1-u4-X08"},{"t":"0.045","mis":"M6-1-u4-X08"},{"t":"45","mis":"M6-1-u4-X08"}],"explanation":["45 %는 기준량이 100일 때 45라는 뜻이에요.","⟨45/100⟩ = 0.45예요.","그래서 소수로 0.45예요."],"variant_rule":{"alt":[{"stem":"8 %를 소수로 나타내면 얼마인가요?","options":[{"t":"0.08","correct":true},{"t":"0.8","mis":"M6-1-u4-X08"},{"t":"0.008","mis":"M6-1-u4-X08"},{"t":"8","mis":"M6-1-u4-X08"}],"explanation":["8 %는 기준량이 100일 때 8라는 뜻이에요.","⟨8/100⟩ = 0.08이에요.","그래서 소수로 0.08이에요."]},{"stem":"60 %를 소수로 나타내면 얼마인가요?","options":[{"t":"0.6","correct":true},{"t":"6","mis":"M6-1-u4-X08"},{"t":"0.06","mis":"M6-1-u4-X08"},{"t":"60","mis":"M6-1-u4-X08"}],"explanation":["60 %는 기준량이 100일 때 60라는 뜻이에요.","⟨60/100⟩ = 0.6이에요.","그래서 소수로 0.6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#4','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',1,'sa','auto','비율 0.83을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u4-C5","difficulty":1,"kind":"sa","stem":"비율 0.83을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["83"],"explanation":["비율에 100을 곱해요.","0.83 × 100 = 83이에요.","0.83은 백분율로 83 %예요."],"mis":"M6-1-u4-X08","variant_rule":{"alt":[{"stem":"비율 0.47을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["47"],"explanation":["비율에 100을 곱해요.","0.47 × 100 = 47이에요.","0.47은 백분율로 47 %예요."]},{"stem":"비율 0.9를 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["비율에 100을 곱해요.","0.9 × 100 = 90이에요.","0.9는 백분율로 90 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#5','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',2,'sa','auto','우리 반 20명 가운데 15명이 이번 주에 도서관을 이용했어요. 전체 학생 수에 대한 이용한 학생 수의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"우리 반 20명 가운데 15명이 이번 주에 도서관을 이용했어요. 전체 학생 수에 대한 이용한 학생 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["기준량은 20, 비교하는 양은 15예요.","15 ÷ 20 × 100 = 75예요.","그래서 75 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"전체 25칸인 모눈에서 16칸을 색칠했어요. 전체 모눈 수에 대한 색칠한 모눈 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["기준량은 25, 비교하는 양은 16이에요.","16 ÷ 25 × 100 = 64예요.","그래서 64 %예요."]},{"stem":"투호 놀이에서 화살 10개를 던져 7개를 넣었어요. 던진 화살 수에 대한 넣은 화살 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["기준량은 10, 비교하는 양은 7이에요.","7 ÷ 10 × 100 = 70이에요.","그래서 70 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#6','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',2,'sa','auto','비율 ⟨16/25⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"비율 ⟨16/25⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 4를 곱해요.","⟨16/25⟩ = ⟨64/100⟩예요.","그래서 ⟨16/25⟩은 64 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"비율 ⟨3/4⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 25를 곱해요.","⟨3/4⟩ = ⟨75/100⟩예요.","그래서 ⟨3/4⟩은 75 %예요."]},{"stem":"비율 ⟨9/20⟩를 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 5를 곱해요.","⟨9/20⟩ = ⟨45/100⟩예요.","그래서 ⟨9/20⟩는 45 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#7','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',2,'mc','auto','비율 0.07을 백분율로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":7,"concept":"M6-1-u4-C5","difficulty":2,"kind":"mc","stem":"비율 0.07을 백분율로 나타내면 얼마인가요?","options":[{"t":"7 %","correct":true},{"t":"0.7 %","mis":"M6-1-u4-X08"},{"t":"0.07 %","mis":"M6-1-u4-X08"},{"t":"70 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.07 × 100 = 7이에요.","그래서 7 %예요."],"variant_rule":{"alt":[{"stem":"비율 0.04를 백분율로 나타내면 얼마인가요?","options":[{"t":"4 %","correct":true},{"t":"0.4 %","mis":"M6-1-u4-X08"},{"t":"0.04 %","mis":"M6-1-u4-X08"},{"t":"40 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.04 × 100 = 4예요.","그래서 4 %예요."]},{"stem":"비율 0.012를 백분율로 나타내면 얼마인가요?","options":[{"t":"1.2 %","correct":true},{"t":"0.12 %","mis":"M6-1-u4-X08"},{"t":"0.012 %","mis":"M6-1-u4-X08"},{"t":"12 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.012 × 100 = 1.2예요.","그래서 1.2 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#8','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',2,'match','auto','비율과 백분율을 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u4-C5","difficulty":2,"kind":"match","stem":"비율과 백분율을 알맞게 이으세요.","pairs":[{"l":"0.35","r":"35 %"},{"l":"⟨3/4⟩","r":"75 %"},{"l":"0.07","r":"7 %"}],"mis":"M6-1-u4-X08","explanation":["비율에 100을 곱해 %를 붙여요.","0.35 → 35 %, ⟨3/4⟩ → 75 %, 0.07 → 7 %예요.","분수는 분모를 100으로 고쳐도 돼요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비율과 백분율을 알맞게 이으세요.","pairs":[{"l":"⟨1/2⟩","r":"50 %"},{"l":"0.08","r":"8 %"},{"l":"0.8","r":"80 %"}],"explanation":["비율에 100을 곱해 %를 붙여요.","⟨1/2⟩ → 50 %, 0.08 → 8 %, 0.8 → 80 %예요.","분수는 분모를 100으로 고쳐도 돼요."]},{"stem":"이번에는 다른 보기예요. 비율과 백분율을 알맞게 이으세요.","pairs":[{"l":"⟨9/20⟩","r":"45 %"},{"l":"1","r":"100 %"},{"l":"0.04","r":"4 %"}],"explanation":["비율에 100을 곱해 %를 붙여요.","⟨9/20⟩ → 45 %, 1 → 100 %, 0.04 → 4 %예요.","분수는 분모를 100으로 고쳐도 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#9','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',2,'mc','auto','나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":9,"concept":"M6-1-u4-C5","difficulty":2,"kind":"mc","stem":"나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"동생","correct":true},{"t":"나","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","나 12 ÷ 25 × 100 = 48, 동생 10 ÷ 20 × 100 = 50이에요.","나 48 %, 동생 50 % — 동생이 더 잘 넣었어요."],"variant_rule":{"alt":[{"stem":"나는 공을 40번 차서 26번 넣었고, 동생은 20번 차서 14번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"동생","correct":true},{"t":"나","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","나 26 ÷ 40 × 100 = 65, 동생 14 ÷ 20 × 100 = 70이에요.","나 65 %, 동생 70 % — 동생이 더 잘 넣었어요."]},{"stem":"형은 공을 50번 차서 30번 넣었고, 나는 20번 차서 13번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"나","correct":true},{"t":"형","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","형 30 ÷ 50 × 100 = 60, 나 13 ÷ 20 × 100 = 65예요.","형 60 %, 나 65 % — 나가 더 잘 넣었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#10','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',3,'sa','auto','나는 공을 25번 차서 12번 넣었어요. 100번 찼다고 생각하면 몇 번 넣은 셈인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u4-C5","difficulty":3,"kind":"sa","stem":"나는 공을 25번 차서 12번 넣었어요. 100번 찼다고 생각하면 몇 번 넣은 셈인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["찬 횟수 25를 100으로 맞추려면 25 × 4 = 100이에요.","넣은 횟수도 12 × 4 = 48이에요.","그래서 48번 넣은 셈 — 48 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"동생은 공을 20번 차서 10번 넣었어요. 100번 찼다고 생각하면 몇 번 넣은 셈인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["찬 횟수 20을 100으로 맞추려면 20 × 5 = 100이에요.","넣은 횟수도 10 × 5 = 50이에요.","그래서 50번 넣은 셈 — 50 %예요."]},{"stem":"언니는 공을 50번 차서 31번 넣었어요. 100번 찼다고 생각하면 몇 번 넣은 셈인가요? 숫자로 쓰세요.","answer":["62"],"explanation":["찬 횟수 50을 100으로 맞추려면 50 × 2 = 100이에요.","넣은 횟수도 31 × 2 = 62예요.","그래서 62번 넣은 셈 — 62 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#1','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',2,'sa','auto','수학 문제 40개 가운데 34개를 맞혔어요. 전체 문제 수에 대한 맞힌 문제 수의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"수학 문제 40개 가운데 34개를 맞혔어요. 전체 문제 수에 대한 맞힌 문제 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["기준량은 40, 비교하는 양은 34예요.","34 ÷ 40 × 100 = 85예요.","그래서 85 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"씨앗 50개를 심었더니 43개가 싹을 틔웠어요. 심은 씨앗 수에 대한 싹 튼 씨앗 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["86"],"explanation":["기준량은 50, 비교하는 양은 43이에요.","43 ÷ 50 × 100 = 86이에요.","그래서 86 %예요."]},{"stem":"줄넘기 이단 뛰기를 25번 해서 21번 성공했어요. 한 횟수에 대한 성공한 횟수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["기준량은 25, 비교하는 양은 21이에요.","21 ÷ 25 × 100 = 84예요.","그래서 84 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#2','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',2,'sa','auto','35 %를 분모가 20인 분수로 나타내면 ⟨□/20⟩예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"35 %를 분모가 20인 분수로 나타내면 ⟨□/20⟩예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["35 %는 ⟨35/100⟩예요.","분모와 분자를 5로 나누면 ⟨35/100⟩ = ⟨7/20⟩이에요.","□는 7이에요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"60 %를 분모가 5인 분수로 나타내면 ⟨□/5⟩예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["60 %는 ⟨60/100⟩이에요.","분모와 분자를 20으로 나누면 ⟨60/100⟩ = ⟨3/5⟩이에요.","□는 3이에요."]},{"stem":"24 %를 분모가 25인 분수로 나타내면 ⟨□/25⟩예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["24 %는 ⟨24/100⟩예요.","분모와 분자를 4로 나누면 ⟨24/100⟩ = ⟨6/25⟩이에요.","□는 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#3','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',3,'error','auto','비율 ⟨16/25⟩을 백분율로 나타내는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X09','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C5","difficulty":3,"kind":"error","stem":"비율 ⟨16/25⟩을 백분율로 나타내는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「분자가 16이니 16 %야.」","correct":true,"mis_target":"M6-1-u4-X09"},{"t":"이현 — 「⟨16/25⟩ = ⟨64/100⟩야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「16 ÷ 25 × 100 = 64야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량을 100으로 맞추어야 해요.","⟨16/25⟩ = ⟨64/100⟩ — 64 %예요.","준희는 분모를 100으로 고치지 않았어요."],"variant_rule":{"alt":[{"stem":"비율 ⟨9/20⟩를 백분율로 나타내는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「분자가 9니 9 %야.」","correct":true,"mis_target":"M6-1-u4-X09"},{"t":"수아 — 「⟨9/20⟩ = ⟨45/100⟩야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「9 ÷ 20 × 100 = 45야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량을 100으로 맞추어야 해요.","⟨9/20⟩ = ⟨45/100⟩ — 45 %예요.","서호는 분모를 100으로 고치지 않았어요."]},{"stem":"비율 ⟨7/25⟩을 백분율로 나타내는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「분자가 7이니 7 %야.」","correct":true,"mis_target":"M6-1-u4-X09"},{"t":"나린 — 「⟨7/25⟩ = ⟨28/100⟩이야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「7 ÷ 25 × 100 = 28이야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량을 100으로 맞추어야 해요.","⟨7/25⟩ = ⟨28/100⟩ — 28 %예요.","가온은 분모를 100으로 고치지 않았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#4','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',3,'ox','auto','비율 0.07을 백분율로 나타내면 70 %예요.',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":4,"concept":"M6-1-u4-C5","difficulty":3,"kind":"ox","stem":"비율 0.07을 백분율로 나타내면 70 %예요.","answer":"X","reason_options":[{"t":"0.07 × 100 = 7이라 7 %이기 때문에","correct":true},{"t":"0.07의 7 뒤에 0을 붙이면 되기 때문에","mis":"M6-1-u4-X08"}],"mis":"M6-1-u4-X08","explanation":["기준량을 100으로 할 때의 비율을 백분율이라 하고 %를 써요.","비율에 100을 곱해서 나온 값에 %를 붙여요.","기준량이 100인 분수로 바꾸어도 돼요."],"variant_rule":{"alt":[{"stem":"비율 ⟨16/25⟩은 16 %예요.","answer":"X","reason_options":[{"t":"⟨16/25⟩ = ⟨64/100⟩라 64 %이기 때문에","correct":true},{"t":"분자 16이 백분율이기 때문에","mis":"M6-1-u4-X09"}],"explanation":["기준량을 100으로 할 때의 비율을 백분율이라 하고 %를 써요.","비율에 100을 곱해서 나온 값에 %를 붙여요.","기준량이 100인 분수로 바꾸어도 돼요."]},{"stem":"공을 넣은 횟수가 많은 사람이 언제나 넣은 비율도 높아요.","answer":"X","reason_options":[{"t":"찬 횟수가 다르면 백분율로 비교해야 하기 때문에","correct":true},{"t":"넣은 횟수가 곧 백분율이기 때문에","mis":"M6-1-u4-X11"}],"explanation":["기준량을 100으로 할 때의 비율을 백분율이라 하고 %를 써요.","비율에 100을 곱해서 나온 값에 %를 붙여요.","기준량이 100인 분수로 바꾸어도 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#5','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',3,'mc','auto','세 비율 ⟨14/25⟩, 0.62, 59 % 가운데 가장 작은 것은 어느 것인가요?',ARRAY['M6-1-u4-X09','M6-1-u4-X15']::text[],true,'{"seq":5,"concept":"M6-1-u4-C5","difficulty":3,"kind":"mc","stem":"세 비율 ⟨14/25⟩, 0.62, 59 % 가운데 가장 작은 것은 어느 것인가요?","options":[{"t":"⟨14/25⟩","correct":true},{"t":"0.62","mis":"M6-1-u4-X09"},{"t":"59 %","mis":"M6-1-u4-X09"},{"t":"모두 같아요","mis":"M6-1-u4-X15"}],"explanation":["한 가지 표기로 통일해서 비교해요.","⟨14/25⟩ → 56 %, 0.62 → 62 %, 59 % → 59 %예요.","가장 작은 것은 ⟨14/25⟩예요."],"variant_rule":{"alt":[{"stem":"세 비율 ⟨3/5⟩, 0.55, 58 % 가운데 가장 큰 것은 어느 것인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"0.55","mis":"M6-1-u4-X09"},{"t":"58 %","mis":"M6-1-u4-X09"},{"t":"모두 같아요","mis":"M6-1-u4-X15"}],"explanation":["한 가지 표기로 통일해서 비교해요.","⟨3/5⟩ → 60 %, 0.55 → 55 %, 58 % → 58 %예요.","가장 큰 것은 ⟨3/5⟩이에요."]},{"stem":"세 비율 ⟨7/20⟩, 0.4, 38 % 가운데 가장 큰 것은 어느 것인가요?","options":[{"t":"0.4","correct":true},{"t":"⟨7/20⟩","mis":"M6-1-u4-X09"},{"t":"38 %","mis":"M6-1-u4-X09"},{"t":"모두 같아요","mis":"M6-1-u4-X15"}],"explanation":["한 가지 표기로 통일해서 비교해요.","⟨7/20⟩ → 35 %, 0.4 → 40 %, 38 % → 38 %예요.","가장 큰 것은 0.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#6','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',3,'mc','auto','지민은 공을 40번 차서 30번 넣었고, 태오는 25번 차서 20번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":6,"concept":"M6-1-u4-C5","difficulty":3,"kind":"mc","stem":"지민은 공을 40번 차서 30번 넣었고, 태오는 25번 차서 20번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"태오","correct":true},{"t":"지민","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","지민 30 ÷ 40 × 100 = 75, 태오 20 ÷ 25 × 100 = 80이에요.","지민 75 %, 태오 80 % — 태오가 더 잘 넣었어요."],"variant_rule":{"alt":[{"stem":"하윤은 공을 50번 차서 34번 넣었고, 은호는 25번 차서 18번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"은호","correct":true},{"t":"하윤","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","하윤 34 ÷ 50 × 100 = 68, 은호 18 ÷ 25 × 100 = 72예요.","하윤 68 %, 은호 72 % — 은호가 더 잘 넣었어요."]},{"stem":"나는 공을 20번 차서 17번 넣었고, 동생은 40번 차서 32번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"나","correct":true},{"t":"동생","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","나 17 ÷ 20 × 100 = 85, 동생 32 ÷ 40 × 100 = 80이에요.","나 85 %, 동생 80 % — 나가 더 잘 넣었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#7','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',3,'sa','auto','자유투를 40번 던져 26번 넣었어요. 던진 횟수에 대한 넣은 횟수의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u4-C5","difficulty":3,"kind":"sa","stem":"자유투를 40번 던져 26번 넣었어요. 던진 횟수에 대한 넣은 횟수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["기준량은 40, 비교하는 양은 26이에요.","26 ÷ 40 × 100 = 65예요.","그래서 65 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"동생은 공을 20번 차서 10번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["기준량은 20, 비교하는 양은 10이에요.","10 ÷ 20 × 100 = 50이에요.","그래서 50 %예요."]},{"stem":"씨앗 50개를 심었더니 43개가 싹을 틔웠어요. 심은 씨앗 수에 대한 싹 튼 씨앗 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["86"],"explanation":["기준량은 50, 비교하는 양은 43이에요.","43 ÷ 50 × 100 = 86이에요.","그래서 86 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#8','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',4,'mc','auto','세 비율 ⟨9/25⟩, 0.4, 3.8 % 가운데 가장 작은 것은 어느 것인가요?',ARRAY['M6-1-u4-X09','M6-1-u4-X15']::text[],true,'{"seq":8,"concept":"M6-1-u4-C5","difficulty":4,"kind":"mc","stem":"세 비율 ⟨9/25⟩, 0.4, 3.8 % 가운데 가장 작은 것은 어느 것인가요?","options":[{"t":"3.8 %","correct":true},{"t":"⟨9/25⟩","mis":"M6-1-u4-X09"},{"t":"0.4","mis":"M6-1-u4-X09"},{"t":"모두 같아요","mis":"M6-1-u4-X15"}],"explanation":["한 가지 표기로 통일해서 비교해요.","⟨9/25⟩ → 36 %, 0.4 → 40 %, 3.8 % → 3.8 %예요.","가장 작은 것은 3.8 %예요."],"variant_rule":{"alt":[{"stem":"세 비율 ⟨7/8⟩, 0.9, 88 % 가운데 가장 큰 것은 어느 것인가요?","options":[{"t":"0.9","correct":true},{"t":"⟨7/8⟩","mis":"M6-1-u4-X09"},{"t":"88 %","mis":"M6-1-u4-X09"},{"t":"모두 같아요","mis":"M6-1-u4-X15"}],"explanation":["한 가지 표기로 통일해서 비교해요.","⟨7/8⟩ → 87.5 %, 0.9 → 90 %, 88 % → 88 %예요.","가장 큰 것은 0.9예요."]},{"stem":"세 비율 ⟨2/5⟩, 0.04, 4.5 % 가운데 가장 작은 것은 어느 것인가요?","options":[{"t":"0.04","correct":true},{"t":"⟨2/5⟩","mis":"M6-1-u4-X09"},{"t":"4.5 %","mis":"M6-1-u4-X09"},{"t":"모두 같아요","mis":"M6-1-u4-X15"}],"explanation":["한 가지 표기로 통일해서 비교해요.","⟨2/5⟩ → 40 %, 0.04 → 4 %, 4.5 % → 4.5 %예요.","가장 작은 것은 0.04예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#9','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',4,'sa','auto','나는 공을 20번 차서 13번 넣었어요. 100번 찼다고 생각하면 몇 번 넣은 셈인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u4-C5","difficulty":4,"kind":"sa","stem":"나는 공을 20번 차서 13번 넣었어요. 100번 찼다고 생각하면 몇 번 넣은 셈인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["찬 횟수 20을 100으로 맞추려면 20 × 5 = 100이에요.","넣은 횟수도 13 × 5 = 65예요.","그래서 65번 넣은 셈 — 65 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"동생은 공을 25번 차서 14번 넣었어요. 100번 찼다고 생각하면 몇 번 넣은 셈인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["찬 횟수 25를 100으로 맞추려면 25 × 4 = 100이에요.","넣은 횟수도 14 × 4 = 56이에요.","그래서 56번 넣은 셈 — 56 %예요."]},{"stem":"형은 공을 50번 차서 37번 넣었어요. 100번 찼다고 생각하면 몇 번 넣은 셈인가요? 숫자로 쓰세요.","answer":["74"],"explanation":["찬 횟수 50을 100으로 맞추려면 50 × 2 = 100이에요.","넣은 횟수도 37 × 2 = 74예요.","그래서 74번 넣은 셈 — 74 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#10','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',4,'essay','teacher','나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 넣은 비율을 백분율로 구하고, 누가 더 잘 넣었는지 까닭과 함께 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u4-C5","difficulty":4,"kind":"essay","stem":"나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 넣은 비율을 백분율로 구하고, 누가 더 잘 넣었는지 까닭과 함께 설명해 보세요.","answer_guide":{"answer":"예: 찬 횟수를 100으로 맞추면 나는 25 × 4 = 100번 찼다면 12 × 4 = 48번, 동생은 20 × 5 = 100번 찼다면 10 × 5 = 50번 넣은 셈이다. 나는 48 %, 동생은 50 %이므로 동생이 더 잘 넣었다. 넣은 횟수는 내가 많지만 찬 횟수가 다르므로 백분율로 비교해야 한다.","scoring_points":["나 48 %·동생 50 %를 구했는가","동생이 더 잘 넣었다고 답했는가","찬 횟수가 달라 백분율로 비교해야 한다고 썼는가"]},"explanation":["나는 48 %, 동생은 50 %예요.","동생이 더 잘 넣었어요.","찬 횟수가 다르면 백분율로 비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#1','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',1,'sa','auto','학급 회장 선거에서 전체 30표 가운데 건우가 18표를 받았어요. 건우의 득표율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C6","difficulty":1,"kind":"sa","stem":"학급 회장 선거에서 전체 30표 가운데 건우가 18표를 받았어요. 건우의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","18 ÷ 30 × 100 = 60이에요.","건우의 득표율은 60 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"학급 회장 선거에서 전체 30표 가운데 수빈이가 12표를 받았어요. 수빈이의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","12 ÷ 30 × 100 = 40이에요.","수빈이의 득표율은 40 %예요."]},{"stem":"학급 회장 선거에서 전체 25표 가운데 하늘이 9표를 받았어요. 하늘의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","9 ÷ 25 × 100 = 36이에요.","하늘의 득표율은 36 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#2','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',1,'mc','auto','은행에 120000원을 맡겼더니 이자가 6000원 붙었어요. 맡긴 돈에 대한 이자의 비율은 몇 %인가요?',ARRAY['M6-1-u4-X08','M6-1-u4-X05']::text[],true,'{"seq":2,"concept":"M6-1-u4-C6","difficulty":1,"kind":"mc","stem":"은행에 120000원을 맡겼더니 이자가 6000원 붙었어요. 맡긴 돈에 대한 이자의 비율은 몇 %인가요?","options":[{"t":"5 %","correct":true},{"t":"50 %","mis":"M6-1-u4-X08"},{"t":"0.5 %","mis":"M6-1-u4-X08"},{"t":"20 %","mis":"M6-1-u4-X05"}],"explanation":["기준량은 맡긴 돈 120000, 비교하는 양은 이자 6000이에요.","⟨6000/120000⟩ = ⟨5/100⟩예요.","그래서 5 %예요."],"variant_rule":{"alt":[{"stem":"은행에 50000원을 맡겼더니 이자가 1000원 붙었어요. 맡긴 돈에 대한 이자의 비율은 몇 %인가요?","options":[{"t":"2 %","correct":true},{"t":"20 %","mis":"M6-1-u4-X08"},{"t":"0.2 %","mis":"M6-1-u4-X08"},{"t":"50 %","mis":"M6-1-u4-X05"}],"explanation":["기준량은 맡긴 돈 50000, 비교하는 양은 이자 1000이에요.","⟨1000/50000⟩ = ⟨2/100⟩예요.","그래서 2 %예요."]},{"stem":"은행에 80000원을 맡겼더니 이자가 2400원 붙었어요. 맡긴 돈에 대한 이자의 비율은 몇 %인가요?","options":[{"t":"3 %","correct":true},{"t":"30 %","mis":"M6-1-u4-X08"},{"t":"0.3 %","mis":"M6-1-u4-X08"},{"t":"300 %","mis":"M6-1-u4-X08"}],"explanation":["기준량은 맡긴 돈 80000, 비교하는 양은 이자 2400이에요.","⟨2400/80000⟩ = ⟨3/100⟩이에요.","그래서 3 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#3','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',1,'ox','auto','후보가 두 명뿐이고 무효표가 없으면 두 사람의 득표율을 더해 100 %예요.',ARRAY['M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C6","difficulty":1,"kind":"ox","stem":"후보가 두 명뿐이고 무효표가 없으면 두 사람의 득표율을 더해 100 %예요.","answer":"O","reason_options":[{"t":"전체 표가 두 사람에게 모두 나뉘기 때문에","correct":true},{"t":"득표율은 언제나 50 %씩이기 때문에","mis":"M6-1-u4-X16"}],"mis":"M6-1-u4-X16","explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."],"variant_rule":{"alt":[{"stem":"120000원을 맡기고 이자 6000원을 받았다면 이자의 비율은 5 %예요.","answer":"O","reason_options":[{"t":"6000 ÷ 120000 × 100 = 5이기 때문에","correct":true},{"t":"120000 ÷ 6000을 계산하기 때문에","mis":"M6-1-u4-X05"}],"explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."]},{"stem":"진하기가 높은 설탕물이 더 달아요.","answer":"O","reason_options":[{"t":"같은 양의 설탕물에 설탕이 더 많이 들어 있기 때문에","correct":true},{"t":"설탕물의 양이 더 많기 때문에","mis":"M6-1-u4-X11"}],"explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#4','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',1,'sa','auto','가 치약은 원래 가격 3000원에서 900원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u4-C6","difficulty":1,"kind":"sa","stem":"가 치약은 원래 가격 3000원에서 900원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","900 ÷ 3000 × 100 = 30이에요.","할인율은 30 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"공책은 원래 가격 2000원에서 300원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","300 ÷ 2000 × 100 = 15예요.","할인율은 15 %예요."]},{"stem":"필통은 원래 가격 8000원에서 2000원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","2000 ÷ 8000 × 100 = 25예요.","할인율은 25 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#5','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',2,'sa','auto','지후는 설탕 210 g을 녹여 설탕물 750 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"지후는 설탕 210 g을 녹여 설탕물 750 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["기준량은 설탕물 750 g, 비교하는 양은 설탕 210 g이에요.","210 ÷ 750 × 100 = 28이에요.","설탕물의 진하기는 28 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"예은은 설탕 36 g을 녹여 설탕물 200 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["기준량은 설탕물 200 g, 비교하는 양은 설탕 36 g이에요.","36 ÷ 200 × 100 = 18이에요.","설탕물의 진하기는 18 %예요."]},{"stem":"민서는 설탕 45 g을 녹여 설탕물 300 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["기준량은 설탕물 300 g, 비교하는 양은 설탕 45 g이에요.","45 ÷ 300 × 100 = 15예요.","설탕물의 진하기는 15 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#6','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',2,'sa','auto','전체 30표 가운데 건우가 18표를 받았어요. 무효표 없이 후보가 두 명뿐이라면 다른 후보의 득표율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"전체 30표 가운데 건우가 18표를 받았어요. 무효표 없이 후보가 두 명뿐이라면 다른 후보의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["건우의 득표율은 18 ÷ 30 × 100 = 60이에요.","두 사람의 득표율을 더하면 100 %예요.","100 − 60 = 40 — 다른 후보는 40 %예요."],"mis":"M6-1-u4-X16","variant_rule":{"alt":[{"stem":"전체 40표 가운데 도윤이 22표를 받았어요. 무효표 없이 후보가 두 명뿐이라면 다른 후보의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["도윤의 득표율은 22 ÷ 40 × 100 = 55예요.","두 사람의 득표율을 더하면 100 %예요.","100 − 55 = 45 — 다른 후보는 45 %예요."]},{"stem":"전체 50표 가운데 서아가 27표를 받았어요. 무효표 없이 후보가 두 명뿐이라면 다른 후보의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["46"],"explanation":["서아의 득표율은 27 ÷ 50 × 100 = 54예요.","두 사람의 득표율을 더하면 100 %예요.","100 − 54 = 46 — 다른 후보는 46 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#7','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',2,'mc','auto','가 치약은 원래 가격 3000원에서 900원을, 나 치약은 원래 가격 5000원에서 1400원을 할인해요. 할인율이 더 큰 것은 어느 것인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":7,"concept":"M6-1-u4-C6","difficulty":2,"kind":"mc","stem":"가 치약은 원래 가격 3000원에서 900원을, 나 치약은 원래 가격 5000원에서 1400원을 할인해요. 할인율이 더 큰 것은 어느 것인가요?","options":[{"t":"가 치약","correct":true},{"t":"나 치약","mis":"M6-1-u4-X11"},{"t":"두 물건이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["원래 가격이 다르니 할인 금액이 아니라 할인율로 비교해요.","가 치약 900 ÷ 3000 × 100 = 30, 나 치약 1400 ÷ 5000 × 100 = 28이에요.","할인율이 더 큰 것은 가 치약이에요."],"variant_rule":{"alt":[{"stem":"가 공책은 원래 가격 2000원에서 500원을, 나 공책은 원래 가격 4000원에서 800원을 할인해요. 할인율이 더 큰 것은 어느 것인가요?","options":[{"t":"가 공책","correct":true},{"t":"나 공책","mis":"M6-1-u4-X11"},{"t":"두 물건이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["원래 가격이 다르니 할인 금액이 아니라 할인율로 비교해요.","가 공책 500 ÷ 2000 × 100 = 25, 나 공책 800 ÷ 4000 × 100 = 20이에요.","할인율이 더 큰 것은 가 공책이에요."]},{"stem":"가 필통은 원래 가격 6000원에서 1800원을, 나 필통은 원래 가격 9000원에서 2250원을 할인해요. 할인율이 더 큰 것은 어느 것인가요?","options":[{"t":"가 필통","correct":true},{"t":"나 필통","mis":"M6-1-u4-X11"},{"t":"두 물건이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["원래 가격이 다르니 할인 금액이 아니라 할인율로 비교해요.","가 필통 1800 ÷ 6000 × 100 = 30, 나 필통 2250 ÷ 9000 × 100 = 25예요.","할인율이 더 큰 것은 가 필통이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#8','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',2,'sa','auto','아이스크림 가게에서 아이스크림 25개 가운데 19개를 팔았어요. 전체 수에 대한 판매한 수의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"아이스크림 가게에서 아이스크림 25개 가운데 19개를 팔았어요. 전체 수에 대한 판매한 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["76"],"explanation":["기준량은 25, 비교하는 양은 19예요.","⟨19/25⟩ = ⟨76/100⟩이에요.","그래서 76 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"빵집에서 빵 40개 가운데 36개를 팔았어요. 전체 수에 대한 판매한 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["기준량은 40, 비교하는 양은 36이에요.","⟨36/40⟩ = ⟨90/100⟩이에요.","그래서 90 %예요."]},{"stem":"음악회 표 50장 가운데 47장이 팔렸어요. 전체 표 수에 대한 팔린 표 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["94"],"explanation":["기준량은 50, 비교하는 양은 47이에요.","⟨47/50⟩ = ⟨94/100⟩예요.","그래서 94 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#9','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',2,'ox','auto','할인 금액이 큰 물건이 언제나 할인율도 커요.',ARRAY['M6-1-u4-X11']::text[],true,'{"seq":9,"concept":"M6-1-u4-C6","difficulty":2,"kind":"ox","stem":"할인 금액이 큰 물건이 언제나 할인율도 커요.","answer":"X","reason_options":[{"t":"원래 가격이 다르면 할인율로 비교해야 하기 때문에","correct":true},{"t":"할인 금액이 곧 할인율이기 때문에","mis":"M6-1-u4-X11"}],"mis":"M6-1-u4-X11","explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."],"variant_rule":{"alt":[{"stem":"설탕 30 g을 물 120 g에 녹인 설탕물의 진하기는 25 %예요.","answer":"X","reason_options":[{"t":"설탕물은 30 + 120 = 150 (g)이라 30 ÷ 150 × 100 = 20이기 때문에","correct":true},{"t":"30 ÷ 120 × 100을 계산하기 때문에","mis":"M6-1-u4-X12"}],"explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."]},{"stem":"할인율은 (할인된 가격) ÷ (원래 가격)으로 구해요.","answer":"X","reason_options":[{"t":"할인율은 원래 가격에 대한 할인 금액의 비율이기 때문에","correct":true},{"t":"할인된 가격이 비교하는 양이기 때문에","mis":"M6-1-u4-X10"}],"explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#10','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',3,'sa','auto','운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u4-C6","difficulty":3,"kind":"sa","stem":"운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 40000 − 30000 = 10000이에요.","10000 ÷ 40000 × 100 = 25예요.","할인율은 25 %예요."],"mis":"M6-1-u4-X10","variant_rule":{"alt":[{"stem":"가방은 원래 가격이 25000원인데 20000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 25000 − 20000 = 5000이에요.","5000 ÷ 25000 × 100 = 20이에요.","할인율은 20 %예요."]},{"stem":"모자는 원래 가격이 20000원인데 17000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 20000 − 17000 = 3000이에요.","3000 ÷ 20000 × 100 = 15예요.","할인율은 15 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#1','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',2,'sa','auto','설탕 30 g을 물 120 g에 녹였어요. 설탕물 양에 대한 설탕 양의 비율(진하기)은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"설탕 30 g을 물 120 g에 녹였어요. 설탕물 양에 대한 설탕 양의 비율(진하기)은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["설탕물은 물과 설탕을 합한 120 + 30 = 150 (g)이에요.","30 ÷ 150 × 100 = 20이에요.","진하기는 20 %예요."],"mis":"M6-1-u4-X12","variant_rule":{"alt":[{"stem":"설탕 60 g을 물 140 g에 녹였어요. 설탕물 양에 대한 설탕 양의 비율(진하기)은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["설탕물은 물과 설탕을 합한 140 + 60 = 200 (g)이에요.","60 ÷ 200 × 100 = 30이에요.","진하기는 30 %예요."]},{"stem":"설탕 45 g을 물 105 g에 녹였어요. 설탕물 양에 대한 설탕 양의 비율(진하기)은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["설탕물은 물과 설탕을 합한 105 + 45 = 150 (g)이에요.","45 ÷ 150 × 100 = 30이에요.","진하기는 30 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#2','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',2,'mc','auto','은행에 200000원을 맡겼더니 이자가 8000원 붙었어요. 맡긴 돈에 대한 이자의 비율은 몇 %인가요?',ARRAY['M6-1-u4-X08','M6-1-u4-X05']::text[],true,'{"seq":2,"concept":"M6-1-u4-C6","difficulty":2,"kind":"mc","stem":"은행에 200000원을 맡겼더니 이자가 8000원 붙었어요. 맡긴 돈에 대한 이자의 비율은 몇 %인가요?","options":[{"t":"4 %","correct":true},{"t":"40 %","mis":"M6-1-u4-X08"},{"t":"0.4 %","mis":"M6-1-u4-X08"},{"t":"25 %","mis":"M6-1-u4-X05"}],"explanation":["기준량은 맡긴 돈 200000, 비교하는 양은 이자 8000이에요.","⟨8000/200000⟩ = ⟨4/100⟩예요.","그래서 4 %예요."],"variant_rule":{"alt":[{"stem":"은행에 60000원을 맡겼더니 이자가 1800원 붙었어요. 맡긴 돈에 대한 이자의 비율은 몇 %인가요?","options":[{"t":"3 %","correct":true},{"t":"30 %","mis":"M6-1-u4-X08"},{"t":"0.3 %","mis":"M6-1-u4-X08"},{"t":"300 %","mis":"M6-1-u4-X08"}],"explanation":["기준량은 맡긴 돈 60000, 비교하는 양은 이자 1800이에요.","⟨1800/60000⟩ = ⟨3/100⟩이에요.","그래서 3 %예요."]},{"stem":"은행에 250000원을 맡겼더니 이자가 5000원 붙었어요. 맡긴 돈에 대한 이자의 비율은 몇 %인가요?","options":[{"t":"2 %","correct":true},{"t":"20 %","mis":"M6-1-u4-X08"},{"t":"0.2 %","mis":"M6-1-u4-X08"},{"t":"50 %","mis":"M6-1-u4-X05"}],"explanation":["기준량은 맡긴 돈 250000, 비교하는 양은 이자 5000이에요.","⟨5000/250000⟩ = ⟨2/100⟩예요.","그래서 2 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#3','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',3,'error','auto','운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X10','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C6","difficulty":3,"kind":"error","stem":"운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「30000 ÷ 40000 × 100 = 75니 75 %야.」","correct":true,"mis_target":"M6-1-u4-X10"},{"t":"이현 — 「할인 금액은 10000원이야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「할인율은 25 %야.」","mis":"M6-1-u4-X16"}],"explanation":["할인 금액은 40000 − 30000 = 10000이에요.","10000 ÷ 40000 × 100 = 25예요.","준희는 할인된 가격으로 계산했어요."],"variant_rule":{"alt":[{"stem":"가방은 원래 가격이 25000원인데 20000원에 팔아요. 할인율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「20000 ÷ 25000 × 100 = 80이니 80 %야.」","correct":true,"mis_target":"M6-1-u4-X10"},{"t":"수아 — 「할인 금액은 5000원이야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「할인율은 20 %야.」","mis":"M6-1-u4-X16"}],"explanation":["할인 금액은 25000 − 20000 = 5000이에요.","5000 ÷ 25000 × 100 = 20이에요.","서호는 할인된 가격으로 계산했어요."]},{"stem":"우산은 원래 가격이 15000원인데 12000원에 팔아요. 할인율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「12000 ÷ 15000 × 100 = 80이니 80 %야.」","correct":true,"mis_target":"M6-1-u4-X10"},{"t":"나린 — 「할인 금액은 3000원이야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「할인율은 20 %야.」","mis":"M6-1-u4-X16"}],"explanation":["할인 금액은 15000 − 12000 = 3000이에요.","3000 ÷ 15000 × 100 = 20이에요.","가온은 할인된 가격으로 계산했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#4','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',3,'ox','auto','은행에 50000원을 맡기고 이자 1000원을 받았다면 이자의 비율은 2 %예요.',ARRAY['M6-1-u4-X03']::text[],true,'{"seq":4,"concept":"M6-1-u4-C6","difficulty":3,"kind":"ox","stem":"은행에 50000원을 맡기고 이자 1000원을 받았다면 이자의 비율은 2 %예요.","answer":"O","reason_options":[{"t":"1000 ÷ 50000 × 100 = 2이기 때문에","correct":true},{"t":"50000에서 1000을 빼서 구하기 때문에","mis":"M6-1-u4-X03"}],"mis":"M6-1-u4-X03","explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."],"variant_rule":{"alt":[{"stem":"득표율은 (받은 표 수) ÷ (전체 표 수) × 100으로 구해요.","answer":"O","reason_options":[{"t":"전체 표 수에 대한 받은 표 수의 비율이기 때문에","correct":true},{"t":"받은 표 수가 기준량이기 때문에","mis":"M6-1-u4-X01"}],"explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."]},{"stem":"3000원에서 900원 할인한 것보다 5000원에서 1400원 할인한 것이 할인율이 커요.","answer":"X","reason_options":[{"t":"할인율이 30 %와 28 %라 3000원짜리가 더 크기 때문에","correct":true},{"t":"1400원이 900원보다 크기 때문에","mis":"M6-1-u4-X11"}],"explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#5','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',3,'mc','auto','석진은 설탕 30 g을 물 70 g에, 민아는 설탕 40 g을 물 160 g에 녹였어요. 더 진한 설탕물은 누구의 것인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X12']::text[],true,'{"seq":5,"concept":"M6-1-u4-C6","difficulty":3,"kind":"mc","stem":"석진은 설탕 30 g을 물 70 g에, 민아는 설탕 40 g을 물 160 g에 녹였어요. 더 진한 설탕물은 누구의 것인가요?","options":[{"t":"석진","correct":true},{"t":"민아","mis":"M6-1-u4-X11"},{"t":"두 설탕물이 같아요","mis":"M6-1-u4-X12"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["진하기는 설탕물 양에 대한 설탕 양의 비율이에요 — 설탕물 = 물 + 설탕.","석진 30 ÷ 100 × 100 = 30, 민아 40 ÷ 200 × 100 = 20이에요.","석진의 설탕물이 더 진해요."],"variant_rule":{"alt":[{"stem":"예은은 설탕 45 g을 물 205 g에, 지후는 설탕 42 g을 물 108 g에 녹였어요. 더 진한 설탕물은 누구의 것인가요?","options":[{"t":"지후","correct":true},{"t":"예은","mis":"M6-1-u4-X11"},{"t":"두 설탕물이 같아요","mis":"M6-1-u4-X12"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["진하기는 설탕물 양에 대한 설탕 양의 비율이에요 — 설탕물 = 물 + 설탕.","예은 45 ÷ 250 × 100 = 18, 지후 42 ÷ 150 × 100 = 28이에요.","지후의 설탕물이 더 진해요."]},{"stem":"하준은 설탕 20 g을 물 80 g에, 소율은 설탕 36 g을 물 114 g에 녹였어요. 더 진한 설탕물은 누구의 것인가요?","options":[{"t":"소율","correct":true},{"t":"하준","mis":"M6-1-u4-X11"},{"t":"두 설탕물이 같아요","mis":"M6-1-u4-X12"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["진하기는 설탕물 양에 대한 설탕 양의 비율이에요 — 설탕물 = 물 + 설탕.","하준 20 ÷ 100 × 100 = 20, 소율 36 ÷ 150 × 100 = 24예요.","소율의 설탕물이 더 진해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#6','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',3,'sa','auto','공연장 자리 120개 가운데 42개가 예매되었어요. 전체 자리 수에 대한 예매된 자리 수의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C6","difficulty":3,"kind":"sa","stem":"공연장 자리 120개 가운데 42개가 예매되었어요. 전체 자리 수에 대한 예매된 자리 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["기준량은 120, 비교하는 양은 42예요.","⟨42/120⟩ = ⟨35/100⟩예요.","그래서 35 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"상큼 주스 80 g에는 설탕 12 g이 들어 있어요. 주스 무게에 대한 설탕 무게의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["기준량은 80, 비교하는 양은 12예요.","⟨12/80⟩ = ⟨15/100⟩예요.","그래서 15 %예요."]},{"stem":"지우는 활쏘기에서 화살 20발 가운데 17발을 맞혔어요. 쏜 화살 수에 대한 맞힌 화살 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["기준량은 20, 비교하는 양은 17이에요.","⟨17/20⟩ = ⟨85/100⟩예요.","그래서 85 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#7','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',3,'sa','auto','우산은 원래 가격이 15000원인데 12000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u4-C6","difficulty":3,"kind":"sa","stem":"우산은 원래 가격이 15000원인데 12000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 15000 − 12000 = 3000이에요.","3000 ÷ 15000 × 100 = 20이에요.","할인율은 20 %예요."],"mis":"M6-1-u4-X10","variant_rule":{"alt":[{"stem":"색연필은 원래 가격이 6000원인데 4500원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 6000 − 4500 = 1500이에요.","1500 ÷ 6000 × 100 = 25예요.","할인율은 25 %예요."]},{"stem":"필통은 원래 가격이 8000원인데 6000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 8000 − 6000 = 2000이에요.","2000 ÷ 8000 × 100 = 25예요.","할인율은 25 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#8','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',4,'mc','auto','가 운동화는 원래 가격 50000원에서 12000원을, 나 운동화는 원래 가격 30000원에서 9000원을 할인해요. 할인율이 더 큰 것은 어느 것인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":8,"concept":"M6-1-u4-C6","difficulty":4,"kind":"mc","stem":"가 운동화는 원래 가격 50000원에서 12000원을, 나 운동화는 원래 가격 30000원에서 9000원을 할인해요. 할인율이 더 큰 것은 어느 것인가요?","options":[{"t":"나 운동화","correct":true},{"t":"가 운동화","mis":"M6-1-u4-X11"},{"t":"두 물건이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["원래 가격이 다르니 할인 금액이 아니라 할인율로 비교해요.","가 운동화 12000 ÷ 50000 × 100 = 24, 나 운동화 9000 ÷ 30000 × 100 = 30이에요.","할인율이 더 큰 것은 나 운동화예요."],"variant_rule":{"alt":[{"stem":"가 책가방은 원래 가격 40000원에서 8000원을, 나 책가방은 원래 가격 25000원에서 6250원을 할인해요. 할인율이 더 큰 것은 어느 것인가요?","options":[{"t":"나 책가방","correct":true},{"t":"가 책가방","mis":"M6-1-u4-X11"},{"t":"두 물건이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["원래 가격이 다르니 할인 금액이 아니라 할인율로 비교해요.","가 책가방 8000 ÷ 40000 × 100 = 20, 나 책가방 6250 ÷ 25000 × 100 = 25예요.","할인율이 더 큰 것은 나 책가방이에요."]},{"stem":"가 자전거는 원래 가격 200000원에서 30000원을, 나 자전거는 원래 가격 120000원에서 24000원을 할인해요. 할인율이 더 큰 것은 어느 것인가요?","options":[{"t":"나 자전거","correct":true},{"t":"가 자전거","mis":"M6-1-u4-X11"},{"t":"두 물건이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["원래 가격이 다르니 할인 금액이 아니라 할인율로 비교해요.","가 자전거 30000 ÷ 200000 × 100 = 15, 나 자전거 24000 ÷ 120000 × 100 = 20이에요.","할인율이 더 큰 것은 나 자전거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#9','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',4,'sa','auto','설탕 25 g을 물 75 g에 녹였어요. 설탕물 양에 대한 설탕 양의 비율(진하기)은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u4-C6","difficulty":4,"kind":"sa","stem":"설탕 25 g을 물 75 g에 녹였어요. 설탕물 양에 대한 설탕 양의 비율(진하기)은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["설탕물은 물과 설탕을 합한 75 + 25 = 100 (g)이에요.","25 ÷ 100 × 100 = 25예요.","진하기는 25 %예요."],"mis":"M6-1-u4-X12","variant_rule":{"alt":[{"stem":"설탕 36 g을 물 84 g에 녹였어요. 설탕물 양에 대한 설탕 양의 비율(진하기)은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["설탕물은 물과 설탕을 합한 84 + 36 = 120 (g)이에요.","36 ÷ 120 × 100 = 30이에요.","진하기는 30 %예요."]},{"stem":"설탕 18 g을 물 102 g에 녹였어요. 설탕물 양에 대한 설탕 양의 비율(진하기)은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["설탕물은 물과 설탕을 합한 102 + 18 = 120 (g)이에요.","18 ÷ 120 × 100 = 15예요.","진하기는 15 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#10','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',4,'essay','teacher','가 치약은 원래 가격 3000원에서 900원, 나 치약은 원래 가격 5000원에서 1400원을 할인해요. 두 치약의 할인율을 구해 비교하고, 할인 금액이 더 큰 나 치약의 할인율이 더 작은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u4-C6","difficulty":4,"kind":"essay","stem":"가 치약은 원래 가격 3000원에서 900원, 나 치약은 원래 가격 5000원에서 1400원을 할인해요. 두 치약의 할인율을 구해 비교하고, 할인 금액이 더 큰 나 치약의 할인율이 더 작은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 가 치약은 900 ÷ 3000 × 100 = 30이므로 30 %, 나 치약은 1400 ÷ 5000 × 100 = 28이므로 28 %이다. 할인율은 가 치약이 더 크다. 원래 가격(기준량)이 다르므로 할인 금액이 커도 원래 가격에 대한 비율은 작을 수 있다.","scoring_points":["30 %와 28 %를 구했는가","가 치약의 할인율이 더 크다고 비교했는가","원래 가격(기준량)이 달라서라는 까닭을 썼는가"]},"explanation":["가 30 %, 나 28 %예요.","가 치약의 할인율이 더 커요.","원래 가격이 달라 금액으로는 비교할 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#1','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',1,'mc','auto','「구한 답을 다시 비율로 만들어 조건과 맞는지 보는 것」은 네 단계 가운데 어느 단계인가요?',ARRAY['M6-1-u4-X16']::text[],true,'{"seq":1,"concept":"M6-1-u4-C7","difficulty":1,"kind":"mc","stem":"「구한 답을 다시 비율로 만들어 조건과 맞는지 보는 것」은 네 단계 가운데 어느 단계인가요?","options":[{"t":"검토","correct":true},{"t":"이해","mis":"M6-1-u4-X16"},{"t":"계획","mis":"M6-1-u4-X16"},{"t":"해결","mis":"M6-1-u4-X16"}],"explanation":["백분율 문제는 이해 → 계획 → 해결 → 검토로 풀어요.","전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해요.","구한 답은 다시 비율로 만들어 조건과 견주어요."],"variant_rule":{"alt":[{"stem":"백분율 문제를 풀 때 맨 먼저 하는 단계는 어느 것인가요?","options":[{"t":"무엇을 구하는지 이해하기","correct":true},{"t":"답이 맞는지 검토하기","mis":"M6-1-u4-X16"},{"t":"식을 세워 계산하기","mis":"M6-1-u4-X16"},{"t":"답을 어림해 쓰기","mis":"M6-1-u4-X16"}],"explanation":["백분율 문제는 이해 → 계획 → 해결 → 검토로 풀어요.","전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해요.","구한 답은 다시 비율로 만들어 조건과 견주어요."]},{"stem":"전체를 100칸으로 볼 때 15 %는 무엇을 뜻하나요?","options":[{"t":"100칸 가운데 15칸","correct":true},{"t":"15칸 가운데 1칸","mis":"M6-1-u4-X13"},{"t":"한 칸의 크기가 15","mis":"M6-1-u4-X13"},{"t":"100칸 모두","mis":"M6-1-u4-X13"}],"explanation":["백분율 문제는 이해 → 계획 → 해결 → 검토로 풀어요.","전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해요.","구한 답은 다시 비율로 만들어 조건과 견주어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#2','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',1,'mc','auto','전체 발전량 3400000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":2,"concept":"M6-1-u4-C7","difficulty":1,"kind":"mc","stem":"전체 발전량 3400000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"34000 kWh","correct":true},{"t":"340000 kWh","mis":"M6-1-u4-X15"},{"t":"3400 kWh","mis":"M6-1-u4-X15"},{"t":"340000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","3400000 ÷ 100 = 34000이에요.","한 칸은 34000 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 2500000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"25000 kWh","correct":true},{"t":"250000 kWh","mis":"M6-1-u4-X15"},{"t":"2500 kWh","mis":"M6-1-u4-X15"},{"t":"250000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","2500000 ÷ 100 = 25000이에요.","한 칸은 25000 kWh예요."]},{"stem":"신재생 발전량 510000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"5100 kWh","correct":true},{"t":"51000 kWh","mis":"M6-1-u4-X15"},{"t":"510 kWh","mis":"M6-1-u4-X15"},{"t":"51000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","510000 ÷ 100 = 5100이에요.","한 칸은 5100 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#3','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',1,'sa','auto','검토해요. 신재생 에너지 510000 kWh를 다시 비율로 만들면 전체 3400000 kWh의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u4-C7","difficulty":1,"kind":"sa","stem":"검토해요. 신재생 에너지 510000 kWh를 다시 비율로 만들면 전체 3400000 kWh의 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["구한 답을 다시 비율로 만들어 조건과 견주어요.","510000 ÷ 3400000 × 100 = 15예요.","15 %라 조건과 맞아요."],"mis":"M6-1-u4-X08","variant_rule":{"alt":[{"stem":"검토해요. 태양광 에너지 244800 kWh를 다시 비율로 만들면 전체 510000 kWh의 몇 %인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["구한 답을 다시 비율로 만들어 조건과 견주어요.","244800 ÷ 510000 × 100 = 48이에요.","48 %라 조건과 맞아요."]},{"stem":"검토해요. 풍력 에너지 153000 kWh를 다시 비율로 만들면 전체 510000 kWh의 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["구한 답을 다시 비율로 만들어 조건과 견주어요.","153000 ÷ 510000 × 100 = 30이에요.","30 %라 조건과 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#4','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',1,'ox','auto','전체를 100칸으로 보면 15 %는 그중 15칸이에요.',ARRAY['M6-1-u4-X13']::text[],true,'{"seq":4,"concept":"M6-1-u4-C7","difficulty":1,"kind":"ox","stem":"전체를 100칸으로 보면 15 %는 그중 15칸이에요.","answer":"O","reason_options":[{"t":"백분율은 기준량을 100으로 할 때의 비율이기 때문에","correct":true},{"t":"15칸이 한 칸의 크기이기 때문에","mis":"M6-1-u4-X13"}],"mis":"M6-1-u4-X13","explanation":["전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해요.","몇 %는 몇 칸 — 한 칸 × 칸 수예요.","기준량이 무엇인지 늘 확인하고, 답은 다시 비율로 검토해요."],"variant_rule":{"alt":[{"stem":"구한 답을 다시 비율로 만들어 조건과 맞는지 보는 것이 검토예요.","answer":"O","reason_options":[{"t":"조건과 맞으면 답이 맞다고 확인할 수 있기 때문에","correct":true},{"t":"검토는 처음 문제를 읽는 단계이기 때문에","mis":"M6-1-u4-X16"}],"explanation":["전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해요.","몇 %는 몇 칸 — 한 칸 × 칸 수예요.","기준량이 무엇인지 늘 확인하고, 답은 다시 비율로 검토해요."]},{"stem":"어떤 양의 100 %는 그 양 전체예요.","answer":"O","reason_options":[{"t":"100칸 가운데 100칸이기 때문에","correct":true},{"t":"100 %는 100이라는 수이기 때문에","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해요.","몇 %는 몇 칸 — 한 칸 × 칸 수예요.","기준량이 무엇인지 늘 확인하고, 답은 다시 비율로 검토해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#5','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',2,'mc','auto','행복 지역의 전체 발전량은 3400000 kWh이고 그중 15 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X16']::text[],true,'{"seq":5,"concept":"M6-1-u4-C7","difficulty":2,"kind":"mc","stem":"행복 지역의 전체 발전량은 3400000 kWh이고 그중 15 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"510000 kWh","correct":true},{"t":"51000 kWh","mis":"M6-1-u4-X15"},{"t":"5100000 kWh","mis":"M6-1-u4-X15"},{"t":"2890000 kWh","mis":"M6-1-u4-X16"}],"explanation":["전체 3400000을 100칸으로 보면 한 칸은 3400000 ÷ 100 = 34000이에요.","15 %는 15칸이라 34000 × 15 = 510000이에요.","답은 510000 kWh예요."],"variant_rule":{"alt":[{"stem":"푸른 지역의 전체 발전량은 2500000 kWh이고 그중 20 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"500000 kWh","correct":true},{"t":"50000 kWh","mis":"M6-1-u4-X15"},{"t":"125000 kWh","mis":"M6-1-u4-X13"},{"t":"5000000 kWh","mis":"M6-1-u4-X15"}],"explanation":["전체 2500000을 100칸으로 보면 한 칸은 2500000 ÷ 100 = 25000이에요.","20 %는 20칸이라 25000 × 20 = 500000이에요.","답은 500000 kWh예요."]},{"stem":"맑은 지역의 전체 발전량은 4200000 kWh이고 그중 10 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"420000 kWh","correct":true},{"t":"42000 kWh","mis":"M6-1-u4-X15"},{"t":"4200000 kWh","mis":"M6-1-u4-X15"},{"t":"3780000 kWh","mis":"M6-1-u4-X16"}],"explanation":["전체 4200000을 100칸으로 보면 한 칸은 4200000 ÷ 100 = 42000이에요.","10 %는 10칸이라 42000 × 10 = 420000이에요.","답은 420000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#6','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',2,'sa','auto','우리 학교 6학년 학생 150명 가운데 18 %가 안경을 써요. 안경을 쓴 6학년 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C7","difficulty":2,"kind":"sa","stem":"우리 학교 6학년 학생 150명 가운데 18 %가 안경을 써요. 안경을 쓴 6학년 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["1 %인 한 칸은 150 ÷ 100 = 1.5예요.","18 %는 1.5 × 18 = 27이에요.","답은 27명이에요."],"mis":"M6-1-u4-X13","variant_rule":{"alt":[{"stem":"도서관 책 400권 가운데 12 %가 과학책이에요. 과학책은 몇 권인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["1 %인 한 칸은 400 ÷ 100 = 4예요.","12 %는 4 × 12 = 48이에요.","답은 48권이에요."]},{"stem":"텃밭 300 m² 가운데 25 %에 상추를 심었어요. 상추를 심은 넓이는 몇 m²인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["1 %인 한 칸은 300 ÷ 100 = 3이에요.","25 %는 3 × 25 = 75예요.","답은 75 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#7','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',2,'mc','auto','신재생 에너지 510000 kWh 가운데 48 %가 태양광 에너지예요. 태양광 발전량을 구할 때 기준량은 무엇인가요?',ARRAY['M6-1-u4-X14','M6-1-u4-X13']::text[],true,'{"seq":7,"concept":"M6-1-u4-C7","difficulty":2,"kind":"mc","stem":"신재생 에너지 510000 kWh 가운데 48 %가 태양광 에너지예요. 태양광 발전량을 구할 때 기준량은 무엇인가요?","options":[{"t":"신재생 발전량 510000","correct":true},{"t":"전체 발전량 3400000","mis":"M6-1-u4-X14"},{"t":"태양광의 백분율 48","mis":"M6-1-u4-X13"},{"t":"한 칸의 크기 34000","mis":"M6-1-u4-X13"}],"explanation":["「신재생 에너지 가운데 48 %」니 기준량은 신재생 발전량이에요.","조건이 바뀌면 기준량이 무엇인지 다시 확인해요.","처음 전체를 그대로 쓰면 다른 답이 나와요."],"variant_rule":{"alt":[{"stem":"전교생 600명 가운데 25 %가 6학년이고, 6학년의 40 %가 안경을 써요. 안경을 쓴 6학년 수를 구할 때 기준량은 무엇인가요?","options":[{"t":"6학년 학생 수 150","correct":true},{"t":"전교생 수 600","mis":"M6-1-u4-X14"},{"t":"안경 쓴 학생의 백분율 40","mis":"M6-1-u4-X13"},{"t":"6학년의 백분율 25","mis":"M6-1-u4-X13"}],"explanation":["「6학년의 40 %」니 기준량은 6학년 학생 수예요.","조건이 바뀌면 기준량이 무엇인지 다시 확인해요.","처음 전체를 그대로 쓰면 다른 답이 나와요."]},{"stem":"용돈 20000원 가운데 30 %를 책값으로 쓰고, 책값의 50 %가 만화책이에요. 만화책 값을 구할 때 기준량은 무엇인가요?","options":[{"t":"책값 6000원","correct":true},{"t":"용돈 20000원","mis":"M6-1-u4-X14"},{"t":"만화책의 백분율 50","mis":"M6-1-u4-X13"},{"t":"책값의 백분율 30","mis":"M6-1-u4-X13"}],"explanation":["「책값의 50 %」니 기준량은 책값이에요.","조건이 바뀌면 기준량이 무엇인지 다시 확인해요.","처음 전체를 그대로 쓰면 다른 답이 나와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#8','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',2,'ox','auto','전체 3400000 kWh의 15 %는 3400000 ÷ 15로 구해요.',ARRAY['M6-1-u4-X13']::text[],true,'{"seq":8,"concept":"M6-1-u4-C7","difficulty":2,"kind":"ox","stem":"전체 3400000 kWh의 15 %는 3400000 ÷ 15로 구해요.","answer":"X","reason_options":[{"t":"한 칸 3400000 ÷ 100 = 34000에 15를 곱해야 하기 때문에","correct":true},{"t":"15 %니 15로 나누면 되기 때문에","mis":"M6-1-u4-X13"}],"mis":"M6-1-u4-X13","explanation":["전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해요.","몇 %는 몇 칸 — 한 칸 × 칸 수예요.","기준량이 무엇인지 늘 확인하고, 답은 다시 비율로 검토해요."],"variant_rule":{"alt":[{"stem":"신재생 에너지의 48 %가 태양광이라면 기준량은 신재생 에너지 발전량이에요.","answer":"O","reason_options":[{"t":"「신재생 에너지의 48 %」이기 때문에","correct":true},{"t":"태양광이 48 %이기 때문에","mis":"M6-1-u4-X14"}],"explanation":["전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해요.","몇 %는 몇 칸 — 한 칸 × 칸 수예요.","기준량이 무엇인지 늘 확인하고, 답은 다시 비율로 검토해요."]},{"stem":"어떤 양의 20 %는 그 양의 15 %보다 작아요.","answer":"X","reason_options":[{"t":"기준량이 같으면 20칸이 15칸보다 많기 때문에","correct":true},{"t":"20 %는 ⟨1/20⟩이기 때문에","mis":"M6-1-u4-X15"}],"explanation":["전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해요.","몇 %는 몇 칸 — 한 칸 × 칸 수예요.","기준량이 무엇인지 늘 확인하고, 답은 다시 비율로 검토해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#9','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',2,'mc','auto','행복 지역의 신재생 에너지 비율이 15 %가 아니라 20 %라면 신재생 발전량은 몇 kWh가 되나요? (전체 3400000 kWh)',ARRAY['M6-1-u4-X16','M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":9,"concept":"M6-1-u4-C7","difficulty":2,"kind":"mc","stem":"행복 지역의 신재생 에너지 비율이 15 %가 아니라 20 %라면 신재생 발전량은 몇 kWh가 되나요? (전체 3400000 kWh)","options":[{"t":"680000 kWh","correct":true},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"68000 kWh","mis":"M6-1-u4-X15"},{"t":"170000 kWh","mis":"M6-1-u4-X13"}],"explanation":["1 %인 한 칸은 3400000 ÷ 100 = 34000이에요.","20 %는 34000 × 20 = 680000이에요.","조건이 바뀌면 칸 수부터 다시 세어요."],"variant_rule":{"alt":[{"stem":"행복 지역의 신재생 에너지 비율이 15 %에서 25 %로 늘면 신재생 발전량은 몇 kWh가 되나요? (전체 3400000 kWh)","options":[{"t":"850000 kWh","correct":true},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"85000 kWh","mis":"M6-1-u4-X15"},{"t":"340000 kWh","mis":"M6-1-u4-X13"}],"explanation":["1 %인 한 칸은 3400000 ÷ 100 = 34000이에요.","25 %는 34000 × 25 = 850000이에요.","조건이 바뀌면 칸 수부터 다시 세어요."]},{"stem":"푸른 지역의 신재생 에너지 비율이 20 %에서 30 %로 늘면 신재생 발전량은 몇 kWh가 되나요? (전체 2500000 kWh)","options":[{"t":"750000 kWh","correct":true},{"t":"500000 kWh","mis":"M6-1-u4-X16"},{"t":"75000 kWh","mis":"M6-1-u4-X15"},{"t":"250000 kWh","mis":"M6-1-u4-X13"}],"explanation":["1 %인 한 칸은 2500000 ÷ 100 = 25000이에요.","30 %는 25000 × 30 = 750000이에요.","조건이 바뀌면 칸 수부터 다시 세어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#10','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',3,'mc','auto','전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 48 %가 태양광이에요. 태양광 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X14','M6-1-u4-X16']::text[],true,'{"seq":10,"concept":"M6-1-u4-C7","difficulty":3,"kind":"mc","stem":"전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 48 %가 태양광이에요. 태양광 발전량은 몇 kWh인가요?","options":[{"t":"244800 kWh","correct":true},{"t":"1632000 kWh","mis":"M6-1-u4-X14"},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"2142000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 3400000 × 15 ÷ 100 = 510000이에요.","기준량이 510000으로 바뀌어요 — 510000 × 48 ÷ 100 = 244800이에요.","답은 244800 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 30 %가 풍력이에요. 풍력 발전량은 몇 kWh인가요?","options":[{"t":"153000 kWh","correct":true},{"t":"1020000 kWh","mis":"M6-1-u4-X14"},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"1530000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 3400000 × 15 ÷ 100 = 510000이에요.","기준량이 510000으로 바뀌어요 — 510000 × 30 ÷ 100 = 153000이에요.","답은 153000 kWh예요."]},{"stem":"전체 발전량 2000000 kWh의 20 %가 신재생 에너지이고, 신재생 에너지의 40 %가 수력이에요. 수력 발전량은 몇 kWh인가요?","options":[{"t":"160000 kWh","correct":true},{"t":"800000 kWh","mis":"M6-1-u4-X14"},{"t":"400000 kWh","mis":"M6-1-u4-X16"},{"t":"1200000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 2000000 × 20 ÷ 100 = 400000이에요.","기준량이 400000으로 바뀌어요 — 400000 × 40 ÷ 100 = 160000이에요.","답은 160000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#1','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',2,'sa','auto','주스 250 mL 가운데 20 %가 과일 원액이에요. 과일 원액은 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C7","difficulty":2,"kind":"sa","stem":"주스 250 mL 가운데 20 %가 과일 원액이에요. 과일 원액은 몇 mL인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["1 %인 한 칸은 250 ÷ 100 = 2.5예요.","20 %는 2.5 × 20 = 50이에요.","답은 50 mL예요."],"mis":"M6-1-u4-X13","variant_rule":{"alt":[{"stem":"학생 80명 가운데 45 %가 걸어서 학교에 와요. 걸어서 오는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["1 %인 한 칸은 80 ÷ 100 = 0.8이에요.","45 %는 0.8 × 45 = 36이에요.","답은 36명이에요."]},{"stem":"씨앗 200개 가운데 35 %가 싹을 틔웠어요. 싹 튼 씨앗은 몇 개인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["1 %인 한 칸은 200 ÷ 100 = 2예요.","35 %는 2 × 35 = 70이에요.","답은 70개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#2','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',2,'mc','auto','용돈 5000원 가운데 30 %를 저금했어요. 남은 돈은 얼마인가요?',ARRAY['M6-1-u4-X16','M6-1-u4-X13']::text[],true,'{"seq":2,"concept":"M6-1-u4-C7","difficulty":2,"kind":"mc","stem":"용돈 5000원 가운데 30 %를 저금했어요. 남은 돈은 얼마인가요?","options":[{"t":"3500원","correct":true},{"t":"1500원","mis":"M6-1-u4-X16"},{"t":"4970원","mis":"M6-1-u4-X13"},{"t":"6500원","mis":"M6-1-u4-X16"}],"explanation":["30 %는 5000 × 30 ÷ 100 = 1500 (원)이에요.","남은 돈은 5000 − 1500 = 3500 (원)이에요.","남은 돈은 3500원이에요."],"variant_rule":{"alt":[{"stem":"용돈 20000원 가운데 15 %를 책을 사는 데 썼어요. 남은 돈은 얼마인가요?","options":[{"t":"17000원","correct":true},{"t":"3000원","mis":"M6-1-u4-X16"},{"t":"19985원","mis":"M6-1-u4-X13"},{"t":"23000원","mis":"M6-1-u4-X16"}],"explanation":["15 %는 20000 × 15 ÷ 100 = 3000 (원)이에요.","남은 돈은 20000 − 3000 = 17000 (원)이에요.","남은 돈은 17000원이에요."]},{"stem":"받은 상금 8000원 가운데 25 %를 기부했어요. 남은 돈은 얼마인가요?","options":[{"t":"6000원","correct":true},{"t":"2000원","mis":"M6-1-u4-X16"},{"t":"7975원","mis":"M6-1-u4-X13"},{"t":"10000원","mis":"M6-1-u4-X16"}],"explanation":["25 %는 8000 × 25 ÷ 100 = 2000 (원)이에요.","남은 돈은 8000 − 2000 = 6000 (원)이에요.","남은 돈은 6000원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#3','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',3,'error','auto','전체 발전량 3400000 kWh의 15 %를 구하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X13','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C7","difficulty":3,"kind":"error","stem":"전체 발전량 3400000 kWh의 15 %를 구하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「3400000 ÷ 15를 계산하면 돼.」","correct":true,"mis_target":"M6-1-u4-X13"},{"t":"이현 — 「한 칸은 3400000 ÷ 100 = 34000이야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「답은 510000 kWh야.」","mis":"M6-1-u4-X16"}],"explanation":["1 %인 한 칸은 3400000 ÷ 100 = 34000이에요.","15 %는 34000 × 15 = 510000이에요.","준희는 전체를 15로 나누었어요."],"variant_rule":{"alt":[{"stem":"전체 발전량 2500000 kWh의 20 %를 구하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「2500000 ÷ 20을 계산하면 돼.」","correct":true,"mis_target":"M6-1-u4-X13"},{"t":"수아 — 「한 칸은 2500000 ÷ 100 = 25000이야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「답은 500000 kWh야.」","mis":"M6-1-u4-X16"}],"explanation":["1 %인 한 칸은 2500000 ÷ 100 = 25000이에요.","20 %는 25000 × 20 = 500000이에요.","서호는 전체를 20으로 나누었어요."]},{"stem":"신재생 발전량 510000 kWh의 30 %를 구하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「510000 ÷ 30을 계산하면 돼.」","correct":true,"mis_target":"M6-1-u4-X13"},{"t":"나린 — 「한 칸은 510000 ÷ 100 = 5100이야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「답은 153000 kWh야.」","mis":"M6-1-u4-X16"}],"explanation":["1 %인 한 칸은 510000 ÷ 100 = 5100이에요.","30 %는 5100 × 30 = 153000이에요.","가온은 전체를 30으로 나누었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#4','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',3,'mc','auto','신재생 에너지 510000 kWh 가운데 30 %가 풍력 에너지예요. 풍력 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":4,"concept":"M6-1-u4-C7","difficulty":3,"kind":"mc","stem":"신재생 에너지 510000 kWh 가운데 30 %가 풍력 에너지예요. 풍력 발전량은 몇 kWh인가요?","options":[{"t":"153000 kWh","correct":true},{"t":"15300 kWh","mis":"M6-1-u4-X15"},{"t":"17000 kWh","mis":"M6-1-u4-X13"},{"t":"1530000 kWh","mis":"M6-1-u4-X15"}],"explanation":["전체 510000을 100칸으로 보면 한 칸은 510000 ÷ 100 = 5100이에요.","30 %는 30칸이라 5100 × 30 = 153000이에요.","답은 153000 kWh예요."],"variant_rule":{"alt":[{"stem":"신재생 에너지 510000 kWh 가운데 48 %가 태양광 에너지예요. 태양광 발전량은 몇 kWh인가요?","options":[{"t":"244800 kWh","correct":true},{"t":"24480 kWh","mis":"M6-1-u4-X15"},{"t":"10625 kWh","mis":"M6-1-u4-X13"},{"t":"2448000 kWh","mis":"M6-1-u4-X15"}],"explanation":["전체 510000을 100칸으로 보면 한 칸은 510000 ÷ 100 = 5100이에요.","48 %는 48칸이라 5100 × 48 = 244800이에요.","답은 244800 kWh예요."]},{"stem":"한 공장의 전체 사용 전력은 800000 kWh이고 그중 35 %를 태양광으로 만들어요. 태양광으로 만든 전력은 몇 kWh인가요?","options":[{"t":"280000 kWh","correct":true},{"t":"28000 kWh","mis":"M6-1-u4-X15"},{"t":"2800000 kWh","mis":"M6-1-u4-X15"},{"t":"520000 kWh","mis":"M6-1-u4-X16"}],"explanation":["전체 800000을 100칸으로 보면 한 칸은 800000 ÷ 100 = 8000이에요.","35 %는 35칸이라 8000 × 35 = 280000이에요.","답은 280000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#5','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',3,'mc','auto','전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 30 %가 풍력이에요. 풍력 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X14','M6-1-u4-X16']::text[],true,'{"seq":5,"concept":"M6-1-u4-C7","difficulty":3,"kind":"mc","stem":"전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 30 %가 풍력이에요. 풍력 발전량은 몇 kWh인가요?","options":[{"t":"153000 kWh","correct":true},{"t":"1020000 kWh","mis":"M6-1-u4-X14"},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"1530000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 3400000 × 15 ÷ 100 = 510000이에요.","기준량이 510000으로 바뀌어요 — 510000 × 30 ÷ 100 = 153000이에요.","답은 153000 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 5000000 kWh의 12 %가 신재생 에너지이고, 신재생 에너지의 25 %가 지열이에요. 지열 발전량은 몇 kWh인가요?","options":[{"t":"150000 kWh","correct":true},{"t":"1250000 kWh","mis":"M6-1-u4-X14"},{"t":"600000 kWh","mis":"M6-1-u4-X16"},{"t":"1850000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 5000000 × 12 ÷ 100 = 600000이에요.","기준량이 600000으로 바뀌어요 — 600000 × 25 ÷ 100 = 150000이에요.","답은 150000 kWh예요."]},{"stem":"전체 발전량 2000000 kWh의 20 %가 신재생 에너지이고, 신재생 에너지의 40 %가 수력이에요. 수력 발전량은 몇 kWh인가요?","options":[{"t":"160000 kWh","correct":true},{"t":"800000 kWh","mis":"M6-1-u4-X14"},{"t":"400000 kWh","mis":"M6-1-u4-X16"},{"t":"1200000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 2000000 × 20 ÷ 100 = 400000이에요.","기준량이 400000으로 바뀌어요 — 400000 × 40 ÷ 100 = 160000이에요.","답은 160000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#6','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',3,'sa','auto','어떤 수의 25 %가 20이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C7","difficulty":3,"kind":"sa","stem":"어떤 수의 25 %가 20이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["어떤 수를 100칸으로 보면 25칸이 20이에요.","한 칸은 20 ÷ 25 = 0.8이에요.","100칸은 0.8 × 100 = 80이에요."],"mis":"M6-1-u4-X13","variant_rule":{"alt":[{"stem":"어떤 수의 50 %가 36이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["어떤 수를 100칸으로 보면 50칸이 36이에요.","한 칸은 36 ÷ 50 = 0.72예요.","100칸은 0.72 × 100 = 72예요."]},{"stem":"어떤 수의 20 %가 9예요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["어떤 수를 100칸으로 보면 20칸이 9예요.","한 칸은 9 ÷ 20 = 0.45예요.","100칸은 0.45 × 100 = 45예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#7','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',3,'mc','auto','행복 지역의 신재생 에너지 비율이 15 %에서 25 %로 늘면 신재생 발전량은 몇 kWh가 되나요? (전체 3400000 kWh)',ARRAY['M6-1-u4-X16','M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":7,"concept":"M6-1-u4-C7","difficulty":3,"kind":"mc","stem":"행복 지역의 신재생 에너지 비율이 15 %에서 25 %로 늘면 신재생 발전량은 몇 kWh가 되나요? (전체 3400000 kWh)","options":[{"t":"850000 kWh","correct":true},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"85000 kWh","mis":"M6-1-u4-X15"},{"t":"340000 kWh","mis":"M6-1-u4-X13"}],"explanation":["1 %인 한 칸은 3400000 ÷ 100 = 34000이에요.","25 %는 34000 × 25 = 850000이에요.","조건이 바뀌면 칸 수부터 다시 세어요."],"variant_rule":{"alt":[{"stem":"푸른 지역의 신재생 에너지 비율이 20 %에서 30 %로 늘면 신재생 발전량은 몇 kWh가 되나요? (전체 2500000 kWh)","options":[{"t":"750000 kWh","correct":true},{"t":"500000 kWh","mis":"M6-1-u4-X16"},{"t":"75000 kWh","mis":"M6-1-u4-X15"},{"t":"250000 kWh","mis":"M6-1-u4-X13"}],"explanation":["1 %인 한 칸은 2500000 ÷ 100 = 25000이에요.","30 %는 25000 × 30 = 750000이에요.","조건이 바뀌면 칸 수부터 다시 세어요."]},{"stem":"맑은 지역의 신재생 에너지 비율이 10 %에서 15 %로 늘면 신재생 발전량은 몇 kWh가 되나요? (전체 4200000 kWh)","options":[{"t":"630000 kWh","correct":true},{"t":"420000 kWh","mis":"M6-1-u4-X16"},{"t":"63000 kWh","mis":"M6-1-u4-X15"},{"t":"210000 kWh","mis":"M6-1-u4-X13"}],"explanation":["1 %인 한 칸은 4200000 ÷ 100 = 42000이에요.","15 %는 42000 × 15 = 630000이에요.","조건이 바뀌면 칸 수부터 다시 세어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#8','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',4,'mc','auto','가 지역은 전체 발전량 2000000 kWh 가운데 20 %, 나 지역은 전체 발전량 3000000 kWh 가운데 15 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":8,"concept":"M6-1-u4-C7","difficulty":4,"kind":"mc","stem":"가 지역은 전체 발전량 2000000 kWh 가운데 20 %, 나 지역은 전체 발전량 3000000 kWh 가운데 15 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"나 지역","correct":true},{"t":"가 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","가 2000000 × 20 ÷ 100 = 400000, 나 3000000 × 15 ÷ 100 = 450000이에요.","발전량이 더 많은 곳은 나 지역이에요."],"variant_rule":{"alt":[{"stem":"다 지역은 전체 발전량 5000000 kWh 가운데 12 %, 라 지역은 전체 발전량 4000000 kWh 가운데 14 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"다 지역","correct":true},{"t":"라 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","다 5000000 × 12 ÷ 100 = 600000, 라 4000000 × 14 ÷ 100 = 560000이에요.","발전량이 더 많은 곳은 다 지역이에요."]},{"stem":"마 지역은 전체 발전량 1500000 kWh 가운데 30 %, 바 지역은 전체 발전량 2500000 kWh 가운데 20 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"바 지역","correct":true},{"t":"마 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","마 1500000 × 30 ÷ 100 = 450000, 바 2500000 × 20 ÷ 100 = 500000이에요.","발전량이 더 많은 곳은 바 지역이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#9','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',4,'sa','auto','어떤 수의 40 %가 24예요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u4-C7","difficulty":4,"kind":"sa","stem":"어떤 수의 40 %가 24예요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["어떤 수를 100칸으로 보면 40칸이 24예요.","한 칸은 24 ÷ 40 = 0.6이에요.","100칸은 0.6 × 100 = 60이에요."],"mis":"M6-1-u4-X13","variant_rule":{"alt":[{"stem":"어떤 수의 60 %가 33이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["어떤 수를 100칸으로 보면 60칸이 33이에요.","한 칸은 33 ÷ 60 = 0.55예요.","100칸은 0.55 × 100 = 55예요."]},{"stem":"어떤 수의 75 %가 60이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["어떤 수를 100칸으로 보면 75칸이 60이에요.","한 칸은 60 ÷ 75 = 0.8이에요.","100칸은 0.8 × 100 = 80이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#10','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',4,'essay','teacher','행복 지역의 전체 발전량은 3400000 kWh이고 그중 15 %가 신재생 에너지예요. 전체를 100칸으로 보는 방법으로 신재생 에너지 발전량을 구하고, 구한 답이 맞는지 검토하는 방법도 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u4-C7","difficulty":4,"kind":"essay","stem":"행복 지역의 전체 발전량은 3400000 kWh이고 그중 15 %가 신재생 에너지예요. 전체를 100칸으로 보는 방법으로 신재생 에너지 발전량을 구하고, 구한 답이 맞는지 검토하는 방법도 써 보세요.","answer_guide":{"answer":"예: 전체를 100칸으로 보면 한 칸은 3400000 ÷ 100 = 34000 (kWh)이다. 15 %는 15칸이므로 34000 × 15 = 510000 (kWh)이다. 검토: 510000 ÷ 3400000 × 100 = 15이므로 조건 15 %와 맞는다.","scoring_points":["한 칸 34000을 구했는가","510000 kWh를 구했는가","다시 비율로 만들어 15 %와 맞는지 검토했는가"]},"explanation":["한 칸은 34000 kWh예요.","15칸은 510000 kWh예요.","510000 ÷ 3400000 × 100 = 15로 검토해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#1','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C2',1,'mc','auto','바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 어느 것인가요?',ARRAY['M6-1-u4-X01','M6-1-u4-X03']::text[],true,'{"seq":1,"concept":"M6-1-u4-C2","difficulty":1,"kind":"mc","stem":"바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 어느 것인가요?","options":[{"t":"6：150","correct":true},{"t":"150：6","mis":"M6-1-u4-X01"},{"t":"6：144","mis":"M6-1-u4-X03"},{"t":"25：1","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 바닷물 양이에요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 6：150이에요."],"variant_rule":{"alt":[{"stem":"팔찌 하나에 파란 구슬 2개와 노란 구슬 10개를 꿰어요. 파란 구슬 수와 노란 구슬 수의 비는 어느 것인가요?","options":[{"t":"2：10","correct":true},{"t":"10：2","mis":"M6-1-u4-X01"},{"t":"2：8","mis":"M6-1-u4-X03"},{"t":"5：1","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 노란 구슬 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 2：10이에요."]},{"stem":"닭 2마리와 병아리 5마리가 있어요. 닭 수에 대한 병아리 수의 비는 어느 것인가요?","options":[{"t":"5：2","correct":true},{"t":"2：5","mis":"M6-1-u4-X01"},{"t":"5：7","mis":"M6-1-u4-X07"},{"t":"3：5","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 닭 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 5：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#2','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C2',1,'sa','auto','비 2：10에서 기준량은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u4-C2","difficulty":1,"kind":"sa","stem":"비 2：10에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","2：10에서 전항은 2, 후항은 10이에요.","그래서 기준량은 10이에요."],"mis":"M6-1-u4-X01","variant_rule":{"alt":[{"stem":"비 9：20에서 후항은 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","9：20에서 전항은 9, 후항은 20이에요.","그래서 후항은 20이에요."]},{"stem":"비 13：23에서 전항은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","13：23에서 전항은 13, 후항은 23이에요.","그래서 전항은 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#3','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C3',1,'mc','auto','비 3：10의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C3","difficulty":1,"kind":"mc","stem":"비 3：10의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"3","mis":"M6-1-u4-X15"},{"t":"0.03","mis":"M6-1-u4-X15"},{"t":"0.7","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","3：10의 비율은 3 ÷ 10 = 0.3이에요.","분수로는 ⟨3/10⟩, 소수로는 0.3이에요."],"variant_rule":{"alt":[{"stem":"비 1：4의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.25","correct":true},{"t":"4","mis":"M6-1-u4-X05"},{"t":"2.5","mis":"M6-1-u4-X15"},{"t":"0.025","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","1：4의 비율은 1 ÷ 4 = 0.25예요.","분수로는 ⟨1/4⟩, 소수로는 0.25예요."]},{"stem":"비 6：5의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"1.2","correct":true},{"t":"12","mis":"M6-1-u4-X15"},{"t":"0.12","mis":"M6-1-u4-X15"},{"t":"2.2","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","6：5의 비율은 6 ÷ 5 = 1.2예요.","분수로는 ⟨6/5⟩, 소수로는 1.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#4','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C4',1,'mc','auto','푸른 팀은 15경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":4,"concept":"M6-1-u4-C4","difficulty":1,"kind":"mc","stem":"푸른 팀은 15경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"2.5","mis":"M6-1-u4-X05"},{"t":"0.6","mis":"M6-1-u4-X16"},{"t":"4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 15, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/15⟩ = 0.4예요.","푸른 팀의 비율은 0.4예요."],"variant_rule":{"alt":[{"stem":"노란 팀은 20경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"0.7","mis":"M6-1-u4-X16"},{"t":"3","mis":"M6-1-u4-X15"},{"t":"0.03","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 20, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/20⟩ = 0.3이에요.","노란 팀의 비율은 0.3이에요."]},{"stem":"초록 팀은 10경기를 치러서 5경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.5","correct":true},{"t":"2","mis":"M6-1-u4-X05"},{"t":"1","mis":"M6-1-u4-X07"},{"t":"5","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 10, 비교하는 양은 이긴 경기 수 5예요.","⟨5/10⟩ = 0.5예요.","초록 팀의 비율은 0.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#5','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C5',1,'mc','auto','비율 0.35를 백분율로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":5,"concept":"M6-1-u4-C5","difficulty":1,"kind":"mc","stem":"비율 0.35를 백분율로 나타내면 얼마인가요?","options":[{"t":"35 %","correct":true},{"t":"3.5 %","mis":"M6-1-u4-X08"},{"t":"0.35 %","mis":"M6-1-u4-X08"},{"t":"350 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.35 × 100 = 35예요.","그래서 35 %예요."],"variant_rule":{"alt":[{"stem":"비율 0.83을 백분율로 나타내면 얼마인가요?","options":[{"t":"83 %","correct":true},{"t":"8.3 %","mis":"M6-1-u4-X08"},{"t":"0.83 %","mis":"M6-1-u4-X08"},{"t":"830 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.83 × 100 = 83이에요.","그래서 83 %예요."]},{"stem":"비율 0.6을 백분율로 나타내면 얼마인가요?","options":[{"t":"60 %","correct":true},{"t":"6 %","mis":"M6-1-u4-X08"},{"t":"0.6 %","mis":"M6-1-u4-X08"},{"t":"600 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.6 × 100 = 60이에요.","그래서 60 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#6','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C6',1,'sa','auto','학급 회장 선거에서 전체 30표 가운데 건우가 18표를 받았어요. 건우의 득표율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C6","difficulty":1,"kind":"sa","stem":"학급 회장 선거에서 전체 30표 가운데 건우가 18표를 받았어요. 건우의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","18 ÷ 30 × 100 = 60이에요.","건우의 득표율은 60 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"학급 회장 선거에서 전체 30표 가운데 수빈이가 12표를 받았어요. 수빈이의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","12 ÷ 30 × 100 = 40이에요.","수빈이의 득표율은 40 %예요."]},{"stem":"학급 회장 선거에서 전체 25표 가운데 하늘이 9표를 받았어요. 하늘의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","9 ÷ 25 × 100 = 36이에요.","하늘의 득표율은 36 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#7','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C7',1,'mc','auto','전체 발전량 3400000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":7,"concept":"M6-1-u4-C7","difficulty":1,"kind":"mc","stem":"전체 발전량 3400000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"34000 kWh","correct":true},{"t":"340000 kWh","mis":"M6-1-u4-X15"},{"t":"3400 kWh","mis":"M6-1-u4-X15"},{"t":"340000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","3400000 ÷ 100 = 34000이에요.","한 칸은 34000 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 2500000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"25000 kWh","correct":true},{"t":"250000 kWh","mis":"M6-1-u4-X15"},{"t":"2500 kWh","mis":"M6-1-u4-X15"},{"t":"250000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","2500000 ÷ 100 = 25000이에요.","한 칸은 25000 kWh예요."]},{"stem":"신재생 발전량 510000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"5100 kWh","correct":true},{"t":"51000 kWh","mis":"M6-1-u4-X15"},{"t":"510 kWh","mis":"M6-1-u4-X15"},{"t":"51000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","510000 ÷ 100 = 5100이에요.","한 칸은 5100 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#8','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C1',1,'sa','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 나눗셈으로 비교하면 물은 매실 원액의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u4-C1","difficulty":1,"kind":"sa","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 나눗셈으로 비교하면 물은 매실 원액의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","4 ÷ 1 = 4예요.","물은 매실 원액의 4배예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 나눗셈으로 비교하면 노란 구슬은 파란 구슬의 몇 배인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","10 ÷ 2 = 5예요.","노란 구슬은 파란 구슬의 5배예요."]},{"stem":"꽃다발 한 개에는 안개꽃 12송이와 장미 3송이가 들어가요. 나눗셈으로 비교하면 안개꽃은 장미의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","12 ÷ 3 = 4예요.","안개꽃은 장미의 4배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#9','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C3',2,'mc','auto','집에서 할머니 댁까지는 20 km, 집에서 주유소까지는 8 km예요. 집과 할머니 댁 사이 거리에 대한 집과 주유소 사이 거리의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":9,"concept":"M6-1-u4-C3","difficulty":2,"kind":"mc","stem":"집에서 할머니 댁까지는 20 km, 집에서 주유소까지는 8 km예요. 집과 할머니 댁 사이 거리에 대한 집과 주유소 사이 거리의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"2.5","mis":"M6-1-u4-X05"},{"t":"0.6","mis":"M6-1-u4-X16"},{"t":"4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 20, 비교하는 양은 8이에요.","8 ÷ 20 = 0.4예요.","그래서 비율은 0.4예요."],"variant_rule":{"alt":[{"stem":"가로 40 cm, 세로 24 cm인 태극기 액자가 있어요. 가로에 대한 세로의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.6","correct":true},{"t":"0.4","mis":"M6-1-u4-X16"},{"t":"6","mis":"M6-1-u4-X15"},{"t":"0.06","mis":"M6-1-u4-X15"}],"explanation":["기준량은 40, 비교하는 양은 24예요.","24 ÷ 40 = 0.6이에요.","그래서 비율은 0.6이에요."]},{"stem":"마을 자전거 도로 15 km 가운데 12 km가 완성되었어요. 전체 길이에 대한 완성된 길이의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"1.25","mis":"M6-1-u4-X05"},{"t":"0.2","mis":"M6-1-u4-X16"},{"t":"8","mis":"M6-1-u4-X15"}],"explanation":["기준량은 15, 비교하는 양은 12예요.","12 ÷ 15 = 0.8이에요.","그래서 비율은 0.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#10','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C4',2,'sa','auto','자율 주행 자동차가 2시간 동안 160 km를 이동했어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u4-C4","difficulty":2,"kind":"sa","stem":"자율 주행 자동차가 2시간 동안 160 km를 이동했어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["기준량은 이동한 시간 2, 비교하는 양은 이동한 거리 160이에요.","160 ÷ 2 = 80이에요.","1시간에 80 km만큼 이동한 셈이에요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"자전거로 3시간 동안 12 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["기준량은 이동한 시간 3, 비교하는 양은 이동한 거리 12예요.","12 ÷ 3 = 4예요.","1시간에 4 km만큼 이동한 셈이에요."]},{"stem":"기차가 2시간 동안 180 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["기준량은 이동한 시간 2, 비교하는 양은 이동한 거리 180이에요.","180 ÷ 2 = 90이에요.","1시간에 90 km만큼 이동한 셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#11','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C5',2,'sa','auto','우리 반 20명 가운데 15명이 이번 주에 도서관을 이용했어요. 전체 학생 수에 대한 이용한 학생 수의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"우리 반 20명 가운데 15명이 이번 주에 도서관을 이용했어요. 전체 학생 수에 대한 이용한 학생 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["기준량은 20, 비교하는 양은 15예요.","15 ÷ 20 × 100 = 75예요.","그래서 75 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"전체 25칸인 모눈에서 16칸을 색칠했어요. 전체 모눈 수에 대한 색칠한 모눈 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["기준량은 25, 비교하는 양은 16이에요.","16 ÷ 25 × 100 = 64예요.","그래서 64 %예요."]},{"stem":"수학 문제 40개 가운데 34개를 맞혔어요. 전체 문제 수에 대한 맞힌 문제 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["기준량은 40, 비교하는 양은 34예요.","34 ÷ 40 × 100 = 85예요.","그래서 85 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#12','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C5',2,'sa','auto','비율 ⟨16/25⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"비율 ⟨16/25⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 4를 곱해요.","⟨16/25⟩ = ⟨64/100⟩예요.","그래서 ⟨16/25⟩은 64 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"비율 ⟨3/4⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 25를 곱해요.","⟨3/4⟩ = ⟨75/100⟩예요.","그래서 ⟨3/4⟩은 75 %예요."]},{"stem":"비율 ⟨9/20⟩를 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 5를 곱해요.","⟨9/20⟩ = ⟨45/100⟩예요.","그래서 ⟨9/20⟩는 45 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#13','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C6',2,'sa','auto','가 치약은 원래 가격 3000원에서 900원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"가 치약은 원래 가격 3000원에서 900원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","900 ÷ 3000 × 100 = 30이에요.","할인율은 30 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"공책은 원래 가격 2000원에서 300원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","300 ÷ 2000 × 100 = 15예요.","할인율은 15 %예요."]},{"stem":"필통은 원래 가격 8000원에서 2000원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","2000 ÷ 8000 × 100 = 25예요.","할인율은 25 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#14','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C6',2,'sa','auto','지후는 설탕 210 g을 녹여 설탕물 750 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"지후는 설탕 210 g을 녹여 설탕물 750 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["기준량은 설탕물 750 g, 비교하는 양은 설탕 210 g이에요.","210 ÷ 750 × 100 = 28이에요.","설탕물의 진하기는 28 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"예은은 설탕 36 g을 녹여 설탕물 200 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["기준량은 설탕물 200 g, 비교하는 양은 설탕 36 g이에요.","36 ÷ 200 × 100 = 18이에요.","설탕물의 진하기는 18 %예요."]},{"stem":"민서는 설탕 45 g을 녹여 설탕물 300 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["기준량은 설탕물 300 g, 비교하는 양은 설탕 45 g이에요.","45 ÷ 300 × 100 = 15예요.","설탕물의 진하기는 15 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#15','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C2',2,'ox','auto','3：4와 4：3은 같은 비예요.',ARRAY['M6-1-u4-X02']::text[],true,'{"seq":15,"concept":"M6-1-u4-C2","difficulty":2,"kind":"ox","stem":"3：4와 4：3은 같은 비예요.","answer":"X","reason_options":[{"t":"기준량이 4와 3으로 달라 서로 다른 비이기 때문에","correct":true},{"t":"두 비에 같은 수가 들어 있기 때문에","mis":"M6-1-u4-X02"}],"mis":"M6-1-u4-X02","explanation":["두 양의 변하지 않는 관계를 기호 ：로 나타낸 것이 비예요.","：의 앞은 비교하는 양(전항), 뒤는 기준량(후항)이에요.","「○에 대한」 쪽이 기준량이에요."],"variant_rule":{"alt":[{"stem":"비율은 언제나 1보다 작아요.","answer":"X","reason_options":[{"t":"12：5의 비율 2.4처럼 비교하는 양이 더 크면 1보다 크기 때문에","correct":true},{"t":"비율은 전체의 일부만 나타내기 때문에","mis":"M6-1-u4-X06"}],"explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."]},{"stem":"비율 0.07을 백분율로 나타내면 70 %예요.","answer":"X","reason_options":[{"t":"0.07 × 100 = 7이라 7 %이기 때문에","correct":true},{"t":"0.07의 7 뒤에 0을 붙이면 되기 때문에","mis":"M6-1-u4-X08"}],"explanation":["기준량을 100으로 할 때의 비율을 백분율이라 하고 %를 써요.","비율에 100을 곱해서 나온 값에 %를 붙여요.","기준량이 100인 분수로 바꾸어도 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#16','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C7',2,'mc','auto','행복 지역의 전체 발전량은 3400000 kWh이고 그중 15 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X16']::text[],true,'{"seq":16,"concept":"M6-1-u4-C7","difficulty":2,"kind":"mc","stem":"행복 지역의 전체 발전량은 3400000 kWh이고 그중 15 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"510000 kWh","correct":true},{"t":"51000 kWh","mis":"M6-1-u4-X15"},{"t":"5100000 kWh","mis":"M6-1-u4-X15"},{"t":"2890000 kWh","mis":"M6-1-u4-X16"}],"explanation":["전체 3400000을 100칸으로 보면 한 칸은 3400000 ÷ 100 = 34000이에요.","15 %는 15칸이라 34000 × 15 = 510000이에요.","답은 510000 kWh예요."],"variant_rule":{"alt":[{"stem":"푸른 지역의 전체 발전량은 2500000 kWh이고 그중 20 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"500000 kWh","correct":true},{"t":"50000 kWh","mis":"M6-1-u4-X15"},{"t":"125000 kWh","mis":"M6-1-u4-X13"},{"t":"5000000 kWh","mis":"M6-1-u4-X15"}],"explanation":["전체 2500000을 100칸으로 보면 한 칸은 2500000 ÷ 100 = 25000이에요.","20 %는 20칸이라 25000 × 20 = 500000이에요.","답은 500000 kWh예요."]},{"stem":"맑은 지역의 전체 발전량은 4200000 kWh이고 그중 10 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"420000 kWh","correct":true},{"t":"42000 kWh","mis":"M6-1-u4-X15"},{"t":"4200000 kWh","mis":"M6-1-u4-X15"},{"t":"3780000 kWh","mis":"M6-1-u4-X16"}],"explanation":["전체 4200000을 100칸으로 보면 한 칸은 4200000 ÷ 100 = 42000이에요.","10 %는 10칸이라 42000 × 10 = 420000이에요.","답은 420000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#17','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C4',3,'mc','auto','가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":17,"concept":"M6-1-u4-C4","difficulty":3,"kind":"mc","stem":"가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"가 마을","correct":true},{"t":"나 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","가 6000 ÷ 2 = 3000, 나 7500 ÷ 3 = 2500이에요.","비율이 큰 가 마을이 더 빽빽해요."],"variant_rule":{"alt":[{"stem":"다 마을은 넓이 4 km²에 10000명, 라 마을은 넓이 5 km²에 11000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"다 마을","correct":true},{"t":"라 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","다 10000 ÷ 4 = 2500, 라 11000 ÷ 5 = 2200이에요.","비율이 큰 다 마을이 더 빽빽해요."]},{"stem":"바 마을은 넓이 4 km²에 7200명, 마 마을은 넓이 6 km²에 9000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"바 마을","correct":true},{"t":"마 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","바 7200 ÷ 4 = 1800, 마 9000 ÷ 6 = 1500이에요.","비율이 큰 바 마을이 더 빽빽해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#18','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C5',3,'mc','auto','나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":18,"concept":"M6-1-u4-C5","difficulty":3,"kind":"mc","stem":"나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"동생","correct":true},{"t":"나","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","나 12 ÷ 25 × 100 = 48, 동생 10 ÷ 20 × 100 = 50이에요.","나 48 %, 동생 50 % — 동생이 더 잘 넣었어요."],"variant_rule":{"alt":[{"stem":"나는 공을 40번 차서 26번 넣었고, 동생은 20번 차서 14번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"동생","correct":true},{"t":"나","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","나 26 ÷ 40 × 100 = 65, 동생 14 ÷ 20 × 100 = 70이에요.","나 65 %, 동생 70 % — 동생이 더 잘 넣었어요."]},{"stem":"형은 공을 50번 차서 30번 넣었고, 나는 20번 차서 13번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"나","correct":true},{"t":"형","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","형 30 ÷ 50 × 100 = 60, 나 13 ÷ 20 × 100 = 65예요.","형 60 %, 나 65 % — 나가 더 잘 넣었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#19','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C6',3,'sa','auto','운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M6-1-u4-C6","difficulty":3,"kind":"sa","stem":"운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 40000 − 30000 = 10000이에요.","10000 ÷ 40000 × 100 = 25예요.","할인율은 25 %예요."],"mis":"M6-1-u4-X10","variant_rule":{"alt":[{"stem":"가방은 원래 가격이 25000원인데 20000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 25000 − 20000 = 5000이에요.","5000 ÷ 25000 × 100 = 20이에요.","할인율은 20 %예요."]},{"stem":"모자는 원래 가격이 20000원인데 17000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 20000 − 17000 = 3000이에요.","3000 ÷ 20000 × 100 = 15예요.","할인율은 15 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#20','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C1',3,'sa','auto','가로 5 cm, 세로 2 cm인 직사각형을 모양 그대로 키웠더니 세로가 6 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M6-1-u4-C1","difficulty":3,"kind":"sa","stem":"가로 5 cm, 세로 2 cm인 직사각형을 모양 그대로 키웠더니 세로가 6 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 6 ÷ 2 = 3배가 되었어요.","가로도 5 × 3 = 15 (cm)예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"가로 4 cm, 세로 3 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 9 ÷ 3 = 3배가 되었어요.","가로도 4 × 3 = 12 (cm)예요."]},{"stem":"가로 6 cm, 세로 4 cm인 직사각형을 모양 그대로 키웠더니 세로가 10 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 10 ÷ 4 = 2.5배가 되었어요.","가로도 6 × 2.5 = 15 (cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#21','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C2',3,'error','auto','바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X01','M6-1-u4-X16']::text[],true,'{"seq":21,"concept":"M6-1-u4-C2","difficulty":3,"kind":"error","stem":"바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「150：6이야.」","correct":true,"mis_target":"M6-1-u4-X01"},{"t":"이현 — 「기준량은 바닷물 양이야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「비는 6：150이야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량은 바닷물 양이에요.","비는 (비교하는 양)：(기준량) 차례라 6：150이에요.","준희는 기준량과 비교하는 양을 바꾸어 썼어요."],"variant_rule":{"alt":[{"stem":"비 9：50의 비율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「50 ÷ 9 = ⟨50/9⟩이야.」","correct":true,"mis_target":"M6-1-u4-X05"},{"t":"수아 — 「기준량은 50이야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「비율은 0.18이야.」","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","9 ÷ 50 = 0.18이에요.","서호는 기준량을 비교하는 양으로 나누었어요."]},{"stem":"비율 ⟨16/25⟩을 백분율로 나타내는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「분자가 16이니 16 %야.」","correct":true,"mis_target":"M6-1-u4-X09"},{"t":"나린 — 「⟨16/25⟩ = ⟨64/100⟩야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「16 ÷ 25 × 100 = 64야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량을 100으로 맞추어야 해요.","⟨16/25⟩ = ⟨64/100⟩ — 64 %예요.","가온은 분모를 100으로 고치지 않았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#22','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C7',3,'mc','auto','전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 48 %가 태양광이에요. 태양광 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X14','M6-1-u4-X16']::text[],true,'{"seq":22,"concept":"M6-1-u4-C7","difficulty":3,"kind":"mc","stem":"전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 48 %가 태양광이에요. 태양광 발전량은 몇 kWh인가요?","options":[{"t":"244800 kWh","correct":true},{"t":"1632000 kWh","mis":"M6-1-u4-X14"},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"2142000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 3400000 × 15 ÷ 100 = 510000이에요.","기준량이 510000으로 바뀌어요 — 510000 × 48 ÷ 100 = 244800이에요.","답은 244800 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 30 %가 풍력이에요. 풍력 발전량은 몇 kWh인가요?","options":[{"t":"153000 kWh","correct":true},{"t":"1020000 kWh","mis":"M6-1-u4-X14"},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"1530000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 3400000 × 15 ÷ 100 = 510000이에요.","기준량이 510000으로 바뀌어요 — 510000 × 30 ÷ 100 = 153000이에요.","답은 153000 kWh예요."]},{"stem":"전체 발전량 2000000 kWh의 20 %가 신재생 에너지이고, 신재생 에너지의 40 %가 수력이에요. 수력 발전량은 몇 kWh인가요?","options":[{"t":"160000 kWh","correct":true},{"t":"800000 kWh","mis":"M6-1-u4-X14"},{"t":"400000 kWh","mis":"M6-1-u4-X16"},{"t":"1200000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 2000000 × 20 ÷ 100 = 400000이에요.","기준량이 400000으로 바뀌어요 — 400000 × 40 ÷ 100 = 160000이에요.","답은 160000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#23','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C7',4,'mc','auto','가 지역은 전체 발전량 2000000 kWh 가운데 20 %, 나 지역은 전체 발전량 3000000 kWh 가운데 15 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":23,"concept":"M6-1-u4-C7","difficulty":4,"kind":"mc","stem":"가 지역은 전체 발전량 2000000 kWh 가운데 20 %, 나 지역은 전체 발전량 3000000 kWh 가운데 15 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"나 지역","correct":true},{"t":"가 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","가 2000000 × 20 ÷ 100 = 400000, 나 3000000 × 15 ÷ 100 = 450000이에요.","발전량이 더 많은 곳은 나 지역이에요."],"variant_rule":{"alt":[{"stem":"다 지역은 전체 발전량 5000000 kWh 가운데 12 %, 라 지역은 전체 발전량 4000000 kWh 가운데 14 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"다 지역","correct":true},{"t":"라 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","다 5000000 × 12 ÷ 100 = 600000, 라 4000000 × 14 ÷ 100 = 560000이에요.","발전량이 더 많은 곳은 다 지역이에요."]},{"stem":"마 지역은 전체 발전량 1500000 kWh 가운데 30 %, 바 지역은 전체 발전량 2500000 kWh 가운데 20 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"바 지역","correct":true},{"t":"마 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","마 1500000 × 30 ÷ 100 = 450000, 바 2500000 × 20 ÷ 100 = 500000이에요.","발전량이 더 많은 곳은 바 지역이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#24','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C2',4,'essay','teacher','바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 친구는 「바닷물 양에 대한 소금 양의 비」를 150：6이라고 썼어요. 바른 비와 비율을 구하고, 친구가 무엇을 잘못했는지 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u4-C2","difficulty":4,"kind":"essay","stem":"바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 친구는 「바닷물 양에 대한 소금 양의 비」를 150：6이라고 썼어요. 바른 비와 비율을 구하고, 친구가 무엇을 잘못했는지 설명해 보세요.","answer_guide":{"answer":"예: 「바닷물 양에 대한」이므로 기준량은 바닷물 양 150이고 비교하는 양은 소금 양 6이다. 바른 비는 6：150이고 비율은 6 ÷ 150 = 0.04이다. 친구는 기준량과 비교하는 양의 자리를 바꾸어 썼다.","scoring_points":["기준량 150·비교하는 양 6을 찾았는가","6：150과 비율 0.04를 구했는가","기준량과 비교하는 양을 바꾸었다고 설명했는가"]},"explanation":["기준량은 바닷물 양 150이에요.","비는 6：150, 비율은 0.04예요.","친구는 두 양의 자리를 바꾸었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#25','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C5',4,'essay','teacher','세 비율 ⟨14/25⟩, 0.62, 59 %의 크기를 비교하는 방법을 쓰고, 가장 작은 것을 찾아 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u4-C5","difficulty":4,"kind":"essay","stem":"세 비율 ⟨14/25⟩, 0.62, 59 %의 크기를 비교하는 방법을 쓰고, 가장 작은 것을 찾아 보세요.","answer_guide":{"answer":"예: 세 비율을 모두 백분율로 바꾸어 비교한다. ⟨14/25⟩ = ⟨56/100⟩이므로 56 %, 0.62 × 100 = 62이므로 62 %, 그리고 59 %이다. 56 % < 59 % < 62 %이므로 가장 작은 것은 ⟨14/25⟩이다.","scoring_points":["한 가지 표기(백분율 등)로 통일했는가","56 %·62 %·59 %로 바꾸었는가","⟨14/25⟩가 가장 작다고 답했는가"]},"explanation":["모두 백분율로 바꾸어요.","56 %, 62 %, 59 %예요.","가장 작은 것은 ⟨14/25⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#1','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C2',1,'mc','auto','팔찌 하나에 파란 구슬 2개와 노란 구슬 10개를 꿰어요. 파란 구슬 수와 노란 구슬 수의 비는 어느 것인가요?',ARRAY['M6-1-u4-X01','M6-1-u4-X03']::text[],true,'{"seq":1,"concept":"M6-1-u4-C2","difficulty":1,"kind":"mc","stem":"팔찌 하나에 파란 구슬 2개와 노란 구슬 10개를 꿰어요. 파란 구슬 수와 노란 구슬 수의 비는 어느 것인가요?","options":[{"t":"2：10","correct":true},{"t":"10：2","mis":"M6-1-u4-X01"},{"t":"2：8","mis":"M6-1-u4-X03"},{"t":"5：1","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 노란 구슬 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 2：10이에요."],"variant_rule":{"alt":[{"stem":"닭 2마리와 병아리 5마리가 있어요. 닭 수에 대한 병아리 수의 비는 어느 것인가요?","options":[{"t":"5：2","correct":true},{"t":"2：5","mis":"M6-1-u4-X01"},{"t":"5：7","mis":"M6-1-u4-X07"},{"t":"3：5","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 닭 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 5：2예요."]},{"stem":"치즈 4장과 달걀부침 3개로 샌드위치를 만들었어요. 치즈 수에 대한 달걀부침 수의 비는 어느 것인가요?","options":[{"t":"3：4","correct":true},{"t":"4：3","mis":"M6-1-u4-X01"},{"t":"3：7","mis":"M6-1-u4-X07"},{"t":"1：4","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 치즈 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 3：4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#2','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C2',1,'sa','auto','비 9：20에서 후항은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u4-C2","difficulty":1,"kind":"sa","stem":"비 9：20에서 후항은 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","9：20에서 전항은 9, 후항은 20이에요.","그래서 후항은 20이에요."],"mis":"M6-1-u4-X01","variant_rule":{"alt":[{"stem":"비 13：23에서 전항은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","13：23에서 전항은 13, 후항은 23이에요.","그래서 전항은 13이에요."]},{"stem":"비 5：8에서 비교하는 양은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","5：8에서 전항은 5, 후항은 8이에요.","그래서 비교하는 양은 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#3','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C3',1,'mc','auto','비 1：4의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X15']::text[],true,'{"seq":3,"concept":"M6-1-u4-C3","difficulty":1,"kind":"mc","stem":"비 1：4의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.25","correct":true},{"t":"4","mis":"M6-1-u4-X05"},{"t":"2.5","mis":"M6-1-u4-X15"},{"t":"0.025","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","1：4의 비율은 1 ÷ 4 = 0.25예요.","분수로는 ⟨1/4⟩, 소수로는 0.25예요."],"variant_rule":{"alt":[{"stem":"비 6：5의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"1.2","correct":true},{"t":"12","mis":"M6-1-u4-X15"},{"t":"0.12","mis":"M6-1-u4-X15"},{"t":"2.2","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","6：5의 비율은 6 ÷ 5 = 1.2예요.","분수로는 ⟨6/5⟩, 소수로는 1.2예요."]},{"stem":"비 7：20의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.35","correct":true},{"t":"3.5","mis":"M6-1-u4-X15"},{"t":"0.035","mis":"M6-1-u4-X15"},{"t":"0.65","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","7：20의 비율은 7 ÷ 20 = 0.35예요.","분수로는 ⟨7/20⟩, 소수로는 0.35예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#4','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C4',1,'mc','auto','노란 팀은 20경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":4,"concept":"M6-1-u4-C4","difficulty":1,"kind":"mc","stem":"노란 팀은 20경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"0.7","mis":"M6-1-u4-X16"},{"t":"3","mis":"M6-1-u4-X15"},{"t":"0.03","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 20, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/20⟩ = 0.3이에요.","노란 팀의 비율은 0.3이에요."],"variant_rule":{"alt":[{"stem":"초록 팀은 10경기를 치러서 5경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.5","correct":true},{"t":"2","mis":"M6-1-u4-X05"},{"t":"1","mis":"M6-1-u4-X07"},{"t":"5","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 10, 비교하는 양은 이긴 경기 수 5예요.","⟨5/10⟩ = 0.5예요.","초록 팀의 비율은 0.5예요."]},{"stem":"빨강 팀은 8경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.75","correct":true},{"t":"0.25","mis":"M6-1-u4-X16"},{"t":"3","mis":"M6-1-u4-X07"},{"t":"7.5","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 8, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/8⟩ = 0.75예요.","빨강 팀의 비율은 0.75예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#5','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C5',1,'mc','auto','비율 0.83을 백분율로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":5,"concept":"M6-1-u4-C5","difficulty":1,"kind":"mc","stem":"비율 0.83을 백분율로 나타내면 얼마인가요?","options":[{"t":"83 %","correct":true},{"t":"8.3 %","mis":"M6-1-u4-X08"},{"t":"0.83 %","mis":"M6-1-u4-X08"},{"t":"830 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.83 × 100 = 83이에요.","그래서 83 %예요."],"variant_rule":{"alt":[{"stem":"비율 0.6을 백분율로 나타내면 얼마인가요?","options":[{"t":"60 %","correct":true},{"t":"6 %","mis":"M6-1-u4-X08"},{"t":"0.6 %","mis":"M6-1-u4-X08"},{"t":"600 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.6 × 100 = 60이에요.","그래서 60 %예요."]},{"stem":"비율 0.07을 백분율로 나타내면 얼마인가요?","options":[{"t":"7 %","correct":true},{"t":"0.7 %","mis":"M6-1-u4-X08"},{"t":"0.07 %","mis":"M6-1-u4-X08"},{"t":"70 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.07 × 100 = 7이에요.","그래서 7 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#6','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C6',1,'sa','auto','학급 회장 선거에서 전체 30표 가운데 수빈이가 12표를 받았어요. 수빈이의 득표율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C6","difficulty":1,"kind":"sa","stem":"학급 회장 선거에서 전체 30표 가운데 수빈이가 12표를 받았어요. 수빈이의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","12 ÷ 30 × 100 = 40이에요.","수빈이의 득표율은 40 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"학급 회장 선거에서 전체 25표 가운데 하늘이 9표를 받았어요. 하늘의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","9 ÷ 25 × 100 = 36이에요.","하늘의 득표율은 36 %예요."]},{"stem":"학급 회장 선거에서 전체 40표 가운데 도윤이 22표를 받았어요. 도윤의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","22 ÷ 40 × 100 = 55예요.","도윤의 득표율은 55 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#7','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C7',1,'mc','auto','전체 발전량 2500000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":7,"concept":"M6-1-u4-C7","difficulty":1,"kind":"mc","stem":"전체 발전량 2500000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"25000 kWh","correct":true},{"t":"250000 kWh","mis":"M6-1-u4-X15"},{"t":"2500 kWh","mis":"M6-1-u4-X15"},{"t":"250000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","2500000 ÷ 100 = 25000이에요.","한 칸은 25000 kWh예요."],"variant_rule":{"alt":[{"stem":"신재생 발전량 510000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"5100 kWh","correct":true},{"t":"51000 kWh","mis":"M6-1-u4-X15"},{"t":"510 kWh","mis":"M6-1-u4-X15"},{"t":"51000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","510000 ÷ 100 = 5100이에요.","한 칸은 5100 kWh예요."]},{"stem":"전체 발전량 4200000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"42000 kWh","correct":true},{"t":"420000 kWh","mis":"M6-1-u4-X15"},{"t":"4200 kWh","mis":"M6-1-u4-X15"},{"t":"420000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","4200000 ÷ 100 = 42000이에요.","한 칸은 42000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#8','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C1',1,'sa','auto','팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 나눗셈으로 비교하면 노란 구슬은 파란 구슬의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u4-C1","difficulty":1,"kind":"sa","stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 나눗셈으로 비교하면 노란 구슬은 파란 구슬의 몇 배인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","10 ÷ 2 = 5예요.","노란 구슬은 파란 구슬의 5배예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"꽃다발 한 개에는 안개꽃 12송이와 장미 3송이가 들어가요. 나눗셈으로 비교하면 안개꽃은 장미의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","12 ÷ 3 = 4예요.","안개꽃은 장미의 4배예요."]},{"stem":"하늘색 물감 한 접시에는 흰색 물감 8방울과 파란색 물감 2방울이 들어가요. 나눗셈으로 비교하면 흰색 물감은 파란색 물감의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","8 ÷ 2 = 4예요.","흰색 물감은 파란색 물감의 4배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#9','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C3',2,'mc','auto','가로 40 cm, 세로 24 cm인 태극기 액자가 있어요. 가로에 대한 세로의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":9,"concept":"M6-1-u4-C3","difficulty":2,"kind":"mc","stem":"가로 40 cm, 세로 24 cm인 태극기 액자가 있어요. 가로에 대한 세로의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.6","correct":true},{"t":"0.4","mis":"M6-1-u4-X16"},{"t":"6","mis":"M6-1-u4-X15"},{"t":"0.06","mis":"M6-1-u4-X15"}],"explanation":["기준량은 40, 비교하는 양은 24예요.","24 ÷ 40 = 0.6이에요.","그래서 비율은 0.6이에요."],"variant_rule":{"alt":[{"stem":"마을 자전거 도로 15 km 가운데 12 km가 완성되었어요. 전체 길이에 대한 완성된 길이의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"1.25","mis":"M6-1-u4-X05"},{"t":"0.2","mis":"M6-1-u4-X16"},{"t":"8","mis":"M6-1-u4-X15"}],"explanation":["기준량은 15, 비교하는 양은 12예요.","12 ÷ 15 = 0.8이에요.","그래서 비율은 0.8이에요."]},{"stem":"세계 환경의 날 기념 행사에 어린이 50명이 지원해서 9명이 당첨되었어요. 지원한 어린이 수에 대한 당첨된 어린이 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.18","correct":true},{"t":"0.82","mis":"M6-1-u4-X16"},{"t":"1.8","mis":"M6-1-u4-X15"},{"t":"0.018","mis":"M6-1-u4-X15"}],"explanation":["기준량은 50, 비교하는 양은 9예요.","9 ÷ 50 = 0.18이에요.","그래서 비율은 0.18이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#10','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C4',2,'sa','auto','자전거로 3시간 동안 12 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u4-C4","difficulty":2,"kind":"sa","stem":"자전거로 3시간 동안 12 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["기준량은 이동한 시간 3, 비교하는 양은 이동한 거리 12예요.","12 ÷ 3 = 4예요.","1시간에 4 km만큼 이동한 셈이에요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"기차가 2시간 동안 180 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["기준량은 이동한 시간 2, 비교하는 양은 이동한 거리 180이에요.","180 ÷ 2 = 90이에요.","1시간에 90 km만큼 이동한 셈이에요."]},{"stem":"유람선이 4시간 동안 36 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["기준량은 이동한 시간 4, 비교하는 양은 이동한 거리 36이에요.","36 ÷ 4 = 9예요.","1시간에 9 km만큼 이동한 셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#11','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C5',2,'sa','auto','전체 25칸인 모눈에서 16칸을 색칠했어요. 전체 모눈 수에 대한 색칠한 모눈 수의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"전체 25칸인 모눈에서 16칸을 색칠했어요. 전체 모눈 수에 대한 색칠한 모눈 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["기준량은 25, 비교하는 양은 16이에요.","16 ÷ 25 × 100 = 64예요.","그래서 64 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"수학 문제 40개 가운데 34개를 맞혔어요. 전체 문제 수에 대한 맞힌 문제 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["기준량은 40, 비교하는 양은 34예요.","34 ÷ 40 × 100 = 85예요.","그래서 85 %예요."]},{"stem":"씨앗 50개를 심었더니 43개가 싹을 틔웠어요. 심은 씨앗 수에 대한 싹 튼 씨앗 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["86"],"explanation":["기준량은 50, 비교하는 양은 43이에요.","43 ÷ 50 × 100 = 86이에요.","그래서 86 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#12','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C5',2,'sa','auto','비율 ⟨3/4⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"비율 ⟨3/4⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 25를 곱해요.","⟨3/4⟩ = ⟨75/100⟩예요.","그래서 ⟨3/4⟩은 75 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"비율 ⟨9/20⟩를 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 5를 곱해요.","⟨9/20⟩ = ⟨45/100⟩예요.","그래서 ⟨9/20⟩는 45 %예요."]},{"stem":"비율 ⟨13/20⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 5를 곱해요.","⟨13/20⟩ = ⟨65/100⟩예요.","그래서 ⟨13/20⟩은 65 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#13','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C6',2,'sa','auto','공책은 원래 가격 2000원에서 300원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"공책은 원래 가격 2000원에서 300원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","300 ÷ 2000 × 100 = 15예요.","할인율은 15 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"필통은 원래 가격 8000원에서 2000원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","2000 ÷ 8000 × 100 = 25예요.","할인율은 25 %예요."]},{"stem":"나 치약은 원래 가격 5000원에서 1400원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","1400 ÷ 5000 × 100 = 28이에요.","할인율은 28 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#14','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C6',2,'sa','auto','예은은 설탕 36 g을 녹여 설탕물 200 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"예은은 설탕 36 g을 녹여 설탕물 200 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["기준량은 설탕물 200 g, 비교하는 양은 설탕 36 g이에요.","36 ÷ 200 × 100 = 18이에요.","설탕물의 진하기는 18 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"민서는 설탕 45 g을 녹여 설탕물 300 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["기준량은 설탕물 300 g, 비교하는 양은 설탕 45 g이에요.","45 ÷ 300 × 100 = 15예요.","설탕물의 진하기는 15 %예요."]},{"stem":"하준은 설탕 24 g을 녹여 설탕물 150 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["기준량은 설탕물 150 g, 비교하는 양은 설탕 24 g이에요.","24 ÷ 150 × 100 = 16이에요.","설탕물의 진하기는 16 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#15','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C3',2,'ox','auto','비율은 언제나 1보다 작아요.',ARRAY['M6-1-u4-X06']::text[],true,'{"seq":15,"concept":"M6-1-u4-C3","difficulty":2,"kind":"ox","stem":"비율은 언제나 1보다 작아요.","answer":"X","reason_options":[{"t":"12：5의 비율 2.4처럼 비교하는 양이 더 크면 1보다 크기 때문에","correct":true},{"t":"비율은 전체의 일부만 나타내기 때문에","mis":"M6-1-u4-X06"}],"mis":"M6-1-u4-X06","explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."],"variant_rule":{"alt":[{"stem":"비율 0.07을 백분율로 나타내면 70 %예요.","answer":"X","reason_options":[{"t":"0.07 × 100 = 7이라 7 %이기 때문에","correct":true},{"t":"0.07의 7 뒤에 0을 붙이면 되기 때문에","mis":"M6-1-u4-X08"}],"explanation":["기준량을 100으로 할 때의 비율을 백분율이라 하고 %를 써요.","비율에 100을 곱해서 나온 값에 %를 붙여요.","기준량이 100인 분수로 바꾸어도 돼요."]},{"stem":"할인율은 (할인된 가격) ÷ (원래 가격)으로 구해요.","answer":"X","reason_options":[{"t":"할인율은 원래 가격에 대한 할인 금액의 비율이기 때문에","correct":true},{"t":"할인된 가격이 비교하는 양이기 때문에","mis":"M6-1-u4-X10"}],"explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#16','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C7',2,'mc','auto','푸른 지역의 전체 발전량은 2500000 kWh이고 그중 20 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":16,"concept":"M6-1-u4-C7","difficulty":2,"kind":"mc","stem":"푸른 지역의 전체 발전량은 2500000 kWh이고 그중 20 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"500000 kWh","correct":true},{"t":"50000 kWh","mis":"M6-1-u4-X15"},{"t":"125000 kWh","mis":"M6-1-u4-X13"},{"t":"5000000 kWh","mis":"M6-1-u4-X15"}],"explanation":["전체 2500000을 100칸으로 보면 한 칸은 2500000 ÷ 100 = 25000이에요.","20 %는 20칸이라 25000 × 20 = 500000이에요.","답은 500000 kWh예요."],"variant_rule":{"alt":[{"stem":"맑은 지역의 전체 발전량은 4200000 kWh이고 그중 10 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"420000 kWh","correct":true},{"t":"42000 kWh","mis":"M6-1-u4-X15"},{"t":"4200000 kWh","mis":"M6-1-u4-X15"},{"t":"3780000 kWh","mis":"M6-1-u4-X16"}],"explanation":["전체 4200000을 100칸으로 보면 한 칸은 4200000 ÷ 100 = 42000이에요.","10 %는 10칸이라 42000 × 10 = 420000이에요.","답은 420000 kWh예요."]},{"stem":"신재생 에너지 510000 kWh 가운데 30 %가 풍력 에너지예요. 풍력 발전량은 몇 kWh인가요?","options":[{"t":"153000 kWh","correct":true},{"t":"15300 kWh","mis":"M6-1-u4-X15"},{"t":"17000 kWh","mis":"M6-1-u4-X13"},{"t":"1530000 kWh","mis":"M6-1-u4-X15"}],"explanation":["전체 510000을 100칸으로 보면 한 칸은 510000 ÷ 100 = 5100이에요.","30 %는 30칸이라 5100 × 30 = 153000이에요.","답은 153000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#17','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C4',3,'mc','auto','다 마을은 넓이 4 km²에 10000명, 라 마을은 넓이 5 km²에 11000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":17,"concept":"M6-1-u4-C4","difficulty":3,"kind":"mc","stem":"다 마을은 넓이 4 km²에 10000명, 라 마을은 넓이 5 km²에 11000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"다 마을","correct":true},{"t":"라 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","다 10000 ÷ 4 = 2500, 라 11000 ÷ 5 = 2200이에요.","비율이 큰 다 마을이 더 빽빽해요."],"variant_rule":{"alt":[{"stem":"바 마을은 넓이 4 km²에 7200명, 마 마을은 넓이 6 km²에 9000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"바 마을","correct":true},{"t":"마 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","바 7200 ÷ 4 = 1800, 마 9000 ÷ 6 = 1500이에요.","비율이 큰 바 마을이 더 빽빽해요."]},{"stem":"사 마을은 넓이 8 km²에 12000명, 아 마을은 넓이 5 km²에 8000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"아 마을","correct":true},{"t":"사 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","사 12000 ÷ 8 = 1500, 아 8000 ÷ 5 = 1600이에요.","비율이 큰 아 마을이 더 빽빽해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#18','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C5',3,'mc','auto','나는 공을 40번 차서 26번 넣었고, 동생은 20번 차서 14번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":18,"concept":"M6-1-u4-C5","difficulty":3,"kind":"mc","stem":"나는 공을 40번 차서 26번 넣었고, 동생은 20번 차서 14번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"동생","correct":true},{"t":"나","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","나 26 ÷ 40 × 100 = 65, 동생 14 ÷ 20 × 100 = 70이에요.","나 65 %, 동생 70 % — 동생이 더 잘 넣었어요."],"variant_rule":{"alt":[{"stem":"형은 공을 50번 차서 30번 넣었고, 나는 20번 차서 13번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"나","correct":true},{"t":"형","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","형 30 ÷ 50 × 100 = 60, 나 13 ÷ 20 × 100 = 65예요.","형 60 %, 나 65 % — 나가 더 잘 넣었어요."]},{"stem":"지민은 공을 40번 차서 30번 넣었고, 태오는 25번 차서 20번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"태오","correct":true},{"t":"지민","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","지민 30 ÷ 40 × 100 = 75, 태오 20 ÷ 25 × 100 = 80이에요.","지민 75 %, 태오 80 % — 태오가 더 잘 넣었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#19','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C6',3,'sa','auto','가방은 원래 가격이 25000원인데 20000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M6-1-u4-C6","difficulty":3,"kind":"sa","stem":"가방은 원래 가격이 25000원인데 20000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 25000 − 20000 = 5000이에요.","5000 ÷ 25000 × 100 = 20이에요.","할인율은 20 %예요."],"mis":"M6-1-u4-X10","variant_rule":{"alt":[{"stem":"모자는 원래 가격이 20000원인데 17000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 20000 − 17000 = 3000이에요.","3000 ÷ 20000 × 100 = 15예요.","할인율은 15 %예요."]},{"stem":"우산은 원래 가격이 15000원인데 12000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 15000 − 12000 = 3000이에요.","3000 ÷ 15000 × 100 = 20이에요.","할인율은 20 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#20','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C1',3,'sa','auto','가로 4 cm, 세로 3 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M6-1-u4-C1","difficulty":3,"kind":"sa","stem":"가로 4 cm, 세로 3 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 9 ÷ 3 = 3배가 되었어요.","가로도 4 × 3 = 12 (cm)예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"가로 6 cm, 세로 4 cm인 직사각형을 모양 그대로 키웠더니 세로가 10 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 10 ÷ 4 = 2.5배가 되었어요.","가로도 6 × 2.5 = 15 (cm)예요."]},{"stem":"가로 8 cm, 세로 6 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 9 ÷ 6 = 1.5배가 되었어요.","가로도 8 × 1.5 = 12 (cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#21','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C3',3,'error','auto','비 9：50의 비율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X16']::text[],true,'{"seq":21,"concept":"M6-1-u4-C3","difficulty":3,"kind":"error","stem":"비 9：50의 비율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「50 ÷ 9 = ⟨50/9⟩이야.」","correct":true,"mis_target":"M6-1-u4-X05"},{"t":"수아 — 「기준량은 50이야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「비율은 0.18이야.」","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","9 ÷ 50 = 0.18이에요.","서호는 기준량을 비교하는 양으로 나누었어요."],"variant_rule":{"alt":[{"stem":"비율 ⟨16/25⟩을 백분율로 나타내는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「분자가 16이니 16 %야.」","correct":true,"mis_target":"M6-1-u4-X09"},{"t":"나린 — 「⟨16/25⟩ = ⟨64/100⟩야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「16 ÷ 25 × 100 = 64야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량을 100으로 맞추어야 해요.","⟨16/25⟩ = ⟨64/100⟩ — 64 %예요.","가온은 분모를 100으로 고치지 않았어요."]},{"stem":"운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「30000 ÷ 40000 × 100 = 75니 75 %야.」","correct":true,"mis_target":"M6-1-u4-X10"},{"t":"라온 — 「할인 금액은 10000원이야.」","mis":"M6-1-u4-X16"},{"t":"예준 — 「할인율은 25 %야.」","mis":"M6-1-u4-X16"}],"explanation":["할인 금액은 40000 − 30000 = 10000이에요.","10000 ÷ 40000 × 100 = 25예요.","여울은 할인된 가격으로 계산했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#22','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C7',3,'mc','auto','전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 30 %가 풍력이에요. 풍력 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X14','M6-1-u4-X16']::text[],true,'{"seq":22,"concept":"M6-1-u4-C7","difficulty":3,"kind":"mc","stem":"전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 30 %가 풍력이에요. 풍력 발전량은 몇 kWh인가요?","options":[{"t":"153000 kWh","correct":true},{"t":"1020000 kWh","mis":"M6-1-u4-X14"},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"1530000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 3400000 × 15 ÷ 100 = 510000이에요.","기준량이 510000으로 바뀌어요 — 510000 × 30 ÷ 100 = 153000이에요.","답은 153000 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 2000000 kWh의 20 %가 신재생 에너지이고, 신재생 에너지의 40 %가 수력이에요. 수력 발전량은 몇 kWh인가요?","options":[{"t":"160000 kWh","correct":true},{"t":"800000 kWh","mis":"M6-1-u4-X14"},{"t":"400000 kWh","mis":"M6-1-u4-X16"},{"t":"1200000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 2000000 × 20 ÷ 100 = 400000이에요.","기준량이 400000으로 바뀌어요 — 400000 × 40 ÷ 100 = 160000이에요.","답은 160000 kWh예요."]},{"stem":"전체 발전량 5000000 kWh의 12 %가 신재생 에너지이고, 신재생 에너지의 25 %가 지열이에요. 지열 발전량은 몇 kWh인가요?","options":[{"t":"150000 kWh","correct":true},{"t":"1250000 kWh","mis":"M6-1-u4-X14"},{"t":"600000 kWh","mis":"M6-1-u4-X16"},{"t":"1850000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 5000000 × 12 ÷ 100 = 600000이에요.","기준량이 600000으로 바뀌어요 — 600000 × 25 ÷ 100 = 150000이에요.","답은 150000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#23','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C7',4,'mc','auto','다 지역은 전체 발전량 5000000 kWh 가운데 12 %, 라 지역은 전체 발전량 4000000 kWh 가운데 14 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":23,"concept":"M6-1-u4-C7","difficulty":4,"kind":"mc","stem":"다 지역은 전체 발전량 5000000 kWh 가운데 12 %, 라 지역은 전체 발전량 4000000 kWh 가운데 14 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"다 지역","correct":true},{"t":"라 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","다 5000000 × 12 ÷ 100 = 600000, 라 4000000 × 14 ÷ 100 = 560000이에요.","발전량이 더 많은 곳은 다 지역이에요."],"variant_rule":{"alt":[{"stem":"마 지역은 전체 발전량 1500000 kWh 가운데 30 %, 바 지역은 전체 발전량 2500000 kWh 가운데 20 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"바 지역","correct":true},{"t":"마 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","마 1500000 × 30 ÷ 100 = 450000, 바 2500000 × 20 ÷ 100 = 500000이에요.","발전량이 더 많은 곳은 바 지역이에요."]},{"stem":"사 지역은 전체 발전량 6000000 kWh 가운데 10 %, 아 지역은 전체 발전량 4000000 kWh 가운데 14 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"사 지역","correct":true},{"t":"아 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","사 6000000 × 10 ÷ 100 = 600000, 아 4000000 × 14 ÷ 100 = 560000이에요.","발전량이 더 많은 곳은 사 지역이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#24','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C3',4,'essay','teacher','가로에 대한 세로의 비가 15：25, 30：50, 6：10인 세 직사각형이 있어요. 세 비율을 소수로 구해 비교하고, 기준량이 다른데도 비율이 같은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u4-C3","difficulty":4,"kind":"essay","stem":"가로에 대한 세로의 비가 15：25, 30：50, 6：10인 세 직사각형이 있어요. 세 비율을 소수로 구해 비교하고, 기준량이 다른데도 비율이 같은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 15 ÷ 25 = 0.6, 30 ÷ 50 = 0.6, 6 ÷ 10 = 0.6이므로 세 비율은 모두 0.6으로 같다. 세 직사각형은 크기는 다르지만 가로에 대한 세로의 관계(세로가 가로의 0.6배)가 같아서, 기준량이 달라도 비율이 같다.","scoring_points":["세 비율을 0.6으로 구했는가","세 비율이 같다고 비교했는가","관계가 같으면 기준량이 달라도 비율이 같다고 설명했는가"]},"explanation":["세 비율은 모두 0.6이에요.","크기는 달라도 모양(관계)이 같아요.","그래서 기준량이 달라도 비율이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#25','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C7',4,'essay','teacher','신재생 에너지 510000 kWh 가운데 48 %가 태양광 에너지예요. 태양광 발전량을 구하고, 친구가 전체 발전량 3400000 kWh의 48 %를 구한 것이 왜 틀렸는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u4-C7","difficulty":4,"kind":"essay","stem":"신재생 에너지 510000 kWh 가운데 48 %가 태양광 에너지예요. 태양광 발전량을 구하고, 친구가 전체 발전량 3400000 kWh의 48 %를 구한 것이 왜 틀렸는지 설명해 보세요.","answer_guide":{"answer":"예: 기준량은 신재생 에너지 발전량 510000이다. 한 칸은 510000 ÷ 100 = 5100이고 48칸은 5100 × 48 = 244800이므로 태양광 발전량은 244800 kWh이다. 친구는 「신재생 에너지의 48 %」인데 기준량을 전체 발전량으로 잘못 잡았다.","scoring_points":["기준량을 510000으로 잡았는가","244800 kWh를 구했는가","기준량이 바뀐 것을 놓쳤다고 설명했는가"]},"explanation":["기준량은 510000이에요.","5100 × 48 = 244800 — 244800 kWh예요.","친구는 기준량을 바꾸지 않았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#1','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C2',1,'mc','auto','닭 2마리와 병아리 5마리가 있어요. 닭 수에 대한 병아리 수의 비는 어느 것인가요?',ARRAY['M6-1-u4-X01','M6-1-u4-X07','M6-1-u4-X03']::text[],true,'{"seq":1,"concept":"M6-1-u4-C2","difficulty":1,"kind":"mc","stem":"닭 2마리와 병아리 5마리가 있어요. 닭 수에 대한 병아리 수의 비는 어느 것인가요?","options":[{"t":"5：2","correct":true},{"t":"2：5","mis":"M6-1-u4-X01"},{"t":"5：7","mis":"M6-1-u4-X07"},{"t":"3：5","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 닭 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 5：2예요."],"variant_rule":{"alt":[{"stem":"치즈 4장과 달걀부침 3개로 샌드위치를 만들었어요. 치즈 수에 대한 달걀부침 수의 비는 어느 것인가요?","options":[{"t":"3：4","correct":true},{"t":"4：3","mis":"M6-1-u4-X01"},{"t":"3：7","mis":"M6-1-u4-X07"},{"t":"1：4","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 치즈 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 3：4예요."]},{"stem":"바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 어느 것인가요?","options":[{"t":"6：150","correct":true},{"t":"150：6","mis":"M6-1-u4-X01"},{"t":"6：144","mis":"M6-1-u4-X03"},{"t":"25：1","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 바닷물 양이에요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 6：150이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#2','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C2',1,'sa','auto','비 13：23에서 전항은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u4-C2","difficulty":1,"kind":"sa","stem":"비 13：23에서 전항은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","13：23에서 전항은 13, 후항은 23이에요.","그래서 전항은 13이에요."],"mis":"M6-1-u4-X01","variant_rule":{"alt":[{"stem":"비 5：8에서 비교하는 양은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","5：8에서 전항은 5, 후항은 8이에요.","그래서 비교하는 양은 5예요."]},{"stem":"비 2：10에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","2：10에서 전항은 2, 후항은 10이에요.","그래서 기준량은 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#3','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C3',1,'mc','auto','비 6：5의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X15']::text[],true,'{"seq":3,"concept":"M6-1-u4-C3","difficulty":1,"kind":"mc","stem":"비 6：5의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"1.2","correct":true},{"t":"12","mis":"M6-1-u4-X15"},{"t":"0.12","mis":"M6-1-u4-X15"},{"t":"2.2","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","6：5의 비율은 6 ÷ 5 = 1.2예요.","분수로는 ⟨6/5⟩, 소수로는 1.2예요."],"variant_rule":{"alt":[{"stem":"비 7：20의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.35","correct":true},{"t":"3.5","mis":"M6-1-u4-X15"},{"t":"0.035","mis":"M6-1-u4-X15"},{"t":"0.65","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","7：20의 비율은 7 ÷ 20 = 0.35예요.","분수로는 ⟨7/20⟩, 소수로는 0.35예요."]},{"stem":"비 3：10의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"3","mis":"M6-1-u4-X15"},{"t":"0.03","mis":"M6-1-u4-X15"},{"t":"0.7","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","3：10의 비율은 3 ÷ 10 = 0.3이에요.","분수로는 ⟨3/10⟩, 소수로는 0.3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#4','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C4',1,'mc','auto','초록 팀은 10경기를 치러서 5경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X07','M6-1-u4-X15']::text[],true,'{"seq":4,"concept":"M6-1-u4-C4","difficulty":1,"kind":"mc","stem":"초록 팀은 10경기를 치러서 5경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.5","correct":true},{"t":"2","mis":"M6-1-u4-X05"},{"t":"1","mis":"M6-1-u4-X07"},{"t":"5","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 10, 비교하는 양은 이긴 경기 수 5예요.","⟨5/10⟩ = 0.5예요.","초록 팀의 비율은 0.5예요."],"variant_rule":{"alt":[{"stem":"빨강 팀은 8경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.75","correct":true},{"t":"0.25","mis":"M6-1-u4-X16"},{"t":"3","mis":"M6-1-u4-X07"},{"t":"7.5","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 8, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/8⟩ = 0.75예요.","빨강 팀의 비율은 0.75예요."]},{"stem":"푸른 팀은 15경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"2.5","mis":"M6-1-u4-X05"},{"t":"0.6","mis":"M6-1-u4-X16"},{"t":"4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 15, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/15⟩ = 0.4예요.","푸른 팀의 비율은 0.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#5','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C5',1,'mc','auto','비율 0.6을 백분율로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":5,"concept":"M6-1-u4-C5","difficulty":1,"kind":"mc","stem":"비율 0.6을 백분율로 나타내면 얼마인가요?","options":[{"t":"60 %","correct":true},{"t":"6 %","mis":"M6-1-u4-X08"},{"t":"0.6 %","mis":"M6-1-u4-X08"},{"t":"600 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.6 × 100 = 60이에요.","그래서 60 %예요."],"variant_rule":{"alt":[{"stem":"비율 0.07을 백분율로 나타내면 얼마인가요?","options":[{"t":"7 %","correct":true},{"t":"0.7 %","mis":"M6-1-u4-X08"},{"t":"0.07 %","mis":"M6-1-u4-X08"},{"t":"70 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.07 × 100 = 7이에요.","그래서 7 %예요."]},{"stem":"비율 0.35를 백분율로 나타내면 얼마인가요?","options":[{"t":"35 %","correct":true},{"t":"3.5 %","mis":"M6-1-u4-X08"},{"t":"0.35 %","mis":"M6-1-u4-X08"},{"t":"350 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.35 × 100 = 35예요.","그래서 35 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#6','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C6',1,'sa','auto','학급 회장 선거에서 전체 25표 가운데 하늘이 9표를 받았어요. 하늘의 득표율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C6","difficulty":1,"kind":"sa","stem":"학급 회장 선거에서 전체 25표 가운데 하늘이 9표를 받았어요. 하늘의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","9 ÷ 25 × 100 = 36이에요.","하늘의 득표율은 36 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"학급 회장 선거에서 전체 40표 가운데 도윤이 22표를 받았어요. 도윤의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","22 ÷ 40 × 100 = 55예요.","도윤의 득표율은 55 %예요."]},{"stem":"학급 회장 선거에서 전체 30표 가운데 건우가 18표를 받았어요. 건우의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","18 ÷ 30 × 100 = 60이에요.","건우의 득표율은 60 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#7','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C7',1,'mc','auto','신재생 발전량 510000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":7,"concept":"M6-1-u4-C7","difficulty":1,"kind":"mc","stem":"신재생 발전량 510000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"5100 kWh","correct":true},{"t":"51000 kWh","mis":"M6-1-u4-X15"},{"t":"510 kWh","mis":"M6-1-u4-X15"},{"t":"51000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","510000 ÷ 100 = 5100이에요.","한 칸은 5100 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 4200000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"42000 kWh","correct":true},{"t":"420000 kWh","mis":"M6-1-u4-X15"},{"t":"4200 kWh","mis":"M6-1-u4-X15"},{"t":"420000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","4200000 ÷ 100 = 42000이에요.","한 칸은 42000 kWh예요."]},{"stem":"전체 발전량 3400000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"34000 kWh","correct":true},{"t":"340000 kWh","mis":"M6-1-u4-X15"},{"t":"3400 kWh","mis":"M6-1-u4-X15"},{"t":"340000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","3400000 ÷ 100 = 34000이에요.","한 칸은 34000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#8','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C1',1,'sa','auto','꽃다발 한 개에는 안개꽃 12송이와 장미 3송이가 들어가요. 나눗셈으로 비교하면 안개꽃은 장미의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u4-C1","difficulty":1,"kind":"sa","stem":"꽃다발 한 개에는 안개꽃 12송이와 장미 3송이가 들어가요. 나눗셈으로 비교하면 안개꽃은 장미의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","12 ÷ 3 = 4예요.","안개꽃은 장미의 4배예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"하늘색 물감 한 접시에는 흰색 물감 8방울과 파란색 물감 2방울이 들어가요. 나눗셈으로 비교하면 흰색 물감은 파란색 물감의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","8 ÷ 2 = 4예요.","흰색 물감은 파란색 물감의 4배예요."]},{"stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 나눗셈으로 비교하면 물은 매실 원액의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","4 ÷ 1 = 4예요.","물은 매실 원액의 4배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#9','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C3',2,'mc','auto','마을 자전거 도로 15 km 가운데 12 km가 완성되었어요. 전체 길이에 대한 완성된 길이의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":9,"concept":"M6-1-u4-C3","difficulty":2,"kind":"mc","stem":"마을 자전거 도로 15 km 가운데 12 km가 완성되었어요. 전체 길이에 대한 완성된 길이의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"1.25","mis":"M6-1-u4-X05"},{"t":"0.2","mis":"M6-1-u4-X16"},{"t":"8","mis":"M6-1-u4-X15"}],"explanation":["기준량은 15, 비교하는 양은 12예요.","12 ÷ 15 = 0.8이에요.","그래서 비율은 0.8이에요."],"variant_rule":{"alt":[{"stem":"세계 환경의 날 기념 행사에 어린이 50명이 지원해서 9명이 당첨되었어요. 지원한 어린이 수에 대한 당첨된 어린이 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.18","correct":true},{"t":"0.82","mis":"M6-1-u4-X16"},{"t":"1.8","mis":"M6-1-u4-X15"},{"t":"0.018","mis":"M6-1-u4-X15"}],"explanation":["기준량은 50, 비교하는 양은 9예요.","9 ÷ 50 = 0.18이에요.","그래서 비율은 0.18이에요."]},{"stem":"집에서 할머니 댁까지는 20 km, 집에서 주유소까지는 8 km예요. 집과 할머니 댁 사이 거리에 대한 집과 주유소 사이 거리의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"2.5","mis":"M6-1-u4-X05"},{"t":"0.6","mis":"M6-1-u4-X16"},{"t":"4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 20, 비교하는 양은 8이에요.","8 ÷ 20 = 0.4예요.","그래서 비율은 0.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#10','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C4',2,'sa','auto','기차가 2시간 동안 180 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u4-C4","difficulty":2,"kind":"sa","stem":"기차가 2시간 동안 180 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["기준량은 이동한 시간 2, 비교하는 양은 이동한 거리 180이에요.","180 ÷ 2 = 90이에요.","1시간에 90 km만큼 이동한 셈이에요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"유람선이 4시간 동안 36 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["기준량은 이동한 시간 4, 비교하는 양은 이동한 거리 36이에요.","36 ÷ 4 = 9예요.","1시간에 9 km만큼 이동한 셈이에요."]},{"stem":"자율 주행 자동차가 2시간 동안 160 km를 이동했어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["기준량은 이동한 시간 2, 비교하는 양은 이동한 거리 160이에요.","160 ÷ 2 = 80이에요.","1시간에 80 km만큼 이동한 셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#11','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C5',2,'sa','auto','수학 문제 40개 가운데 34개를 맞혔어요. 전체 문제 수에 대한 맞힌 문제 수의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"수학 문제 40개 가운데 34개를 맞혔어요. 전체 문제 수에 대한 맞힌 문제 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["기준량은 40, 비교하는 양은 34예요.","34 ÷ 40 × 100 = 85예요.","그래서 85 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"씨앗 50개를 심었더니 43개가 싹을 틔웠어요. 심은 씨앗 수에 대한 싹 튼 씨앗 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["86"],"explanation":["기준량은 50, 비교하는 양은 43이에요.","43 ÷ 50 × 100 = 86이에요.","그래서 86 %예요."]},{"stem":"우리 반 20명 가운데 15명이 이번 주에 도서관을 이용했어요. 전체 학생 수에 대한 이용한 학생 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["기준량은 20, 비교하는 양은 15예요.","15 ÷ 20 × 100 = 75예요.","그래서 75 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#12','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C5',2,'sa','auto','비율 ⟨9/20⟩를 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"비율 ⟨9/20⟩를 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 5를 곱해요.","⟨9/20⟩ = ⟨45/100⟩예요.","그래서 ⟨9/20⟩는 45 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"비율 ⟨13/20⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 5를 곱해요.","⟨13/20⟩ = ⟨65/100⟩예요.","그래서 ⟨13/20⟩은 65 %예요."]},{"stem":"비율 ⟨16/25⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 4를 곱해요.","⟨16/25⟩ = ⟨64/100⟩예요.","그래서 ⟨16/25⟩은 64 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#13','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C6',2,'sa','auto','필통은 원래 가격 8000원에서 2000원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"필통은 원래 가격 8000원에서 2000원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","2000 ÷ 8000 × 100 = 25예요.","할인율은 25 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"나 치약은 원래 가격 5000원에서 1400원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","1400 ÷ 5000 × 100 = 28이에요.","할인율은 28 %예요."]},{"stem":"가 치약은 원래 가격 3000원에서 900원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","900 ÷ 3000 × 100 = 30이에요.","할인율은 30 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#14','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C6',2,'sa','auto','민서는 설탕 45 g을 녹여 설탕물 300 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"민서는 설탕 45 g을 녹여 설탕물 300 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["기준량은 설탕물 300 g, 비교하는 양은 설탕 45 g이에요.","45 ÷ 300 × 100 = 15예요.","설탕물의 진하기는 15 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"하준은 설탕 24 g을 녹여 설탕물 150 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["기준량은 설탕물 150 g, 비교하는 양은 설탕 24 g이에요.","24 ÷ 150 × 100 = 16이에요.","설탕물의 진하기는 16 %예요."]},{"stem":"지후는 설탕 210 g을 녹여 설탕물 750 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["기준량은 설탕물 750 g, 비교하는 양은 설탕 210 g이에요.","210 ÷ 750 × 100 = 28이에요.","설탕물의 진하기는 28 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#15','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C5',2,'ox','auto','비율 0.07을 백분율로 나타내면 70 %예요.',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":15,"concept":"M6-1-u4-C5","difficulty":2,"kind":"ox","stem":"비율 0.07을 백분율로 나타내면 70 %예요.","answer":"X","reason_options":[{"t":"0.07 × 100 = 7이라 7 %이기 때문에","correct":true},{"t":"0.07의 7 뒤에 0을 붙이면 되기 때문에","mis":"M6-1-u4-X08"}],"mis":"M6-1-u4-X08","explanation":["기준량을 100으로 할 때의 비율을 백분율이라 하고 %를 써요.","비율에 100을 곱해서 나온 값에 %를 붙여요.","기준량이 100인 분수로 바꾸어도 돼요."],"variant_rule":{"alt":[{"stem":"할인율은 (할인된 가격) ÷ (원래 가격)으로 구해요.","answer":"X","reason_options":[{"t":"할인율은 원래 가격에 대한 할인 금액의 비율이기 때문에","correct":true},{"t":"할인된 가격이 비교하는 양이기 때문에","mis":"M6-1-u4-X10"}],"explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."]},{"stem":"3：4와 4：3은 같은 비예요.","answer":"X","reason_options":[{"t":"기준량이 4와 3으로 달라 서로 다른 비이기 때문에","correct":true},{"t":"두 비에 같은 수가 들어 있기 때문에","mis":"M6-1-u4-X02"}],"explanation":["두 양의 변하지 않는 관계를 기호 ：로 나타낸 것이 비예요.","：의 앞은 비교하는 양(전항), 뒤는 기준량(후항)이에요.","「○에 대한」 쪽이 기준량이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#16','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C7',2,'mc','auto','맑은 지역의 전체 발전량은 4200000 kWh이고 그중 10 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X16']::text[],true,'{"seq":16,"concept":"M6-1-u4-C7","difficulty":2,"kind":"mc","stem":"맑은 지역의 전체 발전량은 4200000 kWh이고 그중 10 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"420000 kWh","correct":true},{"t":"42000 kWh","mis":"M6-1-u4-X15"},{"t":"4200000 kWh","mis":"M6-1-u4-X15"},{"t":"3780000 kWh","mis":"M6-1-u4-X16"}],"explanation":["전체 4200000을 100칸으로 보면 한 칸은 4200000 ÷ 100 = 42000이에요.","10 %는 10칸이라 42000 × 10 = 420000이에요.","답은 420000 kWh예요."],"variant_rule":{"alt":[{"stem":"신재생 에너지 510000 kWh 가운데 30 %가 풍력 에너지예요. 풍력 발전량은 몇 kWh인가요?","options":[{"t":"153000 kWh","correct":true},{"t":"15300 kWh","mis":"M6-1-u4-X15"},{"t":"17000 kWh","mis":"M6-1-u4-X13"},{"t":"1530000 kWh","mis":"M6-1-u4-X15"}],"explanation":["전체 510000을 100칸으로 보면 한 칸은 510000 ÷ 100 = 5100이에요.","30 %는 30칸이라 5100 × 30 = 153000이에요.","답은 153000 kWh예요."]},{"stem":"행복 지역의 전체 발전량은 3400000 kWh이고 그중 15 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"510000 kWh","correct":true},{"t":"51000 kWh","mis":"M6-1-u4-X15"},{"t":"5100000 kWh","mis":"M6-1-u4-X15"},{"t":"2890000 kWh","mis":"M6-1-u4-X16"}],"explanation":["전체 3400000을 100칸으로 보면 한 칸은 3400000 ÷ 100 = 34000이에요.","15 %는 15칸이라 34000 × 15 = 510000이에요.","답은 510000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#17','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C4',3,'mc','auto','바 마을은 넓이 4 km²에 7200명, 마 마을은 넓이 6 km²에 9000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":17,"concept":"M6-1-u4-C4","difficulty":3,"kind":"mc","stem":"바 마을은 넓이 4 km²에 7200명, 마 마을은 넓이 6 km²에 9000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"바 마을","correct":true},{"t":"마 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","바 7200 ÷ 4 = 1800, 마 9000 ÷ 6 = 1500이에요.","비율이 큰 바 마을이 더 빽빽해요."],"variant_rule":{"alt":[{"stem":"사 마을은 넓이 8 km²에 12000명, 아 마을은 넓이 5 km²에 8000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"아 마을","correct":true},{"t":"사 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","사 12000 ÷ 8 = 1500, 아 8000 ÷ 5 = 1600이에요.","비율이 큰 아 마을이 더 빽빽해요."]},{"stem":"가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"가 마을","correct":true},{"t":"나 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","가 6000 ÷ 2 = 3000, 나 7500 ÷ 3 = 2500이에요.","비율이 큰 가 마을이 더 빽빽해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#18','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C5',3,'mc','auto','형은 공을 50번 차서 30번 넣었고, 나는 20번 차서 13번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":18,"concept":"M6-1-u4-C5","difficulty":3,"kind":"mc","stem":"형은 공을 50번 차서 30번 넣었고, 나는 20번 차서 13번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"나","correct":true},{"t":"형","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","형 30 ÷ 50 × 100 = 60, 나 13 ÷ 20 × 100 = 65예요.","형 60 %, 나 65 % — 나가 더 잘 넣었어요."],"variant_rule":{"alt":[{"stem":"지민은 공을 40번 차서 30번 넣었고, 태오는 25번 차서 20번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"태오","correct":true},{"t":"지민","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","지민 30 ÷ 40 × 100 = 75, 태오 20 ÷ 25 × 100 = 80이에요.","지민 75 %, 태오 80 % — 태오가 더 잘 넣었어요."]},{"stem":"나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"동생","correct":true},{"t":"나","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","나 12 ÷ 25 × 100 = 48, 동생 10 ÷ 20 × 100 = 50이에요.","나 48 %, 동생 50 % — 동생이 더 잘 넣었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#19','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C6',3,'sa','auto','모자는 원래 가격이 20000원인데 17000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M6-1-u4-C6","difficulty":3,"kind":"sa","stem":"모자는 원래 가격이 20000원인데 17000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 20000 − 17000 = 3000이에요.","3000 ÷ 20000 × 100 = 15예요.","할인율은 15 %예요."],"mis":"M6-1-u4-X10","variant_rule":{"alt":[{"stem":"우산은 원래 가격이 15000원인데 12000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 15000 − 12000 = 3000이에요.","3000 ÷ 15000 × 100 = 20이에요.","할인율은 20 %예요."]},{"stem":"운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 40000 − 30000 = 10000이에요.","10000 ÷ 40000 × 100 = 25예요.","할인율은 25 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#20','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C1',3,'sa','auto','가로 6 cm, 세로 4 cm인 직사각형을 모양 그대로 키웠더니 세로가 10 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M6-1-u4-C1","difficulty":3,"kind":"sa","stem":"가로 6 cm, 세로 4 cm인 직사각형을 모양 그대로 키웠더니 세로가 10 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 10 ÷ 4 = 2.5배가 되었어요.","가로도 6 × 2.5 = 15 (cm)예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"가로 8 cm, 세로 6 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 9 ÷ 6 = 1.5배가 되었어요.","가로도 8 × 1.5 = 12 (cm)예요."]},{"stem":"가로 5 cm, 세로 2 cm인 직사각형을 모양 그대로 키웠더니 세로가 6 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 6 ÷ 2 = 3배가 되었어요.","가로도 5 × 3 = 15 (cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#21','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C5',3,'error','auto','비율 ⟨16/25⟩을 백분율로 나타내는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X09','M6-1-u4-X16']::text[],true,'{"seq":21,"concept":"M6-1-u4-C5","difficulty":3,"kind":"error","stem":"비율 ⟨16/25⟩을 백분율로 나타내는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「분자가 16이니 16 %야.」","correct":true,"mis_target":"M6-1-u4-X09"},{"t":"나린 — 「⟨16/25⟩ = ⟨64/100⟩야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「16 ÷ 25 × 100 = 64야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량을 100으로 맞추어야 해요.","⟨16/25⟩ = ⟨64/100⟩ — 64 %예요.","가온은 분모를 100으로 고치지 않았어요."],"variant_rule":{"alt":[{"stem":"운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「30000 ÷ 40000 × 100 = 75니 75 %야.」","correct":true,"mis_target":"M6-1-u4-X10"},{"t":"라온 — 「할인 금액은 10000원이야.」","mis":"M6-1-u4-X16"},{"t":"예준 — 「할인율은 25 %야.」","mis":"M6-1-u4-X16"}],"explanation":["할인 금액은 40000 − 30000 = 10000이에요.","10000 ÷ 40000 × 100 = 25예요.","여울은 할인된 가격으로 계산했어요."]},{"stem":"바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「150：6이야.」","correct":true,"mis_target":"M6-1-u4-X01"},{"t":"이현 — 「기준량은 바닷물 양이야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「비는 6：150이야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량은 바닷물 양이에요.","비는 (비교하는 양)：(기준량) 차례라 6：150이에요.","준희는 기준량과 비교하는 양을 바꾸어 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#22','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C7',3,'mc','auto','전체 발전량 2000000 kWh의 20 %가 신재생 에너지이고, 신재생 에너지의 40 %가 수력이에요. 수력 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X14','M6-1-u4-X16']::text[],true,'{"seq":22,"concept":"M6-1-u4-C7","difficulty":3,"kind":"mc","stem":"전체 발전량 2000000 kWh의 20 %가 신재생 에너지이고, 신재생 에너지의 40 %가 수력이에요. 수력 발전량은 몇 kWh인가요?","options":[{"t":"160000 kWh","correct":true},{"t":"800000 kWh","mis":"M6-1-u4-X14"},{"t":"400000 kWh","mis":"M6-1-u4-X16"},{"t":"1200000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 2000000 × 20 ÷ 100 = 400000이에요.","기준량이 400000으로 바뀌어요 — 400000 × 40 ÷ 100 = 160000이에요.","답은 160000 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 5000000 kWh의 12 %가 신재생 에너지이고, 신재생 에너지의 25 %가 지열이에요. 지열 발전량은 몇 kWh인가요?","options":[{"t":"150000 kWh","correct":true},{"t":"1250000 kWh","mis":"M6-1-u4-X14"},{"t":"600000 kWh","mis":"M6-1-u4-X16"},{"t":"1850000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 5000000 × 12 ÷ 100 = 600000이에요.","기준량이 600000으로 바뀌어요 — 600000 × 25 ÷ 100 = 150000이에요.","답은 150000 kWh예요."]},{"stem":"전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 48 %가 태양광이에요. 태양광 발전량은 몇 kWh인가요?","options":[{"t":"244800 kWh","correct":true},{"t":"1632000 kWh","mis":"M6-1-u4-X14"},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"2142000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 3400000 × 15 ÷ 100 = 510000이에요.","기준량이 510000으로 바뀌어요 — 510000 × 48 ÷ 100 = 244800이에요.","답은 244800 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#23','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C7',4,'mc','auto','마 지역은 전체 발전량 1500000 kWh 가운데 30 %, 바 지역은 전체 발전량 2500000 kWh 가운데 20 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":23,"concept":"M6-1-u4-C7","difficulty":4,"kind":"mc","stem":"마 지역은 전체 발전량 1500000 kWh 가운데 30 %, 바 지역은 전체 발전량 2500000 kWh 가운데 20 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"바 지역","correct":true},{"t":"마 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","마 1500000 × 30 ÷ 100 = 450000, 바 2500000 × 20 ÷ 100 = 500000이에요.","발전량이 더 많은 곳은 바 지역이에요."],"variant_rule":{"alt":[{"stem":"사 지역은 전체 발전량 6000000 kWh 가운데 10 %, 아 지역은 전체 발전량 4000000 kWh 가운데 14 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"사 지역","correct":true},{"t":"아 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","사 6000000 × 10 ÷ 100 = 600000, 아 4000000 × 14 ÷ 100 = 560000이에요.","발전량이 더 많은 곳은 사 지역이에요."]},{"stem":"가 지역은 전체 발전량 2000000 kWh 가운데 20 %, 나 지역은 전체 발전량 3000000 kWh 가운데 15 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"나 지역","correct":true},{"t":"가 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","가 2000000 × 20 ÷ 100 = 400000, 나 3000000 × 15 ÷ 100 = 450000이에요.","발전량이 더 많은 곳은 나 지역이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#24','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C6',4,'essay','teacher','설탕 30 g을 물 120 g에 녹였어요. 친구는 이 설탕물의 진하기를 25 %라고 했어요. 바른 진하기를 구하고, 친구가 잘못한 점을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u4-C6","difficulty":4,"kind":"essay","stem":"설탕 30 g을 물 120 g에 녹였어요. 친구는 이 설탕물의 진하기를 25 %라고 했어요. 바른 진하기를 구하고, 친구가 잘못한 점을 설명해 보세요.","answer_guide":{"answer":"예: 설탕물은 물과 설탕을 합한 120 + 30 = 150 (g)이다. 진하기는 설탕물 양에 대한 설탕 양의 비율이므로 30 ÷ 150 × 100 = 20, 20 %이다. 친구는 기준량을 설탕물 150 g이 아니라 물 120 g으로 잘못 잡았다.","scoring_points":["설탕물 150 g을 구했는가","20 %를 구했는가","기준량을 물의 양으로 잘못 잡았다고 설명했는가"]},"explanation":["설탕물은 150 g이에요.","30 ÷ 150 × 100 = 20 — 20 %예요.","친구는 물의 양을 기준량으로 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#25','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C6',4,'essay','teacher','가 치약은 원래 가격 3000원에서 900원, 나 치약은 원래 가격 5000원에서 1400원을 할인해요. 두 치약의 할인율을 구해 비교하고, 할인 금액이 더 큰 나 치약의 할인율이 더 작은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u4-C6","difficulty":4,"kind":"essay","stem":"가 치약은 원래 가격 3000원에서 900원, 나 치약은 원래 가격 5000원에서 1400원을 할인해요. 두 치약의 할인율을 구해 비교하고, 할인 금액이 더 큰 나 치약의 할인율이 더 작은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 가 치약은 900 ÷ 3000 × 100 = 30이므로 30 %, 나 치약은 1400 ÷ 5000 × 100 = 28이므로 28 %이다. 할인율은 가 치약이 더 크다. 원래 가격(기준량)이 다르므로 할인 금액이 커도 원래 가격에 대한 비율은 작을 수 있다.","scoring_points":["30 %와 28 %를 구했는가","가 치약의 할인율이 더 크다고 비교했는가","원래 가격(기준량)이 달라서라는 까닭을 썼는가"]},"explanation":["가 30 %, 나 28 %예요.","가 치약의 할인율이 더 커요.","원래 가격이 달라 금액으로는 비교할 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#1','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C2',1,'mc','auto','치즈 4장과 달걀부침 3개로 샌드위치를 만들었어요. 치즈 수에 대한 달걀부침 수의 비는 어느 것인가요?',ARRAY['M6-1-u4-X01','M6-1-u4-X07','M6-1-u4-X03']::text[],true,'{"seq":1,"concept":"M6-1-u4-C2","difficulty":1,"kind":"mc","stem":"치즈 4장과 달걀부침 3개로 샌드위치를 만들었어요. 치즈 수에 대한 달걀부침 수의 비는 어느 것인가요?","options":[{"t":"3：4","correct":true},{"t":"4：3","mis":"M6-1-u4-X01"},{"t":"3：7","mis":"M6-1-u4-X07"},{"t":"1：4","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 치즈 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 3：4예요."],"variant_rule":{"alt":[{"stem":"바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 어느 것인가요?","options":[{"t":"6：150","correct":true},{"t":"150：6","mis":"M6-1-u4-X01"},{"t":"6：144","mis":"M6-1-u4-X03"},{"t":"25：1","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 바닷물 양이에요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 6：150이에요."]},{"stem":"팔찌 하나에 파란 구슬 2개와 노란 구슬 10개를 꿰어요. 파란 구슬 수와 노란 구슬 수의 비는 어느 것인가요?","options":[{"t":"2：10","correct":true},{"t":"10：2","mis":"M6-1-u4-X01"},{"t":"2：8","mis":"M6-1-u4-X03"},{"t":"5：1","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 노란 구슬 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 2：10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#2','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C2',1,'sa','auto','비 5：8에서 비교하는 양은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u4-C2","difficulty":1,"kind":"sa","stem":"비 5：8에서 비교하는 양은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","5：8에서 전항은 5, 후항은 8이에요.","그래서 비교하는 양은 5예요."],"mis":"M6-1-u4-X01","variant_rule":{"alt":[{"stem":"비 2：10에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","2：10에서 전항은 2, 후항은 10이에요.","그래서 기준량은 10이에요."]},{"stem":"비 9：20에서 후항은 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","9：20에서 전항은 9, 후항은 20이에요.","그래서 후항은 20이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#3','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C3',1,'mc','auto','비 7：20의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C3","difficulty":1,"kind":"mc","stem":"비 7：20의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.35","correct":true},{"t":"3.5","mis":"M6-1-u4-X15"},{"t":"0.035","mis":"M6-1-u4-X15"},{"t":"0.65","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","7：20의 비율은 7 ÷ 20 = 0.35예요.","분수로는 ⟨7/20⟩, 소수로는 0.35예요."],"variant_rule":{"alt":[{"stem":"비 3：10의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"3","mis":"M6-1-u4-X15"},{"t":"0.03","mis":"M6-1-u4-X15"},{"t":"0.7","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","3：10의 비율은 3 ÷ 10 = 0.3이에요.","분수로는 ⟨3/10⟩, 소수로는 0.3이에요."]},{"stem":"비 1：4의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.25","correct":true},{"t":"4","mis":"M6-1-u4-X05"},{"t":"2.5","mis":"M6-1-u4-X15"},{"t":"0.025","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","1：4의 비율은 1 ÷ 4 = 0.25예요.","분수로는 ⟨1/4⟩, 소수로는 0.25예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#4','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C4',1,'mc','auto','빨강 팀은 8경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X16','M6-1-u4-X07','M6-1-u4-X15']::text[],true,'{"seq":4,"concept":"M6-1-u4-C4","difficulty":1,"kind":"mc","stem":"빨강 팀은 8경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.75","correct":true},{"t":"0.25","mis":"M6-1-u4-X16"},{"t":"3","mis":"M6-1-u4-X07"},{"t":"7.5","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 8, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/8⟩ = 0.75예요.","빨강 팀의 비율은 0.75예요."],"variant_rule":{"alt":[{"stem":"푸른 팀은 15경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"2.5","mis":"M6-1-u4-X05"},{"t":"0.6","mis":"M6-1-u4-X16"},{"t":"4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 15, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/15⟩ = 0.4예요.","푸른 팀의 비율은 0.4예요."]},{"stem":"노란 팀은 20경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"0.7","mis":"M6-1-u4-X16"},{"t":"3","mis":"M6-1-u4-X15"},{"t":"0.03","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 20, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/20⟩ = 0.3이에요.","노란 팀의 비율은 0.3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#5','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C5',1,'mc','auto','비율 0.07을 백분율로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":5,"concept":"M6-1-u4-C5","difficulty":1,"kind":"mc","stem":"비율 0.07을 백분율로 나타내면 얼마인가요?","options":[{"t":"7 %","correct":true},{"t":"0.7 %","mis":"M6-1-u4-X08"},{"t":"0.07 %","mis":"M6-1-u4-X08"},{"t":"70 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.07 × 100 = 7이에요.","그래서 7 %예요."],"variant_rule":{"alt":[{"stem":"비율 0.35를 백분율로 나타내면 얼마인가요?","options":[{"t":"35 %","correct":true},{"t":"3.5 %","mis":"M6-1-u4-X08"},{"t":"0.35 %","mis":"M6-1-u4-X08"},{"t":"350 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.35 × 100 = 35예요.","그래서 35 %예요."]},{"stem":"비율 0.83을 백분율로 나타내면 얼마인가요?","options":[{"t":"83 %","correct":true},{"t":"8.3 %","mis":"M6-1-u4-X08"},{"t":"0.83 %","mis":"M6-1-u4-X08"},{"t":"830 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.83 × 100 = 83이에요.","그래서 83 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#6','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C6',1,'sa','auto','학급 회장 선거에서 전체 40표 가운데 도윤이 22표를 받았어요. 도윤의 득표율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C6","difficulty":1,"kind":"sa","stem":"학급 회장 선거에서 전체 40표 가운데 도윤이 22표를 받았어요. 도윤의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","22 ÷ 40 × 100 = 55예요.","도윤의 득표율은 55 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"학급 회장 선거에서 전체 30표 가운데 건우가 18표를 받았어요. 건우의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","18 ÷ 30 × 100 = 60이에요.","건우의 득표율은 60 %예요."]},{"stem":"학급 회장 선거에서 전체 30표 가운데 수빈이가 12표를 받았어요. 수빈이의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","12 ÷ 30 × 100 = 40이에요.","수빈이의 득표율은 40 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#7','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C7',1,'mc','auto','전체 발전량 4200000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":7,"concept":"M6-1-u4-C7","difficulty":1,"kind":"mc","stem":"전체 발전량 4200000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"42000 kWh","correct":true},{"t":"420000 kWh","mis":"M6-1-u4-X15"},{"t":"4200 kWh","mis":"M6-1-u4-X15"},{"t":"420000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","4200000 ÷ 100 = 42000이에요.","한 칸은 42000 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 3400000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"34000 kWh","correct":true},{"t":"340000 kWh","mis":"M6-1-u4-X15"},{"t":"3400 kWh","mis":"M6-1-u4-X15"},{"t":"340000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","3400000 ÷ 100 = 34000이에요.","한 칸은 34000 kWh예요."]},{"stem":"전체 발전량 2500000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"25000 kWh","correct":true},{"t":"250000 kWh","mis":"M6-1-u4-X15"},{"t":"2500 kWh","mis":"M6-1-u4-X15"},{"t":"250000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","2500000 ÷ 100 = 25000이에요.","한 칸은 25000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#8','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C1',1,'sa','auto','하늘색 물감 한 접시에는 흰색 물감 8방울과 파란색 물감 2방울이 들어가요. 나눗셈으로 비교하면 흰색 물감은 파란색 물감의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u4-C1","difficulty":1,"kind":"sa","stem":"하늘색 물감 한 접시에는 흰색 물감 8방울과 파란색 물감 2방울이 들어가요. 나눗셈으로 비교하면 흰색 물감은 파란색 물감의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","8 ÷ 2 = 4예요.","흰색 물감은 파란색 물감의 4배예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 나눗셈으로 비교하면 물은 매실 원액의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","4 ÷ 1 = 4예요.","물은 매실 원액의 4배예요."]},{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 나눗셈으로 비교하면 노란 구슬은 파란 구슬의 몇 배인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","10 ÷ 2 = 5예요.","노란 구슬은 파란 구슬의 5배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#9','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C3',2,'mc','auto','세계 환경의 날 기념 행사에 어린이 50명이 지원해서 9명이 당첨되었어요. 지원한 어린이 수에 대한 당첨된 어린이 수의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":9,"concept":"M6-1-u4-C3","difficulty":2,"kind":"mc","stem":"세계 환경의 날 기념 행사에 어린이 50명이 지원해서 9명이 당첨되었어요. 지원한 어린이 수에 대한 당첨된 어린이 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.18","correct":true},{"t":"0.82","mis":"M6-1-u4-X16"},{"t":"1.8","mis":"M6-1-u4-X15"},{"t":"0.018","mis":"M6-1-u4-X15"}],"explanation":["기준량은 50, 비교하는 양은 9예요.","9 ÷ 50 = 0.18이에요.","그래서 비율은 0.18이에요."],"variant_rule":{"alt":[{"stem":"집에서 할머니 댁까지는 20 km, 집에서 주유소까지는 8 km예요. 집과 할머니 댁 사이 거리에 대한 집과 주유소 사이 거리의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"2.5","mis":"M6-1-u4-X05"},{"t":"0.6","mis":"M6-1-u4-X16"},{"t":"4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 20, 비교하는 양은 8이에요.","8 ÷ 20 = 0.4예요.","그래서 비율은 0.4예요."]},{"stem":"가로 40 cm, 세로 24 cm인 태극기 액자가 있어요. 가로에 대한 세로의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.6","correct":true},{"t":"0.4","mis":"M6-1-u4-X16"},{"t":"6","mis":"M6-1-u4-X15"},{"t":"0.06","mis":"M6-1-u4-X15"}],"explanation":["기준량은 40, 비교하는 양은 24예요.","24 ÷ 40 = 0.6이에요.","그래서 비율은 0.6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#10','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C4',2,'sa','auto','유람선이 4시간 동안 36 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u4-C4","difficulty":2,"kind":"sa","stem":"유람선이 4시간 동안 36 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["기준량은 이동한 시간 4, 비교하는 양은 이동한 거리 36이에요.","36 ÷ 4 = 9예요.","1시간에 9 km만큼 이동한 셈이에요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"자율 주행 자동차가 2시간 동안 160 km를 이동했어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["기준량은 이동한 시간 2, 비교하는 양은 이동한 거리 160이에요.","160 ÷ 2 = 80이에요.","1시간에 80 km만큼 이동한 셈이에요."]},{"stem":"자전거로 3시간 동안 12 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["기준량은 이동한 시간 3, 비교하는 양은 이동한 거리 12예요.","12 ÷ 3 = 4예요.","1시간에 4 km만큼 이동한 셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#11','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C5',2,'sa','auto','씨앗 50개를 심었더니 43개가 싹을 틔웠어요. 심은 씨앗 수에 대한 싹 튼 씨앗 수의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"씨앗 50개를 심었더니 43개가 싹을 틔웠어요. 심은 씨앗 수에 대한 싹 튼 씨앗 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["86"],"explanation":["기준량은 50, 비교하는 양은 43이에요.","43 ÷ 50 × 100 = 86이에요.","그래서 86 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"우리 반 20명 가운데 15명이 이번 주에 도서관을 이용했어요. 전체 학생 수에 대한 이용한 학생 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["기준량은 20, 비교하는 양은 15예요.","15 ÷ 20 × 100 = 75예요.","그래서 75 %예요."]},{"stem":"전체 25칸인 모눈에서 16칸을 색칠했어요. 전체 모눈 수에 대한 색칠한 모눈 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["기준량은 25, 비교하는 양은 16이에요.","16 ÷ 25 × 100 = 64예요.","그래서 64 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#12','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C5',2,'sa','auto','비율 ⟨13/20⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"비율 ⟨13/20⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 5를 곱해요.","⟨13/20⟩ = ⟨65/100⟩예요.","그래서 ⟨13/20⟩은 65 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"비율 ⟨16/25⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 4를 곱해요.","⟨16/25⟩ = ⟨64/100⟩예요.","그래서 ⟨16/25⟩은 64 %예요."]},{"stem":"비율 ⟨3/4⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 25를 곱해요.","⟨3/4⟩ = ⟨75/100⟩예요.","그래서 ⟨3/4⟩은 75 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#13','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C6',2,'sa','auto','나 치약은 원래 가격 5000원에서 1400원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"나 치약은 원래 가격 5000원에서 1400원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","1400 ÷ 5000 × 100 = 28이에요.","할인율은 28 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"가 치약은 원래 가격 3000원에서 900원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","900 ÷ 3000 × 100 = 30이에요.","할인율은 30 %예요."]},{"stem":"공책은 원래 가격 2000원에서 300원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","300 ÷ 2000 × 100 = 15예요.","할인율은 15 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#14','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C6',2,'sa','auto','하준은 설탕 24 g을 녹여 설탕물 150 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"하준은 설탕 24 g을 녹여 설탕물 150 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["기준량은 설탕물 150 g, 비교하는 양은 설탕 24 g이에요.","24 ÷ 150 × 100 = 16이에요.","설탕물의 진하기는 16 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"지후는 설탕 210 g을 녹여 설탕물 750 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["기준량은 설탕물 750 g, 비교하는 양은 설탕 210 g이에요.","210 ÷ 750 × 100 = 28이에요.","설탕물의 진하기는 28 %예요."]},{"stem":"예은은 설탕 36 g을 녹여 설탕물 200 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["기준량은 설탕물 200 g, 비교하는 양은 설탕 36 g이에요.","36 ÷ 200 × 100 = 18이에요.","설탕물의 진하기는 18 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#15','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C6',2,'ox','auto','할인율은 (할인된 가격) ÷ (원래 가격)으로 구해요.',ARRAY['M6-1-u4-X10']::text[],true,'{"seq":15,"concept":"M6-1-u4-C6","difficulty":2,"kind":"ox","stem":"할인율은 (할인된 가격) ÷ (원래 가격)으로 구해요.","answer":"X","reason_options":[{"t":"할인율은 원래 가격에 대한 할인 금액의 비율이기 때문에","correct":true},{"t":"할인된 가격이 비교하는 양이기 때문에","mis":"M6-1-u4-X10"}],"mis":"M6-1-u4-X10","explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."],"variant_rule":{"alt":[{"stem":"3：4와 4：3은 같은 비예요.","answer":"X","reason_options":[{"t":"기준량이 4와 3으로 달라 서로 다른 비이기 때문에","correct":true},{"t":"두 비에 같은 수가 들어 있기 때문에","mis":"M6-1-u4-X02"}],"explanation":["두 양의 변하지 않는 관계를 기호 ：로 나타낸 것이 비예요.","：의 앞은 비교하는 양(전항), 뒤는 기준량(후항)이에요.","「○에 대한」 쪽이 기준량이에요."]},{"stem":"비율은 언제나 1보다 작아요.","answer":"X","reason_options":[{"t":"12：5의 비율 2.4처럼 비교하는 양이 더 크면 1보다 크기 때문에","correct":true},{"t":"비율은 전체의 일부만 나타내기 때문에","mis":"M6-1-u4-X06"}],"explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#16','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C7',2,'mc','auto','신재생 에너지 510000 kWh 가운데 30 %가 풍력 에너지예요. 풍력 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":16,"concept":"M6-1-u4-C7","difficulty":2,"kind":"mc","stem":"신재생 에너지 510000 kWh 가운데 30 %가 풍력 에너지예요. 풍력 발전량은 몇 kWh인가요?","options":[{"t":"153000 kWh","correct":true},{"t":"15300 kWh","mis":"M6-1-u4-X15"},{"t":"17000 kWh","mis":"M6-1-u4-X13"},{"t":"1530000 kWh","mis":"M6-1-u4-X15"}],"explanation":["전체 510000을 100칸으로 보면 한 칸은 510000 ÷ 100 = 5100이에요.","30 %는 30칸이라 5100 × 30 = 153000이에요.","답은 153000 kWh예요."],"variant_rule":{"alt":[{"stem":"행복 지역의 전체 발전량은 3400000 kWh이고 그중 15 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"510000 kWh","correct":true},{"t":"51000 kWh","mis":"M6-1-u4-X15"},{"t":"5100000 kWh","mis":"M6-1-u4-X15"},{"t":"2890000 kWh","mis":"M6-1-u4-X16"}],"explanation":["전체 3400000을 100칸으로 보면 한 칸은 3400000 ÷ 100 = 34000이에요.","15 %는 15칸이라 34000 × 15 = 510000이에요.","답은 510000 kWh예요."]},{"stem":"푸른 지역의 전체 발전량은 2500000 kWh이고 그중 20 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"500000 kWh","correct":true},{"t":"50000 kWh","mis":"M6-1-u4-X15"},{"t":"125000 kWh","mis":"M6-1-u4-X13"},{"t":"5000000 kWh","mis":"M6-1-u4-X15"}],"explanation":["전체 2500000을 100칸으로 보면 한 칸은 2500000 ÷ 100 = 25000이에요.","20 %는 20칸이라 25000 × 20 = 500000이에요.","답은 500000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#17','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C4',3,'mc','auto','사 마을은 넓이 8 km²에 12000명, 아 마을은 넓이 5 km²에 8000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":17,"concept":"M6-1-u4-C4","difficulty":3,"kind":"mc","stem":"사 마을은 넓이 8 km²에 12000명, 아 마을은 넓이 5 km²에 8000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"아 마을","correct":true},{"t":"사 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","사 12000 ÷ 8 = 1500, 아 8000 ÷ 5 = 1600이에요.","비율이 큰 아 마을이 더 빽빽해요."],"variant_rule":{"alt":[{"stem":"가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"가 마을","correct":true},{"t":"나 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","가 6000 ÷ 2 = 3000, 나 7500 ÷ 3 = 2500이에요.","비율이 큰 가 마을이 더 빽빽해요."]},{"stem":"다 마을은 넓이 4 km²에 10000명, 라 마을은 넓이 5 km²에 11000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"다 마을","correct":true},{"t":"라 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","다 10000 ÷ 4 = 2500, 라 11000 ÷ 5 = 2200이에요.","비율이 큰 다 마을이 더 빽빽해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#18','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C5',3,'mc','auto','지민은 공을 40번 차서 30번 넣었고, 태오는 25번 차서 20번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":18,"concept":"M6-1-u4-C5","difficulty":3,"kind":"mc","stem":"지민은 공을 40번 차서 30번 넣었고, 태오는 25번 차서 20번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"태오","correct":true},{"t":"지민","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","지민 30 ÷ 40 × 100 = 75, 태오 20 ÷ 25 × 100 = 80이에요.","지민 75 %, 태오 80 % — 태오가 더 잘 넣었어요."],"variant_rule":{"alt":[{"stem":"나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"동생","correct":true},{"t":"나","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","나 12 ÷ 25 × 100 = 48, 동생 10 ÷ 20 × 100 = 50이에요.","나 48 %, 동생 50 % — 동생이 더 잘 넣었어요."]},{"stem":"나는 공을 40번 차서 26번 넣었고, 동생은 20번 차서 14번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"동생","correct":true},{"t":"나","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","나 26 ÷ 40 × 100 = 65, 동생 14 ÷ 20 × 100 = 70이에요.","나 65 %, 동생 70 % — 동생이 더 잘 넣었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#19','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C6',3,'sa','auto','우산은 원래 가격이 15000원인데 12000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M6-1-u4-C6","difficulty":3,"kind":"sa","stem":"우산은 원래 가격이 15000원인데 12000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 15000 − 12000 = 3000이에요.","3000 ÷ 15000 × 100 = 20이에요.","할인율은 20 %예요."],"mis":"M6-1-u4-X10","variant_rule":{"alt":[{"stem":"운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 40000 − 30000 = 10000이에요.","10000 ÷ 40000 × 100 = 25예요.","할인율은 25 %예요."]},{"stem":"가방은 원래 가격이 25000원인데 20000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 25000 − 20000 = 5000이에요.","5000 ÷ 25000 × 100 = 20이에요.","할인율은 20 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#20','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C1',3,'sa','auto','가로 8 cm, 세로 6 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M6-1-u4-C1","difficulty":3,"kind":"sa","stem":"가로 8 cm, 세로 6 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 9 ÷ 6 = 1.5배가 되었어요.","가로도 8 × 1.5 = 12 (cm)예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 2 cm인 직사각형을 모양 그대로 키웠더니 세로가 6 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 6 ÷ 2 = 3배가 되었어요.","가로도 5 × 3 = 15 (cm)예요."]},{"stem":"가로 4 cm, 세로 3 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 9 ÷ 3 = 3배가 되었어요.","가로도 4 × 3 = 12 (cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#21','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C6',3,'error','auto','운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X10','M6-1-u4-X16']::text[],true,'{"seq":21,"concept":"M6-1-u4-C6","difficulty":3,"kind":"error","stem":"운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「30000 ÷ 40000 × 100 = 75니 75 %야.」","correct":true,"mis_target":"M6-1-u4-X10"},{"t":"라온 — 「할인 금액은 10000원이야.」","mis":"M6-1-u4-X16"},{"t":"예준 — 「할인율은 25 %야.」","mis":"M6-1-u4-X16"}],"explanation":["할인 금액은 40000 − 30000 = 10000이에요.","10000 ÷ 40000 × 100 = 25예요.","여울은 할인된 가격으로 계산했어요."],"variant_rule":{"alt":[{"stem":"바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「150：6이야.」","correct":true,"mis_target":"M6-1-u4-X01"},{"t":"이현 — 「기준량은 바닷물 양이야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「비는 6：150이야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량은 바닷물 양이에요.","비는 (비교하는 양)：(기준량) 차례라 6：150이에요.","준희는 기준량과 비교하는 양을 바꾸어 썼어요."]},{"stem":"비 9：50의 비율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「50 ÷ 9 = ⟨50/9⟩이야.」","correct":true,"mis_target":"M6-1-u4-X05"},{"t":"수아 — 「기준량은 50이야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「비율은 0.18이야.」","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","9 ÷ 50 = 0.18이에요.","서호는 기준량을 비교하는 양으로 나누었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#22','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C7',3,'mc','auto','전체 발전량 5000000 kWh의 12 %가 신재생 에너지이고, 신재생 에너지의 25 %가 지열이에요. 지열 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X14','M6-1-u4-X16']::text[],true,'{"seq":22,"concept":"M6-1-u4-C7","difficulty":3,"kind":"mc","stem":"전체 발전량 5000000 kWh의 12 %가 신재생 에너지이고, 신재생 에너지의 25 %가 지열이에요. 지열 발전량은 몇 kWh인가요?","options":[{"t":"150000 kWh","correct":true},{"t":"1250000 kWh","mis":"M6-1-u4-X14"},{"t":"600000 kWh","mis":"M6-1-u4-X16"},{"t":"1850000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 5000000 × 12 ÷ 100 = 600000이에요.","기준량이 600000으로 바뀌어요 — 600000 × 25 ÷ 100 = 150000이에요.","답은 150000 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 48 %가 태양광이에요. 태양광 발전량은 몇 kWh인가요?","options":[{"t":"244800 kWh","correct":true},{"t":"1632000 kWh","mis":"M6-1-u4-X14"},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"2142000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 3400000 × 15 ÷ 100 = 510000이에요.","기준량이 510000으로 바뀌어요 — 510000 × 48 ÷ 100 = 244800이에요.","답은 244800 kWh예요."]},{"stem":"전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 30 %가 풍력이에요. 풍력 발전량은 몇 kWh인가요?","options":[{"t":"153000 kWh","correct":true},{"t":"1020000 kWh","mis":"M6-1-u4-X14"},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"1530000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 3400000 × 15 ÷ 100 = 510000이에요.","기준량이 510000으로 바뀌어요 — 510000 × 30 ÷ 100 = 153000이에요.","답은 153000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#23','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C7',4,'mc','auto','사 지역은 전체 발전량 6000000 kWh 가운데 10 %, 아 지역은 전체 발전량 4000000 kWh 가운데 14 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":23,"concept":"M6-1-u4-C7","difficulty":4,"kind":"mc","stem":"사 지역은 전체 발전량 6000000 kWh 가운데 10 %, 아 지역은 전체 발전량 4000000 kWh 가운데 14 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"사 지역","correct":true},{"t":"아 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","사 6000000 × 10 ÷ 100 = 600000, 아 4000000 × 14 ÷ 100 = 560000이에요.","발전량이 더 많은 곳은 사 지역이에요."],"variant_rule":{"alt":[{"stem":"가 지역은 전체 발전량 2000000 kWh 가운데 20 %, 나 지역은 전체 발전량 3000000 kWh 가운데 15 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"나 지역","correct":true},{"t":"가 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","가 2000000 × 20 ÷ 100 = 400000, 나 3000000 × 15 ÷ 100 = 450000이에요.","발전량이 더 많은 곳은 나 지역이에요."]},{"stem":"다 지역은 전체 발전량 5000000 kWh 가운데 12 %, 라 지역은 전체 발전량 4000000 kWh 가운데 14 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"다 지역","correct":true},{"t":"라 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","다 5000000 × 12 ÷ 100 = 600000, 라 4000000 × 14 ÷ 100 = 560000이에요.","발전량이 더 많은 곳은 다 지역이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#24','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C5',4,'essay','teacher','나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 넣은 비율을 백분율로 구하고, 누가 더 잘 넣었는지 까닭과 함께 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u4-C5","difficulty":4,"kind":"essay","stem":"나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 넣은 비율을 백분율로 구하고, 누가 더 잘 넣었는지 까닭과 함께 설명해 보세요.","answer_guide":{"answer":"예: 찬 횟수를 100으로 맞추면 나는 25 × 4 = 100번 찼다면 12 × 4 = 48번, 동생은 20 × 5 = 100번 찼다면 10 × 5 = 50번 넣은 셈이다. 나는 48 %, 동생은 50 %이므로 동생이 더 잘 넣었다. 넣은 횟수는 내가 많지만 찬 횟수가 다르므로 백분율로 비교해야 한다.","scoring_points":["나 48 %·동생 50 %를 구했는가","동생이 더 잘 넣었다고 답했는가","찬 횟수가 달라 백분율로 비교해야 한다고 썼는가"]},"explanation":["나는 48 %, 동생은 50 %예요.","동생이 더 잘 넣었어요.","찬 횟수가 다르면 백분율로 비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#25','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C4',4,'essay','teacher','가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 「나 마을이 사람이 더 많으니 더 빽빽하다」는 말이 맞는지 넓이에 대한 인구의 비율을 구해 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u4-C4","difficulty":4,"kind":"essay","stem":"가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 「나 마을이 사람이 더 많으니 더 빽빽하다」는 말이 맞는지 넓이에 대한 인구의 비율을 구해 설명해 보세요.","answer_guide":{"answer":"예: 맞지 않다. 가 마을은 6000 ÷ 2 = 3000, 나 마을은 7500 ÷ 3 = 2500이다. 1 km²에 사는 사람이 가 마을이 더 많으므로 가 마을이 더 빽빽하다. 넓이가 다르면 인구 수가 아니라 넓이에 대한 인구의 비율로 비교해야 한다.","scoring_points":["3000과 2500을 구했는가","가 마을이 더 빽빽하다고 답했는가","기준(넓이)이 다르면 비율로 비교해야 한다고 썼는가"]},"explanation":["가 3000, 나 2500이에요.","가 마을이 더 빽빽해요.","넓이가 다르면 비율로 비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
